insert into public.products (id, market_id, category_slug, title, brand, image, price_minor, list_minor, deal_pct, deal, badge, bought_past_month, seller, ships_from, bullets, description, details, stock, position, variant_group, variant_axis, variant_label) values
  ('6181VJVcgSL', 'US', 'electronics', 'Hybrid Active Noise Cancelling Bluetooth Headphones, Over Ear, 120H Playtime', null, '/products/6181VJVcgSL.jpg', 10595, null, null, false, 'Overall Pick', null, 'Marketplace Seller', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'These over-ear wireless headphones use hybrid active noise cancelling to reduce engine hum, traffic, and office chatter so you can focus on music, podcasts, or calls. A long-lasting battery delivers up to 120 hours of playtime, and fast USB-C charging tops them up quickly. Bluetooth 5.3 keeps the connection stable up to 33 feet, while memory-foam ear cushions and a built-in microphone make them comfortable for all-day listening and hands-free calls.', '[["Brand","Generic"],["Form factor","Over-ear"],["Connectivity","Bluetooth 5.3"],["Noise control","Hybrid active noise cancellation"],["Battery life","Up to 120 hours"],["Charging port","USB-C"],["Microphone","Built-in"],["Wireless range","Up to 33 ft"]]'::jsonb, 307, 0, null, null, null),
  ('51CnDMbXZzL', 'US', 'electronics', 'Soundcore by Anker Q20i Hybrid Active Noise Cancelling Headphones, Bluetooth, Black', 'Soundcore', '/products/51CnDMbXZzL.jpg', 16800, null, null, false, null, '10K+ bought in past month', 'Amazon.com', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'The Soundcore Q20i by Anker pairs hybrid active noise cancellation with 40mm dynamic drivers and BassUp technology for full, punchy sound at home or on the go. Battery life reaches up to 40 hours with noise cancelling on and up to 60 hours with it off, and a quick USB-C charge adds hours of listening. Connect with an AUX cable for Hi-Res Audio playback, or fine-tune the sound in the Soundcore app.', '[["Brand","Soundcore"],["Model name","Q20i"],["Form factor","Over-ear"],["Connectivity","Bluetooth, 3.5 mm AUX"],["Noise control","Hybrid active noise cancellation"],["Battery life","Up to 40 hours (ANC on), 60 hours (ANC off)"],["Driver size","40 mm"],["Color","Black"]]'::jsonb, 4, 1, null, null, null),
  ('61hzm0JOv3L', 'US', 'electronics', 'MEETION Tri-Mode Wireless Office Headset with ENC Mic, 40mm Speaker, White', 'MEETION', '/products/61hzm0JOv3L.jpg', 12949, null, null, false, null, null, 'MEETION Official Store', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'Built for calls and video meetings, this MEETION office headset connects in three modes so you can switch between your computer, phone, and tablet as the workday demands. An ENC (environmental noise cancellation) microphone helps filter background noise so your voice comes through clearly, while 40mm speakers deliver full, detailed sound. Soft memory-foam ear cushions keep it comfortable through long shifts, and the clean white finish suits any desk setup.', '[["Brand","MEETION"],["Form factor","Over-ear headset"],["Connectivity","Tri-mode wireless"],["Microphone","ENC noise-cancelling mic"],["Speaker size","40 mm"],["Ideal for","Office calls and video meetings"],["Color","White"]]'::jsonb, 319, 2, null, null, null),
  ('71Hx8b6HGbL', 'US', 'electronics', 'KVIDIO Bluetooth Headphones Wireless Over Ear, 65H Playtime with Microphone', 'KVIDIO', '/products/71Hx8b6HGbL.jpg', 10300, 18699, 45, true, null, '1K+ bought in past month', 'Amazon.com', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'KVIDIO over-ear Bluetooth headphones deliver rich, bass-forward sound and up to 65 hours of playtime on a single charge, enough for weeks of commutes and workouts. Bluetooth 5.3 provides a stable wireless link up to 33 feet, and the built-in microphone handles hands-free calls. Memory-foam ear cushions and an adjustable headband keep the fit comfortable for long listening sessions at home, at work, or while traveling.', '[["Brand","KVIDIO"],["Form factor","Over-ear"],["Connectivity","Bluetooth 5.3"],["Battery life","Up to 65 hours"],["Microphone","Built-in"],["Wireless range","Up to 33 ft"],["Ear cushions","Memory foam"]]'::jsonb, 41, 3, null, null, null),
  ('61mcpfVlKVL', 'US', 'electronics', 'Bluetooth Headphones, Hybrid Active Noise Cancelling Over Ear, 35H Playtime', null, '/products/61mcpfVlKVL.jpg', 5195, null, null, false, null, '500+ bought in past month', 'Marketplace Seller', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'These over-ear Bluetooth headphones combine hybrid active noise cancelling with up to 35 hours of playtime, making them a practical companion for flights, commutes, and focused work. Bluetooth 5.3 keeps audio stable up to 33 feet, and fast USB-C charging gets you back to listening quickly. A built-in microphone supports hands-free calls, and cushioned memory-foam ear cups stay comfortable during long sessions.', '[["Brand","Generic"],["Form factor","Over-ear"],["Connectivity","Bluetooth 5.3"],["Noise control","Hybrid active noise cancellation"],["Battery life","Up to 35 hours"],["Charging port","USB-C"],["Microphone","Built-in"]]'::jsonb, 259, 4, null, null, null),
  ('61DzAvRWJlL', 'US', 'electronics', 'HAOYUYAN Wireless Earbuds, Sports Bluetooth Headphones, 80Hrs Playtime', 'HAOYUYAN', '/products/61DzAvRWJlL.jpg', 15195, 27199, 44, true, null, null, 'Marketplace Seller', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'HAOYUYAN wireless earbuds are designed for active days, with a sport-ready fit that stays put through runs, gym sessions, and bike rides. Combined with the charging case, they provide up to 80 hours of total playtime, and USB-C charging keeps the case topped up. Bluetooth 5.3 offers a stable connection up to 33 feet, and built-in microphones let you take calls without reaching for your phone.', '[["Brand","HAOYUYAN"],["Form factor","In-ear"],["Connectivity","Bluetooth 5.3"],["Battery life","Up to 80 hours with charging case"],["Charging port","USB-C"],["Microphone","Built-in"],["Ideal for","Sports and workouts"]]'::jsonb, 357, 5, null, null, null),
  ('61P4QAI28CL', 'US', 'electronics', 'Fhumsh Wireless Earbuds, Bluetooth 5.3 HiFi Stereo 50H Playback, LED Display', 'Fhumsh', '/products/61P4QAI28CL.jpg', 15949, null, null, false, null, '500+ bought in past month', 'Marketplace Seller', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'Fhumsh wireless earbuds deliver HiFi stereo sound over a stable Bluetooth 5.3 connection, with up to 50 hours of total playback when you include the charging case. An LED display on the case shows the remaining battery at a glance, so you always know when to recharge via USB-C. Built-in microphones support hands-free calls, and the lightweight in-ear design is comfortable for commutes, workouts, and everyday listening.', '[["Brand","Fhumsh"],["Form factor","In-ear"],["Connectivity","Bluetooth 5.3"],["Battery life","Up to 50 hours with charging case"],["Battery display","LED display on case"],["Charging port","USB-C"],["Microphone","Built-in"]]'::jsonb, 63, 6, 'fhumsh-a10-pro', 'Color', 'White'),
  ('61gS7RofWfL', 'US', 'electronics', 'SIMOLIO TV Headphones Wireless for Seniors with Bluetooth & Charging Dock', 'SIMOLIO', '/products/61gS7RofWfL.jpg', 7049, null, null, false, null, '1K+ bought in past month', 'Marketplace Seller', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'SIMOLIO wireless TV headphones help seniors and hard-of-hearing listeners enjoy television at their own volume without disturbing others in the room. Bluetooth connectivity carries audio to the headphones, and the included charging dock gives them a dedicated place to rest and recharge when not in use. Memory-foam cushions keep them comfortable during long movies, and a built-in microphone adds hands-free calling when paired with a phone.', '[["Brand","SIMOLIO"],["Form factor","Over-ear"],["Connectivity","Bluetooth"],["Ideal for","TV listening, seniors"],["Included components","Headphones, charging dock"],["Microphone","Built-in"]]'::jsonb, 389, 7, null, null, null),
  ('51rpbVmi9XL', 'US', 'electronics', 'Sony WH-CH720N Wireless Noise Cancelling Over-Ear Bluetooth Headphones, Black', 'Sony', '/products/51rpbVmi9XL.jpg', 2199, 3599, 39, true, null, '5K+ bought in past month', 'Amazon.com', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'The Sony WH-CH720N combines Sony''s noise cancelling technology with a lightweight over-ear design built for all-day comfort. An Integrated Processor V1 helps reduce ambient noise, while Ambient Sound mode lets you hear your surroundings when needed. Enjoy up to 35 hours of battery life with noise cancelling on, quick charging over USB-C, and multipoint connection to switch between two Bluetooth devices. The Sony Headphones Connect app lets you customize the EQ.', '[["Brand","Sony"],["Model name","WH-CH720N"],["Form factor","Over-ear"],["Connectivity","Bluetooth, multipoint"],["Noise control","Active noise cancellation"],["Battery life","Up to 35 hours (ANC on)"],["Charging port","USB-C"],["Color","Black"]]'::jsonb, 340, 8, null, null, null),
  ('41lArSiD5hL', 'US', 'electronics', 'Sony WH-CH520 Wireless On-Ear Bluetooth Headphones with Microphone, Black', 'Sony', '/products/41lArSiD5hL.jpg', 4949, null, null, false, null, '5K+ bought in past month', 'Sony Official Store', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'Sony WH-CH520 wireless on-ear headphones offer up to 50 hours of battery life, and a quick 3-minute charge provides up to 1.5 hours of playback. DSEE technology restores detail lost in compressed music files, and the Sony Headphones Connect app lets you tailor the sound with a customizable equalizer. Multipoint connection lets you pair two devices at once, and the built-in microphone makes hands-free calls easy.', '[["Brand","Sony"],["Model name","WH-CH520"],["Form factor","On-ear"],["Connectivity","Bluetooth, multipoint"],["Battery life","Up to 50 hours"],["Quick charge","3 minutes for up to 1.5 hours"],["Microphone","Built-in"],["Color","Black"]]'::jsonb, 292, 9, 'sony-wh-ch520', 'Color', 'Black'),
  ('71F2ccIPPLL', 'US', 'electronics', 'BERIBES Bluetooth Headphones Over Ear, HiFi Stereo Wireless Headset, 65H 6EQ', 'BERIBES', '/products/71F2ccIPPLL.jpg', 6049, null, null, false, 'Best Seller', '10K+ bought in past month', 'Amazon.com', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'BERIBES over-ear Bluetooth headphones deliver HiFi stereo sound with six EQ modes, so you can shift the sound profile for bass-heavy playlists, podcasts, or movies. The battery provides up to 65 hours of playtime, and Bluetooth 5.3 maintains a stable wireless connection up to 33 feet. Soft memory-foam ear cushions and a built-in microphone make them a comfortable choice for long listening sessions and hands-free calls.', '[["Brand","BERIBES"],["Form factor","Over-ear"],["Connectivity","Bluetooth 5.3"],["Battery life","Up to 65 hours"],["EQ modes","6"],["Microphone","Built-in"],["Wireless range","Up to 33 ft"]]'::jsonb, 372, 10, null, null, null),
  ('41JACWTwWL', 'US', 'electronics', 'Sony WH-CH520 Wireless On-Ear Bluetooth Headphones with Microphone, Blue', 'Sony', '/products/41JACWTwWL.jpg', 4700, null, null, false, null, '5K+ bought in past month', 'Sony Official Store', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'In a vibrant blue finish, the Sony WH-CH520 wireless on-ear headphones deliver up to 50 hours of battery life for days of listening between charges, and USB-C quick charging gets you back to your music fast. DSEE technology enhances compressed audio, while the Sony Headphones Connect app offers an adjustable equalizer. The lightweight design, multipoint pairing, and built-in microphone make them easy to use for music and calls.', '[["Brand","Sony"],["Model name","WH-CH520"],["Form factor","On-ear"],["Connectivity","Bluetooth, multipoint"],["Battery life","Up to 50 hours"],["Charging port","USB-C"],["Microphone","Built-in"],["Color","Blue"]]'::jsonb, 147, 11, 'sony-wh-ch520', 'Color', 'Blue'),
  ('61Vg5tvG7pL', 'US', 'electronics', 'Wireless Earbuds Bluetooth Headphones, 54H Playtime Stereo with ENC Mic', null, '/products/61Vg5tvG7pL.jpg', 11500, null, null, false, null, null, 'Marketplace Seller', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'These wireless earbuds deliver balanced stereo sound and up to 54 hours of total playtime with the charging case, covering long travel days and busy work weeks. ENC microphones help reduce background noise on calls so your voice stays clear. Bluetooth 5.3 keeps the connection stable up to 33 feet, and fast USB-C charging quickly refills the compact case between uses.', '[["Brand","Generic"],["Form factor","In-ear"],["Connectivity","Bluetooth 5.3"],["Battery life","Up to 54 hours with charging case"],["Microphone","ENC noise-reducing mics"],["Charging port","USB-C"],["Wireless range","Up to 33 ft"]]'::jsonb, 143, 12, null, null, null),
  ('61gTcutSYML', 'US', 'electronics', 'Hybrid ANC Wireless Over-Ear Headphones, 100H Playtime, Hi-Res Audio', null, '/products/61gTcutSYML.jpg', 2900, null, null, false, null, null, 'Marketplace Seller', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'These over-ear wireless headphones pair hybrid active noise cancellation with Hi-Res Audio support for clear highs and deep, punchy bass. A single charge delivers up to 100 hours of playtime, so you can go days or even weeks between charges. Bluetooth 5.3 provides a stable wireless link up to 33 feet, and memory-foam ear cushions and a built-in microphone keep long listening sessions and calls comfortable.', '[["Brand","Generic"],["Form factor","Over-ear"],["Connectivity","Bluetooth 5.3"],["Noise control","Hybrid active noise cancellation"],["Battery life","Up to 100 hours"],["Audio","Hi-Res Audio"],["Microphone","Built-in"]]'::jsonb, 248, 13, null, null, null),
  ('61PPiCaslSL', 'US', 'electronics', 'Wireless Earbuds, Bluetooth 5.4 Headphones HiFi Stereo, Touch Control, White', null, '/products/61PPiCaslSL.jpg', 12199, 19099, 36, true, null, null, 'Marketplace Seller', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'These white wireless earbuds use Bluetooth 5.4 for fast pairing and a stable connection, delivering HiFi stereo sound with deep bass for music, videos, and calls. Touch controls on each earbud let you play, pause, skip tracks, and answer calls without reaching for your phone. Built-in microphones support hands-free conversations, and the compact charging case slips easily into a pocket or bag.', '[["Brand","Generic"],["Form factor","In-ear"],["Connectivity","Bluetooth 5.4"],["Controls","Touch"],["Audio","HiFi stereo"],["Microphone","Built-in"],["Color","White"]]'::jsonb, 181, 14, null, null, null),
  ('714leNyXHIL', 'US', 'electronics', 'Picun B8 Wireless Bluetooth Headphones, 120H Playtime, 3EQ Modes, Black', 'Picun', '/products/714leNyXHIL.jpg', 12799, null, null, false, null, '500+ bought in past month', 'Amazon.com', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'The Picun B8 wireless over-ear headphones offer up to 120 hours of playtime, so a single charge can last through weeks of daily listening. Three EQ modes let you switch between sound profiles for different kinds of music and content, while deep, punchy bass adds impact. Bluetooth 5.3 keeps the connection steady up to 33 feet, and a built-in microphone and memory-foam ear cushions make calls and long sessions comfortable.', '[["Brand","Picun"],["Model name","B8"],["Form factor","Over-ear"],["Connectivity","Bluetooth 5.3"],["Battery life","Up to 120 hours"],["EQ modes","3"],["Microphone","Built-in"],["Color","Black"]]'::jsonb, 69, 15, null, null, null),
  ('61D5ZCSIymL', 'US', 'electronics', 'Fhumsh Wireless Earbuds, Bluetooth 5.3 HiFi Stereo 50H Playback, LED, Deep Bass', 'Fhumsh', '/products/61D5ZCSIymL.jpg', 7049, null, null, false, null, null, 'Marketplace Seller', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'These Fhumsh wireless earbuds are tuned for deep bass and HiFi stereo sound, with Bluetooth 5.3 providing quick pairing and a stable connection. The charging case extends total playback to up to 50 hours, and its LED display shows remaining battery so you are never caught off guard. USB-C charging, built-in microphones for calls, and a lightweight in-ear fit make them easy to carry and wear every day.', '[["Brand","Fhumsh"],["Form factor","In-ear"],["Connectivity","Bluetooth 5.3"],["Battery life","Up to 50 hours with charging case"],["Battery display","LED display on case"],["Sound","Deep bass, HiFi stereo"],["Charging port","USB-C"]]'::jsonb, 28, 16, 'fhumsh-a10-pro', 'Color', 'Black'),
  ('51Yya2WtvkL', 'US', 'electronics', 'Soundcore by Anker P20i True Wireless Earbuds, Bluetooth, Big Bass, 30H Playtime', 'Soundcore', '/products/51Yya2WtvkL.jpg', 10500, 12799, 18, true, 'Best Seller', '10K+ bought in past month', 'Soundcore Official Store', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'Soundcore P20i true wireless earbuds by Anker use 10mm drivers with BassUp technology for powerful, bass-rich sound. They deliver up to 30 hours of total playtime with the charging case, and a quick 10-minute charge adds about two hours of listening. An IPX5 water-resistance rating handles sweat and splashes, and the Soundcore app provides EQ presets. A built-in lanyard makes the compact case easy to carry.', '[["Brand","Soundcore"],["Model name","P20i"],["Form factor","In-ear"],["Connectivity","Bluetooth 5.3"],["Battery life","Up to 30 hours with charging case"],["Driver size","10 mm"],["Water resistance","IPX5"]]'::jsonb, 39, 17, null, null, null),
  ('814jNKVFgL', 'US', 'electronics', 'TOZO A1 Wireless Earbuds Bluetooth 5.3, Lightweight In-Ear Headphones, IPX5', 'TOZO', '/products/814jNKVFgL.jpg', 4799, null, null, false, null, '10K+ bought in past month', 'Marketplace Seller', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'TOZO A1 wireless earbuds are designed to be lightweight and compact, with a comfortable in-ear fit for all-day wear. Bluetooth 5.3 provides quick pairing and a stable connection, while deep, punchy bass brings energy to music and videos. An IPX5 water-resistance rating protects against sweat and light rain during workouts, and built-in microphones support clear hands-free calls. The small charging case slips easily into a pocket.', '[["Brand","TOZO"],["Model name","A1"],["Form factor","In-ear"],["Connectivity","Bluetooth 5.3"],["Water resistance","IPX5"],["Microphone","Built-in"],["Ideal for","Everyday listening, workouts"]]'::jsonb, 308, 18, null, null, null),
  ('51013C6va8L', 'US', 'electronics', 'Soundcore P30i by Anker Noise Cancelling Wireless Earbuds, 45H Playtime', 'Soundcore', '/products/51013C6va8L.jpg', 1899, 2299, 17, true, 'Best Seller', '10K+ bought in past month', 'Soundcore Official Store', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'Soundcore P30i earbuds by Anker bring active noise cancelling to a compact, lightweight design, helping reduce the rumble of commutes and busy offices. With the charging case, they deliver up to 45 hours of total playtime, and fast USB-C charging keeps them ready to go. A stable Bluetooth connection and built-in microphones handle music and hands-free calls, while the Soundcore app lets you adjust EQ and noise cancelling settings.', '[["Brand","Soundcore"],["Model name","P30i"],["Form factor","In-ear"],["Connectivity","Bluetooth"],["Noise control","Active noise cancellation"],["Battery life","Up to 45 hours with charging case"],["Charging port","USB-C"],["Microphone","Built-in"]]'::jsonb, 99, 19, null, null, null),
  ('71fEWG6n4aL', 'US', 'electronics', 'Soundcore P31i by Anker Wireless Earbuds with Real-Time Adaptive ANC', 'Soundcore', '/products/71fEWG6n4aL.jpg', 15100, null, null, false, null, '5K+ bought in past month', 'Soundcore Official Store', 'Amazon', array['Immersive Hi-Res sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear']::text[], 'Soundcore P31i wireless earbuds by Anker feature real-time adaptive active noise cancellation, which continuously adjusts to your surroundings to reduce distracting sound on trains, in cafes, and at the office. Deep, punchy bass and clear detail bring energy to music and podcasts. A stable Bluetooth connection, built-in microphones for hands-free calls, and a compact charging case make them easy to use throughout the day.', '[["Brand","Soundcore"],["Model name","P31i"],["Form factor","In-ear"],["Connectivity","Bluetooth"],["Noise control","Real-time adaptive ANC"],["Microphone","Built-in"],["Included components","Earbuds, charging case"]]'::jsonb, 299, 20, null, null, null),
  ('51QEHqsjzPL', 'US', 'electronics', 'Samsung Galaxy Buds 4 Pro AI True Wireless Bluetooth Earbuds, Black', 'Samsung', '/products/51QEHqsjzPL.jpg', 12699, 19999, 37, true, null, '1K+ bought in past month', 'Marketplace Seller', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 33 ft', 'Built-in microphone for hands-free calls', 'Comfortable memory-foam ear cushions for all-day wear', 'Fast USB-C charging — a quick charge gives hours of play']::text[], 'Samsung Galaxy Buds 4 Pro true wireless earbuds are designed to work seamlessly with Galaxy devices, bringing Galaxy AI features to your everyday listening. Active noise cancellation helps block out distractions, while a secure in-ear fit keeps them comfortable for long sessions. Built-in microphones support clear hands-free calls, and fast USB-C charging keeps the compact case ready for the day ahead. This pair comes in a sleek black finish.', '[["Brand","Samsung"],["Model name","Galaxy Buds 4 Pro"],["Form factor","In-ear"],["Connectivity","Bluetooth"],["Noise control","Active noise cancellation"],["Charging port","USB-C"],["Color","Black"]]'::jsonb, 204, 21, null, null, null),
  ('81RFGfu0skL', 'US', 'computers', 'HP Essential Laptop 2026, Intel CPU, 128GB Storage, Office 365, Copilot AI, Windows 11', 'HP', '/products/81RFGfu0skL.jpg', 121949, null, null, false, null, null, 'HP Official Store', 'Amazon', array['Crisp Full-HD display with anti-glare coating', 'All-day battery life keeps you unplugged for longer', 'Fast SSD storage boots in seconds', 'Backlit keyboard and precision touchpad']::text[], 'The HP Essential Laptop is an everyday notebook for schoolwork, email, browsing, and streaming. It runs Windows 11 with Copilot AI assistance built in and comes with Office 365, so you can start on documents, spreadsheets, and presentations right away. An Intel processor and 128GB of fast storage keep the system responsive, while a Full-HD anti-glare display, backlit keyboard, and all-day battery support work from anywhere.', '[["Brand","HP"],["Series","HP Essential"],["Model year","2026"],["Processor","Intel"],["Storage","128 GB"],["Operating system","Windows 11"],["Software included","Office 365"],["AI features","Microsoft Copilot"]]'::jsonb, 5, 22, null, null, null),
