  ('818LlGeUuzL', 'US', 'home-kitchen', 'CAROTE 26pcs Pots and Pans Set, Nonstick Cookware Sets, Non Stick Kitchen', 'CAROTE', '/products/818LlGeUuzL.jpg', 10600, 12799, 17, true, null, '100+ bought in past month', 'CAROTE Official Store', 'Amazon', array['Even heat distribution with a sturdy aluminum core', 'Stay-cool ergonomic handles for a secure grip', 'Oven and dishwasher safe for effortless cooking', 'Complete set covers every everyday cooking need']::text[], 'This CAROTE 26-piece cookware set outfits a kitchen with nonstick pots, pans, and accessories for everyday cooking. A sturdy aluminum core spreads heat evenly to reduce hot spots, while the nonstick coating releases eggs, pancakes, and sauces easily and wipes clean quickly. Stay-cool ergonomic handles provide a secure grip, and the set is oven and dishwasher safe for convenient cooking and cleanup.', '[["Brand","CAROTE"],["Material","Aluminum with nonstick coating"],["Pieces","26"],["Coating","Nonstick"],["Handle","Stay-cool ergonomic"],["Dishwasher safe","Yes"],["Oven safe","Yes"]]'::jsonb, 284, 36, null, null, null),
