  ('71huXWZdTL', 'US', 'beauty', 'Sakura Skin Care Set for Kids & Teens, 6 PCS Gentle Routine', 'Sakura', '/products/71huXWZdTL.jpg', 3299, null, null, false, null, '100+ bought in past month', 'Amazon.com', 'Amazon', array['Deeply hydrates and restores a healthy glow', 'Travel-friendly sizes — perfect for on the go', 'Free from parabens and harsh sulfates', 'Suitable for all skin types, including sensitive']::text[], 'This Sakura skincare set gives kids and teens a simple, gentle six-piece routine for building healthy skin habits early. The mild formulas help cleanse, hydrate, and restore a fresh, healthy glow, and they are free from parabens and harsh sulfates. Suitable for all skin types, including sensitive, the travel-friendly sizes also make the set easy to pack for sleepovers, camps, and family trips.', '[["Brand","Sakura"],["Item form","Skincare set"],["Pieces","6"],["Intended for","Kids and teens"],["Skin type","All, including sensitive"],["Free from","Parabens, harsh sulfates"],["Size","Travel size"]]'::jsonb, 140, 71, null, null, null),
  ('91iUn61g79L', 'US', 'beauty', 'Vitamin C Niacinamide Skincare Set, Daily Facial Care Routine, 6-Piece', null, '/products/91iUn61g79L.jpg', 6800, null, null, false, null, '500+ bought in past month', 'Amazon.com', 'Amazon', array['Deeply hydrates and restores a healthy glow', 'Travel-friendly sizes — perfect for on the go', 'Free from parabens and harsh sulfates', 'Suitable for all skin types, including sensitive']::text[], 'This six-piece skincare set builds a complete daily facial routine around vitamin C and niacinamide, two popular ingredients for a brighter, more even-looking complexion. The coordinated products help cleanse, hydrate, and restore a healthy glow, and the formulas are free from parabens and harsh sulfates. Suitable for all skin types, including sensitive, the travel-friendly sizes make it easy to stay consistent at home or on the go.', '[["Brand","Generic"],["Item form","Skincare set"],["Pieces","6"],["Key ingredients","Vitamin C, niacinamide"],["Skin type","All, including sensitive"],["Use","Daily brightening and hydration"]]'::jsonb, 53, 72, null, null, null),
