  ('51jDWarkrL', 'US', 'beauty', 'BYOMA So Hydrated Travel Size Gift Set, Skincare Minis Bundle', 'BYOMA', '/products/51jDWarkrL.jpg', 3749, 5299, 29, true, 'Overall Pick', null, 'BYOMA Official Store', 'Amazon', array['Gentle, dermatologist-tested formula for daily use', 'Deeply hydrates and restores a healthy glow', 'Travel-friendly sizes — perfect for on the go', 'Free from parabens and harsh sulfates']::text[], 'The BYOMA So Hydrated Travel Size Gift Set bundles hydrating skincare minis into a compact kit that is ready for gifting or travel. BYOMA formulas are built around a barrier lipid complex of ceramides, cholesterol, and fatty acids that helps support a healthy skin barrier while delivering lasting moisture. Gentle and dermatologist-tested for daily use, the minis are free from parabens and harsh sulfates.', '[["Brand","BYOMA"],["Item form","Mini skincare set"],["Key ingredients","Ceramides, cholesterol, fatty acids"],["Size","Travel size"],["Use","Barrier support and hydration"],["Testing","Dermatologist-tested"],["Ideal for","Gifting and travel"]]'::jsonb, 186, 74, null, null, null),
  ('61245ffGcNL', 'US', 'beauty', 'LANEIGE Water Bank Blue Hyaluronic Cream Moisturizer for Combination Skin', 'LANEIGE', '/products/61245ffGcNL.jpg', 2700, 3599, 25, true, null, '1K+ bought in past month', 'Amazon.com', 'Amazon', array['Deeply hydrates and restores a healthy glow', 'Travel-friendly sizes — perfect for on the go', 'Free from parabens and harsh sulfates', 'Suitable for all skin types, including sensitive']::text[], 'LANEIGE Water Bank Blue Hyaluronic Cream Moisturizer delivers lightweight, long-lasting hydration formulated with Blue Hyaluronic Acid to help skin look plump, smooth, and dewy. This version is designed for combination skin, balancing moisture without a heavy feel. Use it morning and night after serums as the final step of your routine. The formula is free from parabens and harsh sulfates and suitable for sensitive skin.', '[["Brand","LANEIGE"],["Collection","Water Bank"],["Item form","Cream"],["Key ingredients","Blue Hyaluronic Acid"],["Skin type","Combination"],["Use","Daily moisturizer"]]'::jsonb, 264, 75, null, null, null),
  ('71KVCB7vltL', 'US', 'beauty', 'QUIYUM Daily Skincare Set for Young Women, 6-Piece Facial Care Kit', 'QUIYUM', '/products/71KVCB7vltL.jpg', 5649, null, null, false, 'Overall Pick', '500+ bought in past month', 'Marketplace Seller', 'Amazon', array['Deeply hydrates and restores a healthy glow', 'Travel-friendly sizes — perfect for on the go', 'Free from parabens and harsh sulfates', 'Suitable for all skin types, including sensitive']::text[], 'The QUIYUM daily skincare set gives young women a straightforward six-piece facial care routine in one kit. The coordinated products help cleanse, hydrate, and restore a healthy glow, making it easy to build a consistent morning and evening routine. Free from parabens and harsh sulfates and suitable for all skin types, including sensitive, the set also comes in travel-friendly sizes for trips and gym bags.', '[["Brand","QUIYUM"],["Item form","Facial care kit"],["Pieces","6"],["Intended for","Young women"],["Skin type","All, including sensitive"],["Free from","Parabens, harsh sulfates"],["Use","Daily hydration"]]'::jsonb, 4, 76, null, null, null),
  ('61TuwUQqvL', 'US', 'beauty', 'CeraVe PM Daily Facial Moisturizer for Dry Skin, Oil-Free, 3 oz', 'CeraVe', '/products/61TuwUQqvL.jpg', 5899, null, null, false, 'Best Seller', '10K+ bought in past month', 'Amazon.com', 'Amazon', array['Gentle, dermatologist-tested formula for daily use', 'Deeply hydrates and restores a healthy glow', 'Travel-friendly sizes — perfect for on the go', 'Free from parabens and harsh sulfates']::text[], 'CeraVe PM Facial Moisturizing Lotion is a lightweight, oil-free nighttime moisturizer developed with dermatologists. It combines three essential ceramides, hyaluronic acid, and niacinamide to help restore the skin''s protective barrier, retain moisture, and calm the look of skin overnight. Patented MVE technology releases moisturizing ingredients over time, and the fragrance-free, non-comedogenic formula absorbs quickly without clogging pores. This bottle holds 3 oz.', '[["Brand","CeraVe"],["Item form","Lotion"],["Skin type","Normal to dry"],["Key ingredients","Ceramides, hyaluronic acid, niacinamide"],["Size","3 oz"],["Use","Nighttime facial moisturizer"],["Formulation","Oil-free, fragrance-free, non-comedogenic"]]'::jsonb, 68, 77, null, null, null),
  ('61e5JrJtCL', 'US', 'beauty', 'Glow Recipe Glass Skin Essential Korean Skincare Kit, Serum + Toner', 'Glow Recipe', '/products/61e5JrJtCL.jpg', 6549, 10699, 39, true, null, '100+ bought in past month', 'Marketplace Seller', 'Amazon', array['Gentle, dermatologist-tested formula for daily use', 'Deeply hydrates and restores a healthy glow', 'Travel-friendly sizes — perfect for on the go', 'Free from parabens and harsh sulfates']::text[], 'The Glow Recipe Glass Skin Essential Kit pairs a toner and a serum to help you achieve the dewy, luminous glass-skin look popularized by Korean skincare. The toner preps skin to absorb what follows, while the serum layers on hydration for a bouncy, radiant finish. Gentle and dermatologist-tested for daily use, the formulas are free from parabens and harsh sulfates, and the travel-friendly sizes are easy to take along.', '[["Brand","Glow Recipe"],["Item form","Toner and serum"],["Skin type","All"],["Use","Hydration and glow"],["Size","Travel size"],["Testing","Dermatologist-tested"]]'::jsonb, 335, 78, null, null, null),
  ('71CssT5FzsL', 'US', 'beauty', 'IUNIK Beta-Glucan Edition Skincare Set, Cream 2.02 oz & Serum 0.51 oz', 'IUNIK', '/products/71CssT5FzsL.jpg', 5700, 9299, 39, true, null, null, 'Amazon.com', 'Amazon', array['Deeply hydrates and restores a healthy glow', 'Travel-friendly sizes — perfect for on the go', 'Free from parabens and harsh sulfates', 'Suitable for all skin types, including sensitive']::text[], 'The IUNIK Beta-Glucan Edition skincare set pairs a moisturizing cream and a lightweight serum built around beta-glucan, an ingredient valued for deep hydration and soothing comfort. Layer the serum first to quench dry skin, then seal in moisture with the cream for a soft, healthy glow. The set includes a 2.02 oz cream and a 0.51 oz serum, and the formulas are suitable for all skin types, including sensitive.', '[["Brand","IUNIK"],["Item form","Cream and serum"],["Key ingredients","Beta-glucan"],["Size","2.02 oz cream, 0.51 oz serum"],["Skin type","All, including sensitive"],["Origin","Korean skincare"],["Use","Hydration and soothing"]]'::jsonb, 51, 79, null, null, null),
  ('71XJ8ORYxCL', 'US', 'beauty', 'Tower 28 SOS Recovery Hydrating Face Cream for Sensitive Skin, 1.86 oz', 'Tower 28', '/products/71XJ8ORYxCL.jpg', 5599, null, null, false, null, null, 'Marketplace Seller', 'Amazon', array['Gentle, dermatologist-tested formula for daily use', 'Deeply hydrates and restores a healthy glow', 'Travel-friendly sizes — perfect for on the go', 'Free from parabens and harsh sulfates']::text[], 'Tower 28 SOS Recovery Hydrating Face Cream is formulated for sensitive skin, delivering rich, comforting moisture that helps calm the look of redness and dryness. Part of the brand''s SOS line for stressed skin, the gentle, dermatologist-tested cream is designed for everyday use morning and night. It is free from parabens and harsh sulfates and comes in a 1.86 oz size that fits easily into a daily routine.', '[["Brand","Tower 28"],["Collection","SOS"],["Item form","Cream"],["Skin type","Sensitive"],["Size","1.86 oz"],["Use","Daily hydration and recovery"],["Testing","Dermatologist-tested"]]'::jsonb, 284, 80, null, null, null),
  ('81P0NvoRrWL', 'US', 'books', 'Theo of Golden: A Novel', 'Allen Levi', '/products/81P0NvoRrWL.jpg', 2599, null, null, false, 'Amazon''s Choice', '1K+ bought in past month', 'Marketplace Seller', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'In the quiet Southern town of Golden, an elderly stranger named Theo arrives and discovers dozens of charcoal portraits of local residents hanging in a neighborhood coffee shop. He quietly buys them one by one and begins giving each portrait to the person it depicts, sparking unexpected conversations and connections. This gentle, reflective novel explores kindness, faith, art, and the ways small acts of attention can change a community.', '[["Author","Allen Levi"],["Format","Paperback"],["Language","English"],["Genre","Literary fiction"],["Setting","The town of Golden"],["Themes","Kindness, community, art"]]'::jsonb, 66, 81, null, null, null),
  ('81gOlbDWpeL', 'US', 'books', 'Yesteryear: A GMA Book Club Pick — A Novel', 'Caro Claire Burke', '/products/81gOlbDWpeL.jpg', 1795, null, null, false, null, '1K+ bought in past month', 'Marketplace Seller', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Yesteryear follows Natalie Mills, a wildly popular influencer whose carefully curated videos celebrate an old-fashioned, homesteading life on her family''s farm. When she wakes one morning to find that the nostalgic past she performs for her followers has somehow become her reality, she must survive without the modern comforts she quietly relied on. Sharp and suspenseful, the novel examines performance, nostalgia, and the cost of romanticizing the past.', '[["Author","Caro Claire Burke"],["Format","Paperback"],["Language","English"],["Genre","Fiction, suspense"],["Book club","GMA Book Club pick"],["Themes","Nostalgia, social media, identity"]]'::jsonb, 353, 82, null, null, null),
  ('71oqUYvuOL', 'US', 'books', 'Verity', 'Colleen Hoover', '/products/71oqUYvuOL.jpg', 1799, null, null, false, null, '10K+ bought in past month', 'Amazon.com', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Struggling writer Lowen Ashleigh accepts a lucrative offer to finish the remaining books in a hit series by Verity Crawford, a bestselling author left unable to write after an accident. Staying in the Crawford home to sort through Verity''s notes, Lowen uncovers an unfinished autobiography filled with chilling admissions never meant to be read. As she grows closer to Verity''s husband, Jeremy, Lowen must decide what to believe in this dark psychological thriller.', '[["Author","Colleen Hoover"],["Format","Paperback"],["Language","English"],["Genre","Psychological thriller"],["Publisher","Grand Central Publishing"],["First published","2018"]]'::jsonb, 319, 83, null, null, null),
  ('91BNEhDBzbL', 'US', 'books', 'The Most Fun We Ever Had (Reese''s Book Club Pick): A Novel', 'Claire Lombardo', '/products/91BNEhDBzbL.jpg', 1299, null, null, false, null, '1K+ bought in past month', 'Marketplace Seller', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Marilyn and David Sorenson fell in love in the 1970s and have stayed devoted for decades, raising four very different daughters in the Chicago area. When a teenage boy with a secret connection to the family enters their lives, long-buried tensions among the sisters rise to the surface. Moving back and forth across more than four decades, this sweeping family saga explores marriage, sibling rivalry, and the complicated bonds of love.', '[["Author","Claire Lombardo"],["Format","Paperback"],["Language","English"],["Genre","Literary fiction, family saga"],["Setting","Chicago area"],["First published","2019"]]'::jsonb, 336, 84, null, null, null),
  ('81lplZAjvkL', 'US', 'books', 'The Correspondent: A Novel', 'Virginia Evans', '/products/81lplZAjvkL.jpg', 1299, null, null, false, 'Amazon''s Choice', '1K+ bought in past month', 'Amazon.com', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Told entirely through letters, The Correspondent follows Sybil Van Antwerp, a retired lawyer in her seventies who has spent a lifetime writing to family, friends, and favorite authors. As an old grief resurfaces and new friendships unexpectedly take root, the letters she sends, and the one she has never been able to send, reveal a woman slowly confronting her past. It is a warm, witty portrait of regret, forgiveness, and connection.', '[["Author","Virginia Evans"],["Format","Paperback"],["Language","English"],["Genre","Literary fiction"],["Style","Epistolary novel (told in letters)"],["First published","2025"]]'::jsonb, 32, 85, null, null, null),
  ('A1vfHxJYL', 'US', 'books', 'The Book Club for Troublesome Women: A Novel', 'Marie Bostwick', '/products/A1vfHxJYL.jpg', 1295, 1599, 19, true, null, '500+ bought in past month', 'Amazon.com', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'In the early 1960s, four suburban Virginia women who seem to have everything they were told to want find themselves quietly unsatisfied. When they form a book club around a controversial new book questioning women''s roles, their monthly meetings grow into a lifeline of honest conversation and friendship. As each woman begins to reconsider her marriage, ambitions, and sense of self, this heartfelt historical novel celebrates the power of female friendship.', '[["Author","Marie Bostwick"],["Format","Paperback"],["Language","English"],["Genre","Historical fiction"],["Setting","Suburban Virginia, 1960s"],["Themes","Friendship, women''s roles"],["First published","2024"]]'::jsonb, 113, 86, null, null, null),
  ('91pKiZROdL', 'US', 'books', 'The Widow: A Novel', 'John Grisham', '/products/91pKiZROdL.jpg', 1295, null, null, false, null, '1K+ bought in past month', 'Amazon.com', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Simon Latch is a small-town Virginia lawyer scraping by on wills and minor cases when an elderly widow walks into his office asking him to draft her will. Their professional relationship takes a dangerous turn after a sudden tragedy, and Simon soon finds himself at the center of a murder investigation. In his first whodunit, John Grisham blends courtroom drama with a twisting mystery about money, greed, and reputation.', '[["Author","John Grisham"],["Format","Paperback"],["Language","English"],["Genre","Legal thriller, mystery"],["Setting","Virginia"],["First published","2025"]]'::jsonb, 100, 87, null, null, null),
  ('91z4fk90NL', 'US', 'books', 'Something in the Water: Reese''s Book Club — A Novel', 'Catherine Steadman', '/products/91z4fk90NL.jpg', 1099, null, null, false, null, '1K+ bought in past month', 'Marketplace Seller', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Documentary filmmaker Erin and her investment-banker husband, Mark, seem to have the perfect life as they set off on a honeymoon in Bora Bora. While scuba diving in the clear water, they discover a mysterious bag, and deciding what to do with it sets off a chain of secrets and dangerous choices. This twisting psychological thriller explores how far a person will go to protect the life they have built.', '[["Author","Catherine Steadman"],["Format","Paperback"],["Language","English"],["Genre","Psychological thriller"],["Book club","Reese''s Book Club pick"],["Publisher","Ballantine Books"],["First published","2018"]]'::jsonb, 320, 88, null, null, null),
  ('91Sy3S198L', 'US', 'books', 'The Lost Bookshop: A Charming and Uplifting Novel', 'Evie Woods', '/products/91Sy3S198L.jpg', 1349, 1499, 10, true, null, '1K+ bought in past month', 'Amazon.com', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Across two timelines, The Lost Bookshop weaves together the story of Opaline, a young woman in the 1920s who flees an arranged marriage for a life among books in Paris and Dublin, with that of Martha and Henry, two people in present-day Dublin drawn to a mysterious bookshop that seems to appear and disappear. Blending historical fiction with a touch of magic, the novel celebrates stories, second chances, and finding where you belong.', '[["Author","Evie Woods"],["Format","Paperback"],["Language","English"],["Genre","Historical fiction, magical realism"],["Setting","Dublin and Paris"],["First published","2023"]]'::jsonb, 375, 89, null, null, null),
  ('91tK0tVAfL', 'US', 'books', 'The Let Them Theory: A Tool to Transform Your Life', 'Mel Robbins', '/products/91tK0tVAfL.jpg', 2395, null, null, false, 'Best Seller', '10K+ bought in past month', 'Amazon.com', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'In The Let Them Theory, Mel Robbins shares a simple mindset shift built around two words: let them. Drawing on research, personal stories, and experiences from her audience, she explains how to stop wasting energy trying to control other people''s opinions, choices, and behavior, and instead focus on what you can control. The book offers practical tools for relationships, work, and personal growth, aimed at reducing stress and building confidence.', '[["Author","Mel Robbins"],["Format","Paperback"],["Language","English"],["Genre","Self-help, personal development"],["Publisher","Hay House"],["First published","2024"]]'::jsonb, 134, 90, null, null, null),
  ('81MSoBpPAL', 'US', 'books', 'The Nightingale: A Novel', 'Kristin Hannah', '/products/81MSoBpPAL.jpg', 2295, 2799, 18, true, 'Amazon''s Choice', '10K+ bought in past month', 'Amazon.com', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'In a small French village at the start of World War II, sisters Vianne and Isabelle are separated by years, temperament, and ideals. When the Germans occupy France, Vianne must make difficult choices to protect her daughter at home, while the rebellious Isabelle joins the Resistance and risks everything to help others escape. This sweeping historical novel explores courage, sacrifice, and the enduring bond between sisters during wartime.', '[["Author","Kristin Hannah"],["Format","Paperback"],["Language","English"],["Genre","Historical fiction"],["Setting","Occupied France, World War II"],["First published","2015"]]'::jsonb, 210, 91, null, null, null),
  ('91VZotRPO2L', 'US', 'books', 'The Housemaid', 'Freida McFadden', '/products/91VZotRPO2L.jpg', 1900, null, null, false, null, '10K+ bought in past month', 'Amazon.com', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Desperate for a fresh start, Millie takes a live-in job cleaning and cooking for the wealthy Winchester family in their beautiful Long Island home. At first it seems like the perfect opportunity, but her employer Nina''s moods grow increasingly unpredictable, and Millie begins to sense that the household is hiding something. As she grows closer to Nina''s husband, Andrew, secrets begin to surface in this twisty psychological thriller.', '[["Author","Freida McFadden"],["Format","Paperback"],["Language","English"],["Genre","Psychological thriller"],["Series","The Housemaid, Book 1"],["First published","2022"]]'::jsonb, 168, 92, null, null, null),
  ('A1bAAofyAIL', 'US', 'books', 'The Frozen River: A Novel', 'Ariel Lawhon', '/products/A1bAAofyAIL.jpg', 1100, 1799, 39, true, null, '10K+ bought in past month', 'Marketplace Seller', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'In the winter of 1789, when the Kennebec River freezes in Hallowell, Maine, a man''s body is discovered trapped in the ice. Midwife and healer Martha Ballard is called to examine him and soon suspects foul play, drawing her into a case that challenges the town''s powerful men. Inspired by the real diary of Martha Ballard, this historical mystery explores justice, courage, and a woman''s determination to be heard.', '[["Author","Ariel Lawhon"],["Format","Paperback"],["Language","English"],["Genre","Historical mystery"],["Setting","Hallowell, Maine, 1789"],["Publisher","Doubleday"],["First published","2023"]]'::jsonb, 68, 93, null, null, null),
  ('71eJ66acl9L', 'US', 'books', 'The Midnight Library: A GMA Book Club Pick — A Novel', 'Matt Haig', '/products/71eJ66acl9L.jpg', 1595, null, null, false, null, '10K+ bought in past month', 'Marketplace Seller', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Between life and death lies a library filled with infinite books, each offering the chance to live a different version of your life. Nora Seed finds herself there after reaching a moment of deep despair, and with guidance from a familiar librarian, she begins exploring the lives she might have lived had she made different choices. This imaginative novel reflects on regret, hope, and what truly makes a life worth living.', '[["Author","Matt Haig"],["Format","Paperback"],["Language","English"],["Genre","Literary fiction, fantasy"],["Book club","GMA Book Club pick"],["First published","2020"]]'::jsonb, 81, 94, null, null, null),
  ('91RVshgQn1S', 'US', 'books', 'The Silent Patient', 'Alex Michaelides', '/products/91RVshgQn1S.jpg', 1695, null, null, false, 'Best Seller', '10K+ bought in past month', 'Marketplace Seller', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Alicia Berenson, a celebrated painter, seems to have a perfect life with her fashion-photographer husband, Gabriel, until the night she shoots him five times and then never speaks another word. Years later, criminal psychotherapist Theo Faber becomes determined to uncover her motive and takes a job at the secure forensic unit where she is held. This tightly plotted psychological thriller explores trauma, obsession, and the stories people tell themselves.', '[["Author","Alex Michaelides"],["Format","Paperback"],["Language","English"],["Genre","Psychological thriller"],["Publisher","Celadon Books"],["First published","2019"]]'::jsonb, 174, 95, null, null, null),
  ('81xWVk2eL', 'US', 'books', 'First Lie Wins: Reese''s Book Club Pick — A Novel', 'Ashley Elston', '/products/81xWVk2eL.jpg', 1895, null, null, false, 'Best Seller', '10K+ bought in past month', 'Marketplace Seller', 'Amazon', array['A gripping story you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favorite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Evie Porter seems to have the perfect life with her charming boyfriend, Ryan, in a small Louisiana town. But Evie Porter is not her real name, and she is on an assignment for a mysterious boss who has given her a new identity and a specific job to do. When a woman using Evie''s true name suddenly appears, she must scramble to stay ahead in this twisty thriller about identity, deception, and reinvention.', '[["Author","Ashley Elston"],["Format","Paperback"],["Language","English"],["Genre","Thriller, suspense"],["Book club","Reese''s Book Club pick"],["First published","2024"]]'::jsonb, 293, 96, null, null, null),
  ('71uh0kUACRL', 'US', 'toys', 'Melissa & Doug Get Well Doctor Kit Play Set, 25-Piece Wooden Toy', 'Melissa & Doug', '/products/71uh0kUACRL.jpg', 3599, 4399, 18, true, 'Amazon''s Choice', '1K+ bought in past month', 'Melissa & Doug Official Store', 'Amazon', array['Sparks imaginative, screen-free play', 'Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift']::text[], 'The Melissa & Doug Get Well Doctor Kit invites kids to play doctor with a 25-piece set of pretend medical tools and accessories. Children can give checkups to friends, family, and stuffed animals, building empathy and communication skills while easing worries about real doctor visits. Sturdy wooden pieces and kid-safe materials stand up to repeated play, and the set makes an easy birthday or holiday gift.', '[["Brand","Melissa & Doug"],["Recommended age","3 years and up"],["Pieces","25"],["Material","Wood"],["Play type","Pretend play"],["Batteries","Not required"],["Educational focus","Imaginative play, empathy"]]'::jsonb, 93, 97, null, null, null),
  ('710dSCrRISL', 'US', 'toys', 'Masterbee Kids Camera for Girls & Boys, 3-12 Years, 1080P HD Digital Camera', 'Masterbee', '/products/710dSCrRISL.jpg', 2599, null, null, false, 'Overall Pick', null, 'Amazon.com', 'Amazon', array['Sparks imaginative, screen-free play', 'Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift']::text[], 'The Masterbee kids camera lets young photographers ages 3 to 12 capture photos and videos in 1080P HD. Its simple buttons and kid-sized design make it easy for small hands to snap pictures of family, pets, and adventures, encouraging creativity and curiosity. Built from durable, kid-safe materials to handle drops and everyday play, it gives kids a camera of their own instead of borrowing a phone and makes a great birthday or holiday gift.', '[["Brand","Masterbee"],["Recommended age","3 to 12 years"],["Video resolution","1080P HD"],["Features","Photo and video capture"],["Material","Durable, kid-safe materials"],["Educational focus","Creativity, photography"]]'::jsonb, 204, 98, null, null, null),
  ('81ll5SJkcQL', 'US', 'toys', 'Melissa & Doug Wooden Kitchen Accessory 22-Piece Play Set', 'Melissa & Doug', '/products/81ll5SJkcQL.jpg', 2495, null, null, false, null, '500+ bought in past month', 'Melissa & Doug Official Store', 'Amazon', array['Sparks imaginative, screen-free play', 'Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift']::text[], 'The Melissa & Doug Wooden Kitchen Accessory Set gives young chefs 22 pieces for pretend cooking, serving, and cleaning up in their play kitchen. Made from sturdy, kid-safe wood, the pieces stand up to busy imaginative play while helping children practice fine motor skills, sorting, and role-play. It pairs well with any toy kitchen or tea party setup and makes a thoughtful birthday or holiday gift.', '[["Brand","Melissa & Doug"],["Recommended age","3 years and up"],["Pieces","22"],["Material","Wood"],["Play type","Pretend kitchen play"],["Batteries","Not required"],["Educational focus","Fine motor skills, role-play"]]'::jsonb, 84, 99, null, null, null),
  ('71APFtgsw4L', 'US', 'toys', 'Smartivity Montessori Slide Puzzle, Wooden Learning Toy for Kids 4-8', 'Smartivity', '/products/71APFtgsw4L.jpg', 2400, null, null, false, null, null, 'Marketplace Seller', 'Amazon', array['Sparks imaginative, screen-free play', 'Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift']::text[], 'The Smartivity Montessori Slide Puzzle is a wooden brain-teaser that challenges kids ages 4 to 8 to slide pieces into place to solve each puzzle. Inspired by Montessori principles, it encourages logical thinking, problem-solving, and patience through hands-on, screen-free play. Made from durable, kid-safe materials, it is a rewarding quiet-time activity and makes a great birthday or holiday gift for curious young minds.', '[["Brand","Smartivity"],["Recommended age","4 to 8 years"],["Material","Wood"],["Toy type","Slide puzzle"],["Educational focus","Logic, problem-solving"],["Batteries","Not required"]]'::jsonb, 343, 100, null, null, null),
  ('71eSSNJH9fL', 'US', 'toys', '4 Pack LCD Writing Tablet for Kids, 8.5 Inch Colorful Doodle Board', null, '/products/71eSSNJH9fL.jpg', 5895, 7099, 17, true, 'Amazon''s Choice', '500+ bought in past month', 'Marketplace Seller', 'Amazon', array['Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift', 'Recommended for hours of independent fun']::text[], 'This 4-pack of 8.5-inch LCD writing tablets gives kids a colorful, mess-free way to doodle, practice letters, and play games. The pressure-sensitive screen displays bright lines as children draw, and a single press of the clear button wipes the board clean for a fresh start. Lightweight, durable, and paper-free, the tablets are great for car rides, restaurants, and classrooms, and the multi-pack makes them easy to share among siblings or friends.', '[["Brand","Generic"],["Quantity","4 tablets"],["Screen size","8.5 inches"],["Display","Colorful LCD"],["Toy type","Drawing and writing tablet"],["Educational focus","Writing, drawing, creativity"]]'::jsonb, 139, 101, null, null, null),
  ('71LxbmXeL', 'US', 'toys', '30 Pack Squishy Toys, Kawaii Mini Squishies Party Favors for Kids', null, '/products/71LxbmXeL.jpg', 5495, null, null, false, 'Overall Pick', '500+ bought in past month', 'Marketplace Seller', 'Amazon', array['Sparks imaginative, screen-free play', 'Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift']::text[], 'This 30-pack of kawaii mini squishies is filled with cute characters that spring back to shape after every squeeze. The soft, palm-sized toys make fun party favors, goodie bag fillers, classroom prizes, and stocking stuffers, and they offer a calming, tactile outlet for fidgety hands. Made from durable, kid-safe materials, the assortment gives kids plenty of variety to collect, share, and trade with friends.', '[["Brand","Generic"],["Quantity","30 pieces"],["Toy type","Mini squishies"],["Style","Kawaii"],["Ideal for","Party favors, classroom prizes"],["Educational focus","Sensory play"]]'::jsonb, 243, 102, null, null, null),
  ('917ZRbSY9TL', 'US', 'toys', '160 Pcs Fidget Toys Party Favors Pack, Pop Sensory Set for Kids', null, '/products/917ZRbSY9TL.jpg', 5549, null, null, false, null, null, 'Amazon.com', 'Amazon', array['Sparks imaginative, screen-free play', 'Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift']::text[], 'This 160-piece fidget toy pack is packed with a variety of pop-style and sensory toys that kids can press, squeeze, and fidget with. It is a convenient way to stock party favor bags, classroom treasure boxes, and holiday stockings with plenty of options for every child. The sensory toys can help keep busy hands occupied during car rides and homework, and they are made from durable, kid-safe materials for repeated play.', '[["Brand","Generic"],["Pieces","160"],["Toy type","Fidget and sensory toys"],["Includes","Pop-style fidgets"],["Ideal for","Party favors, classroom rewards"],["Educational focus","Sensory play, focus"]]'::jsonb, 94, 103, null, null, null),
  ('815sofq0avL', 'US', 'toys', 'Party Favors for Kids, 150-Pack Fidget Toys Bulk, Treasure Box Fillers', null, '/products/815sofq0avL.jpg', 4099, null, null, false, null, '500+ bought in past month', 'Marketplace Seller', 'Amazon', array['Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift', 'Recommended for hours of independent fun']::text[], 'This 150-pack of fidget toys makes it easy to fill party goodie bags, classroom treasure boxes, and reward jars in one purchase. The assortment offers a variety of tactile toys that kids can squeeze, press, and play with, helping keep hands busy and minds focused. Built from durable, kid-safe materials, the toys hold up to repeated use and provide hours of independent fun at home, at school, or on the road.', '[["Brand","Generic"],["Pieces","150"],["Toy type","Assorted fidget toys"],["Packaging","Bulk pack"],["Ideal for","Party favors, treasure box prizes"],["Educational focus","Sensory play"]]'::jsonb, 154, 104, null, null, null),
  ('71pyDjRPqhL', 'US', 'toys', '1000X Handheld Digital Microscope for Kids, 2.0" IPS Screen, STEM Toy', null, '/products/71pyDjRPqhL.jpg', 1695, 3099, 45, true, null, null, 'Marketplace Seller', 'Amazon', array['Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift', 'Recommended for hours of independent fun']::text[], 'This handheld digital microscope lets kids explore the tiny details of insects, leaves, coins, fabric, and more with up to 1000x magnification. A built-in 2.0-inch IPS screen shows a clear, magnified view without connecting to a computer, making it easy to use at home, outdoors, or in the classroom. As a hands-on STEM toy, it encourages curiosity, observation, and scientific thinking, and its durable build stands up to young explorers.', '[["Brand","Generic"],["Magnification","Up to 1000x"],["Screen","2.0-inch IPS"],["Toy type","Handheld digital microscope"],["Educational focus","STEM, science exploration"],["Ideal for","Home, outdoor, and classroom use"]]'::jsonb, 201, 105, null, null, null),
  ('61Pg7ofgYHL', 'US', 'toys', 'Nex Playground, The Active Play System for Kids & Families', 'Nex', '/products/61Pg7ofgYHL.jpg', 2999, 5399, 44, true, null, null, 'Marketplace Seller', 'Amazon', array['Sparks imaginative, screen-free play', 'Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift']::text[], 'Nex Playground is an active play system that turns your living room into a game space for kids and families. It connects to your TV and uses a motion-tracking camera to follow players'' movements, so there are no controllers or wearables to charge or lose. Games encourage kids to jump, dodge, dance, and stretch, making screen time more physically active while players compete or cooperate together.', '[["Brand","Nex"],["Product type","Motion-sensing game console"],["Players","Kids and families"],["Controllers","None required"],["Setup","Connects to your TV"],["Educational focus","Active play, movement"]]'::jsonb, 347, 106, null, null, null),
  ('61VzFxBrh7L', 'US', 'toys', 'Gesture Control RC Helicopter Toy for Kids, Rechargeable Mini Drone', null, '/products/61VzFxBrh7L.jpg', 4495, null, null, false, null, null, 'Amazon.com', 'Amazon', array['Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift', 'Recommended for hours of independent fun']::text[], 'This gesture-control RC helicopter lets kids steer a mini flying toy with simple hand movements, adding a fun, hands-on twist to indoor flight. The rechargeable design means no stacks of disposable batteries, and the compact size makes it well suited to living rooms and playrooms. Built from durable, kid-safe materials to handle bumps and tumbles, it encourages coordination and curiosity and makes a great birthday or holiday gift.', '[["Brand","Generic"],["Toy type","Mini RC helicopter"],["Control","Hand gesture control"],["Power","Rechargeable battery"],["Ideal for","Indoor flying"],["Educational focus","Hand-eye coordination"]]'::jsonb, 2, 107, null, null, null),
  ('519Oty05lTL', 'US', 'toys', 'Flycatcher smART Sketcher 2.0 Projector, Drawing Toy for Kids Ages 5+', 'Flycatcher', '/products/519Oty05lTL.jpg', 4300, 7599, 43, true, 'Overall Pick', '100+ bought in past month', 'Flycatcher Official Store', 'Amazon', array['Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift', 'Recommended for hours of independent fun']::text[], 'The Flycatcher smART Sketcher 2.0 is a drawing projector that helps kids ages 5 and up learn to draw step by step. It projects images and guided activities onto paper so children can trace outlines, add details, and build confidence as their skills grow. Built-in lessons and activities turn art time into a creative learning experience, and its durable, kid-friendly design stands up to regular use at home.', '[["Brand","Flycatcher"],["Model name","smART Sketcher 2.0"],["Recommended age","5 years and up"],["Toy type","Drawing projector"],["Educational focus","Drawing, art skills, creativity"],["Use","Trace projected images on paper"]]'::jsonb, 162, 108, null, null, null),
  ('71crrz3XJL', 'US', 'toys', 'LeapFrog 2-in-1 LeapTop Touch Learning Laptop Toy, Green', 'LeapFrog', '/products/71crrz3XJL.jpg', 4695, null, null, false, null, '10K+ bought in past month', 'Amazon.com', 'Amazon', array['Sparks imaginative, screen-free play', 'Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift']::text[], 'The LeapFrog 2-in-1 LeapTop Touch is a toddler learning laptop that switches between two play modes: a laptop with a keyboard and a tablet-style touch pad. Kids can explore letters, numbers, animals, and music through interactive activities, songs, and sounds, building early vocabulary and fine motor skills. Its durable, kid-safe design is sized for little hands, and the bright green finish makes it a cheerful gift for birthdays and holidays.', '[["Brand","LeapFrog"],["Recommended age","2 years and up"],["Toy type","Learning laptop"],["Educational focus","Letters, numbers, animals, music"],["Batteries","Required"],["Color","Green"]]'::jsonb, 287, 109, null, null, null),
  ('71jVEjU17nL', 'US', 'toys', 'Melissa & Doug 100 Wooden Building Blocks with Storage Box', 'Melissa & Doug', '/products/71jVEjU17nL.jpg', 5349, null, null, false, null, '5K+ bought in past month', 'Amazon.com', 'Amazon', array['Sparks imaginative, screen-free play', 'Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift']::text[], 'This Melissa & Doug set includes 100 solid wooden building blocks in a variety of shapes and colors, plus a storage box that makes cleanup quick and easy. Kids can stack, sort, and build towers, houses, and bridges, developing spatial reasoning, fine motor skills, and early problem-solving along the way. The sturdy, kid-safe blocks are built to last through years of open-ended play and make a classic birthday or holiday gift.', '[["Brand","Melissa & Doug"],["Pieces","100"],["Material","Wood"],["Includes","Storage box"],["Toy type","Building blocks"],["Batteries","Not required"],["Educational focus","Spatial reasoning, fine motor skills"]]'::jsonb, 137, 110, null, null, null),
  ('7106ox8f2jL', 'US', 'toys', 'Melissa & Doug Wooden Scoop & Serve Ice Cream Counter Play Set, 28 Pieces', 'Melissa & Doug', '/products/7106ox8f2jL.jpg', 2499, null, null, false, null, '5K+ bought in past month', 'Melissa & Doug Official Store', 'Amazon', array['Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift', 'Recommended for hours of independent fun']::text[], 'The Melissa & Doug Scoop & Serve Ice Cream Counter lets kids run their own pretend ice cream shop with 28 wooden pieces. Children can scoop, stack, and serve cones and treats to friends and family, practicing social skills and imaginative role-play as they go. The sturdy counter and kid-safe wooden pieces hold up to busy play sessions and provide hours of independent fun, making it a sweet birthday or holiday gift.', '[["Brand","Melissa & Doug"],["Recommended age","3 years and up"],["Pieces","28"],["Material","Wood"],["Play type","Pretend play"],["Batteries","Not required"],["Educational focus","Role-play, social skills"]]'::jsonb, 67, 111, null, null, null),
  ('71jnKpPcTL', 'US', 'toys', 'Melissa & Doug Super Smile Dentist Play Set, 25-Piece Kids Toy', 'Melissa & Doug', '/products/71jnKpPcTL.jpg', 4549, 5299, 14, true, 'Amazon''s Choice', '5K+ bought in past month', 'Melissa & Doug Official Store', 'Amazon', array['Built tough from kid-safe, durable materials', 'Encourages learning, creativity, and motor skills', 'Makes a great birthday or holiday gift', 'Recommended for hours of independent fun']::text[], 'The Melissa & Doug Super Smile Dentist Play Set gives kids 25 pieces of pretend dental tools and accessories for playing out checkups at home. Role-playing a dentist visit helps children learn about brushing and oral care while easing worries about their own appointments. Made from durable, kid-safe materials, the set stands up to repeated play and provides hours of independent fun, making it a thoughtful birthday or holiday gift.', '[["Brand","Melissa & Doug"],["Recommended age","3 years and up"],["Pieces","25"],["Play type","Pretend play"],["Educational focus","Oral hygiene, role-play"],["Material","Durable, kid-safe materials"]]'::jsonb, 234, 112, null, null, null),
  ('71ZbWyz0ndL', 'US', 'sports', 'Adjustable Dumbbells Set of 2, Free Weights Dumbbell Set for Home Gym', null, '/products/71ZbWyz0ndL.jpg', 33100, null, null, false, null, '500+ bought in past month', 'Amazon.com', 'Amazon', array['Adjustable weight adapts as your strength grows', 'Space-saving design replaces a full rack of dumbbells', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle']::text[], 'This set of two adjustable dumbbells lets you change the weight as your strength grows, bringing versatile free-weight training to your home gym. The space-saving design replaces a full rack of fixed dumbbells, keeping your workout area tidy. A secure locking mechanism holds the plates firmly in place during lifts, and durable, non-slip grip handles provide control for presses, curls, rows, and more.', '[["Brand","Generic"],["Product type","Adjustable dumbbells"],["Quantity","Set of 2"],["Adjustment","Adjustable weight plates"],["Locking","Secure locking mechanism"],["Handle","Non-slip grip"],["Ideal for","Home-gym strength training"]]'::jsonb, 287, 113, null, null, null),
  ('71qoBoG6ML', 'US', 'sports', '25/50/55 lbs Pair Adjustable Dumbbell Set for Men and Women', null, '/products/71qoBoG6ML.jpg', 5599, 7099, 21, true, null, '100+ bought in past month', 'Amazon.com', 'Amazon', array['Space-saving design replaces a full rack of dumbbells', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle', 'Ideal for home-gym strength training']::text[], 'This adjustable dumbbell pair is offered in 25, 50, and 55 lb options, giving men and women a flexible way to strength train at home. The space-saving design takes the place of several fixed-weight dumbbells, and a secure locking mechanism keeps plates in place while you lift. Durable, non-slip grip handles provide control for curls, presses, and rows, making the set well suited to home-gym workouts at every level.', '[["Brand","Generic"],["Weight options","25, 50, or 55 lb pair"],["Quantity","Pair"],["Locking","Secure locking mechanism"],["Handle","Non-slip grip"],["Ideal for","Home-gym strength training"]]'::jsonb, 4, 114, null, null, null),
  ('81Ub7Swav5L', 'US', 'sports', 'Adjustable Dumbbell Set, 20/33/45/70/90lbs Free Weights, 5-in-1', null, '/products/81Ub7Swav5L.jpg', 30849, 49599, 38, true, null, '100+ bought in past month', 'Amazon.com', 'Amazon', array['Space-saving design replaces a full rack of dumbbells', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle', 'Ideal for home-gym strength training']::text[], 'This 5-in-1 adjustable dumbbell set is available in 20, 33, 45, 70, and 90 lb options and can be reconfigured for a variety of exercises beyond standard dumbbell work. The space-saving design replaces a full rack of weights, and a secure locking mechanism keeps plates firmly in place. Durable, non-slip grip handles provide control for everything from curls to squats, making it a versatile foundation for home-gym strength training.', '[["Brand","Generic"],["Weight options","20, 33, 45, 70, or 90 lb"],["Design","5-in-1 multi-function"],["Locking","Secure locking mechanism"],["Handle","Non-slip grip"],["Ideal for","Home-gym strength training"]]'::jsonb, 228, 115, null, null, null),
