  ('81yF5CpdlLL', 'US', 'sports', 'PowerBlock Elite EXP Adjustable Dumbbells, Sold in Pairs, 5-50 lb', 'PowerBlock', '/products/81yF5CpdlLL.jpg', 28649, 36199, 21, true, null, '500+ bought in past month', 'PowerBlock Official Store', 'Amazon', array['Space-saving design replaces a full rack of dumbbells', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle', 'Ideal for home-gym strength training']::text[], 'PowerBlock Elite EXP adjustable dumbbells are sold in pairs and adjust from 5 to 50 lb per hand, replacing a full rack of traditional dumbbells with a compact footprint. A selector pin lets you change weight quickly between sets, and the set is expandable with optional kits for heavier loads as your strength grows. Durable steel construction and comfortable handles make them a long-lasting foundation for any home gym.', '[["Brand","PowerBlock"],["Model name","Elite EXP"],["Weight range","5 to 50 lb per dumbbell"],["Quantity","Pair"],["Adjustment","Selector pin"],["Expandable","Yes, with optional expansion kits"],["Material","Steel"]]'::jsonb, 35, 120, null, null, null),
  ('91QxtmB7tEL', 'US', 'sports', 'Amazon Basics Adjustable Dumbbell Hand Weight Set, 38 Pounds, Black', 'Amazon Basics', '/products/91QxtmB7tEL.jpg', 38200, null, null, false, 'Overall Pick', '100+ bought in past month', 'Amazon.com', 'Amazon', array['Adjustable weight adapts as your strength grows', 'Space-saving design replaces a full rack of dumbbells', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle']::text[], 'This adjustable dumbbell hand weight set provides 38 pounds of total weight, making it easy to scale workouts up or down as your strength develops. The space-saving design replaces multiple fixed dumbbells, and a secure locking mechanism keeps the weights firmly in place during every rep. Durable, non-slip grip handles offer control for curls, presses, and rows, and the black finish looks clean in any home gym.', '[["Brand","Amazon Basics"],["Total weight","38 lb"],["Product type","Adjustable dumbbell set"],["Locking","Secure locking mechanism"],["Handle","Non-slip grip"],["Color","Black"]]'::jsonb, 346, 121, null, null, null),
