  ('in-61BWskzWNIL', 'IN', 'electronics', 'boAt Rockerz 371 Bluetooth Headphones, 40mm Drivers, 50H Battery, ENx Tech, BT v5.4, Foldable', 'boAt', '/products/in/61BWskzWNIL.jpg', 109900, 186900, 41, true, null, '500+ bought in past month', 'Cloudtail India', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play', 'Comfortable cushions for all-day wear']::text[], 'The boAt Rockerz 371 is a foldable wireless headphone made for long listening sessions, with 40 mm drivers that deliver boAt''s signature bass-forward sound. A single charge offers up to 50 hours of playback, and ENx technology works with the built-in mic to keep your voice clear on calls. Bluetooth v5.4 provides a stable connection, while soft cushions and a folding design make it comfortable to wear and easy to carry.', '[["Brand","boAt"],["Model name","Rockerz 371"],["Connectivity","Bluetooth v5.4"],["Driver size","40 mm"],["Battery life","Up to 50 hours"],["Microphone","Built-in mic with ENx technology"],["Design","Foldable"],["Charging port","USB Type-C"]]'::jsonb, 363, 0, null, null, null),
  ('in-711l4y8aNlL', 'IN', 'electronics', 'boAt Rockerz 480 RGB Bluetooth Headphones, 6 Light Modes, 40mm Drivers, 60H Battery, ENx Tech', 'boAt', '/products/in/711l4y8aNlL.jpg', 189900, 332900, 43, true, 'Limited time deal', '1K+ bought in past month', 'boAt Official Store', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play', 'Comfortable cushions for all-day wear']::text[], 'The boAt Rockerz 480 wireless headphone adds a splash of colour to your playlist with RGB lighting that cycles through six light modes. Its 40 mm drivers produce punchy, bass-rich audio, and the battery lasts up to 60 hours on a single charge. ENx technology helps cut background noise from your voice during calls, and cushioned ear cups keep extended listening comfortable. USB Type-C charging tops it up between sessions.', '[["Brand","boAt"],["Model name","Rockerz 480"],["Form factor","On-ear"],["Connectivity","Bluetooth"],["Lighting","RGB LEDs with 6 light modes"],["Driver size","40 mm"],["Battery life","Up to 60 hours"],["Microphone","Built-in mic with ENx technology"],["Charging port","USB Type-C"]]'::jsonb, 44, 1, null, null, null),
