  ('in-51lPcFkwYmL', 'IN', 'electronics', 'Noise Airwave Max XR Wireless Over-Ear Headphones, 120H Playtime, ANC, Spatial Audio', 'Noise', '/products/in/51lPcFkwYmL.jpg', 299900, null, null, false, null, '100+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['Immersive sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play']::text[], 'The Noise Airwave Max XR is an over-ear wireless headphone that pairs active noise cancellation with spatial audio for a more immersive listening experience. Its battery is rated for up to 120 hours of playtime, so it can go for days between charges. Cushioned over-ear cups keep long sessions comfortable, the built-in mic handles calls, and USB Type-C charging keeps top-ups simple.', '[["Brand","Noise"],["Model name","Airwave Max XR"],["Form factor","Over-ear"],["Connectivity","Bluetooth"],["Noise control","Active noise cancellation"],["Audio","Spatial audio"],["Battery life","Up to 120 hours"],["Charging port","USB Type-C"]]'::jsonb, 102, 3, null, null, null),
  ('in-6163uYK3eeL', 'IN', 'electronics', 'Boult Q Over-Ear Bluetooth Headphones, 70H Playtime, 40mm Bass Drivers, Zen ENC Mic, Type-C', 'Boult', '/products/in/6163uYK3eeL.jpg', 179900, null, null, false, null, '500+ bought in past month', 'Boult Official Store', 'Amazon', array['Immersive sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play']::text[], 'The Boult Q is an over-ear Bluetooth headphone built around 40 mm bass drivers for rich, powerful sound. It offers up to 70 hours of playtime on a full charge, and the Zen ENC mic reduces surrounding noise so callers hear you more clearly. Soft over-ear cushions make it comfortable for long commutes and work-from-home days, and a USB Type-C port handles charging.', '[["Brand","Boult"],["Model name","Q"],["Form factor","Over-ear"],["Connectivity","Bluetooth"],["Driver size","40 mm"],["Battery life","Up to 70 hours"],["Noise control","Zen ENC mic for calls"],["Charging port","USB Type-C"]]'::jsonb, 88, 4, null, null, null),
  ('in-61qVKj0RGfL', 'IN', 'electronics', 'Zebronics Silencio 200T Wireless Headphones, Hybrid ANC 48dB, 100H Playback, 40mm Drivers, Dual Mic', 'Zebronics', '/products/in/61qVKj0RGfL.jpg', 299900, null, null, false, null, '100+ bought in past month', 'Cocoblu Retail', 'Amazon', array['Immersive sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play']::text[], 'The Zebronics Silencio 200T wireless headphone uses hybrid active noise cancellation rated at up to 48 dB to quieten the world around you. Its 40 mm drivers deliver full, bass-rich sound, and the battery supports up to 100 hours of playback. A dual-mic setup helps keep calls clear, making it a practical choice for travel, study and long work days.', '[["Brand","Zebronics"],["Model name","Silencio 200T"],["Connectivity","Bluetooth"],["Noise control","Hybrid ANC, up to 48 dB"],["Driver size","40 mm"],["Battery life","Up to 100 hours"],["Microphone","Dual mic"]]'::jsonb, 48, 5, null, null, null),
  ('in-51rE6mPHnL', 'IN', 'electronics', 'Portronics Muffs M2 On-Ear Bluetooth Headphones, 40H Playtime, 40mm Dynamic Drivers, AUX 3.5mm', 'Portronics', '/products/in/51rE6mPHnL.jpg', 86900, 157900, 45, true, null, '500+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play', 'Comfortable cushions for all-day wear']::text[], 'The Portronics Muffs M2 is an on-ear headphone that works wirelessly over Bluetooth or wired through its 3.5 mm AUX input, so you can keep listening even when the battery runs low. It offers up to 40 hours of playtime, and 40 mm dynamic drivers deliver clear, balanced sound. The built-in mic handles calls, and cushioned ear pads keep it comfortable through the day.', '[["Brand","Portronics"],["Model name","Muffs M2"],["Form factor","On-ear"],["Connectivity","Bluetooth and 3.5 mm AUX"],["Driver size","40 mm dynamic"],["Battery life","Up to 40 hours"],["Microphone","Built-in"]]'::jsonb, 25, 6, null, null, null),
  ('in-61qLlDAZEL', 'IN', 'computers', 'Lenovo V15 G4 AMD Ryzen 5 7520U 15.6" FHD Laptop, 16GB DDR5, 512GB NVMe SSD, Windows 11', 'Lenovo', '/products/in/61qLlDAZEL.jpg', 5809000, null, null, false, null, null, 'Lenovo Official Store', 'Amazon', array['Snappy everyday performance for work and study', 'Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds']::text[], 'The Lenovo V15 G4 is a 15.6-inch everyday laptop powered by the AMD Ryzen 5 7520U processor with integrated Radeon graphics. It pairs 16 GB of DDR5 memory with a 512 GB NVMe SSD, so apps open quickly and multitasking stays smooth. The Full HD display suits spreadsheets, video calls and streaming, and Windows 11 comes pre-installed for work, study or small-business use.', '[["Brand","Lenovo"],["Model name","V15 G4"],["Screen size","15.6 inches"],["Resolution","Full HD (1920 x 1080)"],["Processor","AMD Ryzen 5 7520U"],["Graphics","AMD Radeon 610M (integrated)"],["RAM","16 GB DDR5"],["Storage","512 GB NVMe SSD"],["Operating system","Windows 11"]]'::jsonb, 295, 7, 'lenovo-v15-g4', 'Configuration', 'Ryzen 5 7520U, 16 GB RAM'),
  ('in-71JcEk00fqL', 'IN', 'computers', 'HP 15 AMD Ryzen 3 7320U Laptop, 8GB LPDDR5, 512GB SSD, 15.6" FHD Anti-Glare Micro-Edge, Win 11', 'HP', '/products/in/71JcEk00fqL.jpg', 5699000, 9658900, 41, true, 'Limited time deal', null, 'Cloudtail India', 'Amazon', array['Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds', 'Windows 11 with lifetime validity']::text[], 'The HP 15 laptop runs on an AMD Ryzen 3 7320U processor with 8 GB of LPDDR5 memory, handling browsing, online classes and office work with ease. A 512 GB SSD offers fast boot times and room for files, while the 15.6-inch Full HD anti-glare display with micro-edge bezels keeps visuals sharp and reduces reflections. It ships with Windows 11 for a familiar setup out of the box.', '[["Brand","HP"],["Model name","HP 15"],["Screen size","15.6 inches"],["Display","Full HD, anti-glare, micro-edge"],["Processor","AMD Ryzen 3 7320U"],["RAM","8 GB LPDDR5"],["Storage","512 GB SSD"],["Operating system","Windows 11"]]'::jsonb, 314, 8, null, null, null),
  ('in-71Ws1bRoM3L', 'IN', 'computers', 'ASUS Vivobook 15 Intel Core i5-13420H, 16GB RAM, 1TB SSD, 15.6" FHD, Backlit Keyboard, Windows 11', 'ASUS', '/products/in/71Ws1bRoM3L.jpg', 6899000, 13449900, 49, true, 'Limited time deal', null, 'Appario Retail Private Ltd', 'Amazon', array['Snappy everyday performance for work and study', 'Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds']::text[], 'The ASUS Vivobook 15 is powered by a 13th Gen Intel Core i5-13420H processor with 16 GB of RAM, giving it headroom for heavy multitasking, coding and light creative work. A 1 TB SSD provides generous storage for documents, photos and projects. The 15.6-inch Full HD display is easy on the eyes, and the backlit keyboard makes typing in dim rooms simpler. Windows 11 comes pre-installed.', '[["Brand","ASUS"],["Model name","Vivobook 15"],["Screen size","15.6 inches"],["Resolution","Full HD"],["Processor","Intel Core i5-13420H"],["RAM","16 GB"],["Storage","1 TB SSD"],["Keyboard","Backlit"],["Operating system","Windows 11"]]'::jsonb, 215, 9, null, null, null),
  ('in-716M8uhjvSL', 'IN', 'computers', 'Apple 2026 MacBook Air 15" Laptop, M5 chip, Apple Intelligence, 15.3" Liquid Retina Display', 'Apple', '/products/in/716M8uhjvSL.jpg', 16699000, null, null, false, null, null, 'Apple Official Store', 'Amazon', array['Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds', 'Windows 11 with lifetime validity']::text[], 'The 2026 MacBook Air 15-inch brings Apple''s M5 chip to a thin, lightweight laptop with a spacious 15.3-inch Liquid Retina display. The M5 chip handles everyday work, photo editing and multitasking smoothly while supporting the Apple Intelligence features built into macOS. The larger screen gives more room for side-by-side apps, making it a practical choice for students and professionals who want a big display in a portable design.', '[["Brand","Apple"],["Model name","MacBook Air 15-inch (2026)"],["Screen size","15.3 inches"],["Display","Liquid Retina"],["Processor","Apple M5 chip"],["Operating system","macOS"],["AI features","Apple Intelligence"]]'::jsonb, 5, 10, null, null, null),
  ('in-71lPJIfGX1L', 'IN', 'computers', 'ASUS Vivobook S14 (2026), Intel Core 7 350, 16GB RAM, 512GB SSD, 14" FHD+ Display', 'ASUS', '/products/in/71lPJIfGX1L.jpg', 11899000, null, null, false, null, null, 'ASUS Official Store', 'Amazon', array['Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds', 'Windows 11 with lifetime validity']::text[], 'The ASUS Vivobook S14 (2026) is a compact 14-inch laptop powered by the Intel Core 7 350 processor. With 16 GB of RAM and a 512 GB SSD, it handles office work, browsing and streaming smoothly while keeping boot and load times short. The FHD+ display offers a taller view than standard widescreens, which helps when working on long documents, and Windows 11 comes ready to use.', '[["Brand","ASUS"],["Model name","Vivobook S14 (2026)"],["Screen size","14 inches"],["Resolution","FHD+"],["Processor","Intel Core 7 350"],["RAM","16 GB"],["Storage","512 GB SSD"],["Operating system","Windows 11"]]'::jsonb, 47, 11, null, null, null),
  ('in-61AccNkmFFL', 'IN', 'computers', 'Lenovo V15 G4 AMD Athlon Silver 7120U Laptop, 8GB LPDDR5, 512GB SSD, 15.6" FHD, Windows 11', 'Lenovo', '/products/in/61AccNkmFFL.jpg', 4699900, null, null, false, null, '100+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds', 'Windows 11 with lifetime validity']::text[], 'The Lenovo V15 G4 with AMD Athlon Silver 7120U is an entry-level 15.6-inch laptop for everyday tasks such as browsing, email, online classes and document work. It comes with 8 GB of LPDDR5 memory and a 512 GB SSD for quick start-ups and ample storage. The Full HD display keeps text and video sharp, and Windows 11 is pre-installed so it is ready to use from day one.', '[["Brand","Lenovo"],["Model name","V15 G4"],["Screen size","15.6 inches"],["Resolution","Full HD"],["Processor","AMD Athlon Silver 7120U"],["Graphics","AMD Radeon 610M (integrated)"],["RAM","8 GB LPDDR5"],["Storage","512 GB SSD"],["Operating system","Windows 11"]]'::jsonb, 376, 12, 'lenovo-v15-g4', 'Configuration', 'Athlon Silver 7120U, 8 GB RAM'),
  ('in-61W5VjoziL', 'IN', 'home-kitchen', 'Hawkins 3 Litre Inner Lid Pressure Cooker, Stainless Steel, Induction Compatible, Silver (HSS3W)', 'Hawkins', '/products/in/61W5VjoziL.jpg', 277900, 383900, 28, true, null, '5K+ bought in past month', 'Hawkins Official Store', 'Amazon', array['ISI-marked, made in India for everyday cooking', 'Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking']::text[], 'This Hawkins 3 litre pressure cooker is made from stainless steel with a thick base that spreads heat evenly and works on both gas and induction cooktops. It uses the Hawkins inner lid design, where the lid sits inside the body and steam pressure seals it from within for safe operation. The 3 litre size suits small families for everyday dal, rice and sabzi, and the silver finish is easy to keep clean.', '[["Brand","Hawkins"],["Model","HSS3W"],["Capacity","3 litres"],["Material","Stainless steel"],["Lid type","Inner lid"],["Compatible cooktops","Gas and induction"],["Colour","Silver"]]'::jsonb, 336, 13, null, null, null),
  ('in-619CmDHn8L', 'IN', 'home-kitchen', 'Hawkins Contura Black 1.5 Litre Hard Anodised Inner Lid Pressure Cooker, Baby Cooker (CB15)', 'Hawkins', '/products/in/619CmDHn8L.jpg', 150700, null, null, false, 'Bestseller', '5K+ bought in past month', 'Hawkins Official Store', 'Amazon', array['ISI-marked, made in India for everyday cooking', 'Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking']::text[], 'The Hawkins Contura Black 1.5 litre is a compact hard anodised pressure cooker, often used as a baby cooker for small portions of dal, rice, khichdi and purees. Its curved Contura body makes stirring easy, and the hard anodised surface resists everyday wear. Like other Hawkins cookers, it uses an inner lid that steam pressure seals from within. The small size also suits one or two people.', '[["Brand","Hawkins"],["Model","CB15"],["Capacity","1.5 litres"],["Material","Hard anodised aluminium"],["Lid type","Inner lid"],["Body shape","Curved Contura body"],["Colour","Black"]]'::jsonb, 307, 14, 'hawkins-contura-black', 'Size', '1.5 Litre'),
  ('in-51LKIBnva1L', 'IN', 'home-kitchen', 'Hawkins Contura Black XT 3 Litre Induction Aluminium Inner Lid Pressure Cooker (CXT30)', 'Hawkins', '/products/in/51LKIBnva1L.jpg', 235000, 408900, 43, true, 'Amazon''s Choice', '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking', 'Backed by a manufacturer warranty']::text[], 'The Hawkins Contura Black XT is a 3 litre inner lid pressure cooker designed for both induction and gas cooktops. Its hard anodised black body is paired with an induction-ready base, and the curved Contura shape makes it easy to stir and serve from. The inner lid is sealed by steam pressure from within, a hallmark of Hawkins cookers, and the 3 litre size suits families of three to four.', '[["Brand","Hawkins"],["Model","CXT30"],["Capacity","3 litres"],["Material","Hard anodised aluminium"],["Lid type","Inner lid"],["Compatible cooktops","Induction and gas"],["Colour","Black"]]'::jsonb, 105, 15, 'hawkins-contura-black', 'Size', '3 Litre XT (induction)'),
  ('in-51pwtOYhqL', 'IN', 'home-kitchen', 'Hawkins Classic 1.5 Litre Aluminium Pressure Cooker, Straight Body, Gas Compatible', 'Hawkins', '/products/in/51pwtOYhqL.jpg', 111900, 154900, 28, true, 'Bestseller', '5K+ bought in past month', 'Hawkins Official Store', 'Amazon', array['ISI-marked, made in India for everyday cooking', 'Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking']::text[], 'The Hawkins Classic 1.5 litre is a straight-bodied aluminium pressure cooker for gas stoves, well suited to one or two people or small side dishes. It uses the traditional Hawkins inner lid, which steam pressure seals from within for safe cooking. Lightweight aluminium heats up quickly, cutting cooking time for dal, rice and vegetables. The ISI-marked cooker is made in India for everyday use.', '[["Brand","Hawkins"],["Model name","Classic"],["Capacity","1.5 litres"],["Material","Aluminium"],["Lid type","Inner lid"],["Compatible cooktops","Gas"],["Body shape","Straight body"],["Colour","Silver"]]'::jsonb, 181, 16, null, null, null),
  ('in-51imT7YoPHL', 'IN', 'home-kitchen', 'Prestige Popular Max Aluminium Outer Lid Pressure Cooker Combo, 2L + 3L + 5L, Gas & Induction', 'Prestige', '/products/in/51imT7YoPHL.jpg', 296200, null, null, false, null, '1K+ bought in past month', 'Cocoblu Retail', 'Amazon', array['Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking', 'Backed by a manufacturer warranty']::text[], 'This Prestige Popular Max combo brings together three aluminium outer lid pressure cookers in 2, 3 and 5 litre sizes, so you can cook dal, rice and curries at the same time or match the cooker to the meal. The outer lid design is simple to open and close, and the cookers work on both gas and induction cooktops. Sturdy handles and a secure locking lid support safe everyday cooking.', '[["Brand","Prestige"],["Model name","Popular Max"],["Capacity","2 litres, 3 litres and 5 litres"],["Number of pieces","3"],["Material","Aluminium"],["Lid type","Outer lid"],["Compatible cooktops","Gas and induction"]]'::jsonb, 188, 17, null, null, null),
  ('in-51r9ZGmYADL', 'IN', 'home-kitchen', 'Prestige Nakshatra Duo 3 Litre Aluminium Inner Lid Pressure Cooker, Stainless Steel Lid', 'Prestige', '/products/in/51r9ZGmYADL.jpg', 151800, 287900, 47, true, null, '1K+ bought in past month', 'Cloudtail India', 'Amazon', array['ISI-marked, made in India for everyday cooking', 'Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking']::text[], 'The Prestige Nakshatra Duo is a 3 litre inner lid pressure cooker that pairs an aluminium body with a stainless steel lid for a durable, easy-clean top. The inner lid seals securely under pressure, and the body spreads heat evenly for faster, fuel-saving cooking. It works on gas and induction cooktops, and the ISI-marked cooker is sized for everyday meals for a small family.', '[["Brand","Prestige"],["Model name","Nakshatra Duo"],["Capacity","3 litres"],["Body material","Aluminium"],["Lid material","Stainless steel"],["Lid type","Inner lid"],["Compatible cooktops","Gas and induction"]]'::jsonb, 42, 18, null, null, null),
  ('in-61rWcMP4s9L', 'IN', 'fashion', 'Campus Men First Running Shoes, Lightweight Lace-Up Sports Shoes', 'Campus', '/products/in/61rWcMP4s9L.jpg', 119900, 203900, 41, true, null, '1K+ bought in past month', 'Cocoblu Retail', 'Amazon', array['Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking', 'Everyday comfort for Indian roads and weather']::text[], 'The Campus First running shoes for men are built for everyday movement, with a lightweight construction that keeps each step easy. A cushioned sole absorbs impact on the road or treadmill, while the anti-skid outsole provides grip on varied surfaces. The lace-up closure gives a secure, adjustable fit for daily runs, gym sessions and evening walks.', '[["Brand","Campus"],["Model name","First"],["Department","Men"],["Shoe type","Running shoes"],["Closure","Lace-up"],["Outsole","Cushioned, anti-skid"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 34, 19, null, null, null),
  ('in-61Il0xGaORL', 'IN', 'fashion', 'Campus Men Hurricane Running Shoes, Cushioned Everyday Trainers', 'Campus', '/products/in/61Il0xGaORL.jpg', 99900, null, null, false, null, '1K+ bought in past month', 'Campus Official Store', 'Amazon', array['Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking', 'Everyday comfort for Indian roads and weather']::text[], 'The Campus Hurricane is a men''s running shoe designed as a cushioned everyday trainer. Its padded sole softens impact during runs and long walks, while the anti-skid outsole helps keep you steady on wet or uneven surfaces. A lace-up closure lets you adjust the fit, and the sporty design works just as well for casual wear as for the gym.', '[["Brand","Campus"],["Model name","Hurricane"],["Department","Men"],["Shoe type","Running shoes, everyday trainers"],["Closure","Lace-up"],["Outsole","Cushioned, anti-skid"],["Use","Running, gym and walking"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 141, 20, null, null, null),
  ('in-61XwYMOyfwL', 'IN', 'fashion', 'Campus Men Wells Running Shoes, Breathable Mesh Upper', 'Campus', '/products/in/61XwYMOyfwL.jpg', 71200, 130900, 46, true, null, '1K+ bought in past month', 'Campus Official Store', 'Amazon', array['Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking', 'Everyday comfort for Indian roads and weather']::text[], 'The Campus Wells running shoes for men feature a breathable mesh upper that lets air circulate and keeps feet cool through warm days and workouts. A cushioned sole absorbs impact with every stride, and the anti-skid outsole offers dependable grip. With a lace-up closure for a secure fit, they suit daily runs, gym sessions and walking.', '[["Brand","Campus"],["Model name","Wells"],["Department","Men"],["Shoe type","Running shoes"],["Closure","Lace-up"],["Upper material","Breathable mesh"],["Outsole","Cushioned, anti-skid"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 337, 21, null, null, null),
  ('in-612dWsWvGRL', 'IN', 'fashion', 'Sparx Men SM 406 Running Shoes, Enhanced Durability & Soft Cushion, Grey', 'Sparx', '/products/in/612dWsWvGRL.jpg', 89100, null, null, false, null, '500+ bought in past month', 'Sparx Official Store', 'Amazon', array['Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking', 'Everyday comfort for Indian roads and weather']::text[], 'The Sparx SM 406 running shoes for men combine enhanced durability with soft cushioning for everyday comfort. The anti-skid outsole grips well on city roads and gym floors, and the lace-up closure keeps the fit snug. Finished in grey, they pair easily with track pants and casual wear for walking, running or training.', '[["Brand","Sparx"],["Model name","SM 406"],["Department","Men"],["Shoe type","Running shoes"],["Closure","Lace-up"],["Outsole","Soft cushion, anti-skid"],["Colour","Grey"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 101, 22, null, null, null),
  ('in-719ojmA9G7L', 'IN', 'fashion', 'Boldfit Running Shoes for Men, Soft Sole Lightweight Sports Shoes, Anti-Skid', 'Boldfit', '/products/in/719ojmA9G7L.jpg', 109900, null, null, false, null, '100+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Lightweight, breathable mesh upper keeps feet cool', 'Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking']::text[], 'These Boldfit running shoes for men are designed to feel light on the feet, with a soft sole that cushions every step. The breathable mesh upper helps keep feet cool, and the anti-skid outsole provides grip on indoor and outdoor surfaces. A lace-up closure offers an adjustable fit for jogging, gym workouts and long walks.', '[["Brand","Boldfit"],["Department","Men"],["Shoe type","Running shoes"],["Closure","Lace-up"],["Upper material","Breathable mesh"],["Outsole","Soft sole, anti-skid"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 30, 23, null, null, null),
  ('in-61TxjQ3FzEL', 'IN', 'fashion', 'Impakto Driftwave Men Running Shoes, Lightweight & Breathable for Gym, Training & Travel', 'Impakto', '/products/in/61TxjQ3FzEL.jpg', 79900, 130900, 39, true, 'Limited time deal', null, 'Appario Retail Private Ltd', 'Amazon', array['Lightweight, breathable mesh upper keeps feet cool', 'Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking']::text[], 'The Impakto Driftwave running shoes for men are lightweight and breathable, making them a versatile pair for the gym, training sessions and travel. A mesh upper allows airflow to keep feet fresh, while the cushioned sole softens impact. The anti-skid outsole adds grip on varied surfaces, and the lace-up closure delivers a secure fit.', '[["Brand","Impakto"],["Model name","Driftwave"],["Department","Men"],["Shoe type","Running shoes"],["Closure","Lace-up"],["Upper material","Breathable mesh"],["Outsole","Cushioned, anti-skid"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 260, 24, null, null, null),
  ('in-51zZo49wleL', 'IN', 'beauty', 'Mamaearth Vitamin C Daily Glow Face Serum for Men & Women, Glowing Skin, Oily & Dry Skin', 'Mamaearth', '/products/in/51zZo49wleL.jpg', 31900, 48900, 35, true, null, '1K+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow', 'Suitable for all skin types']::text[], 'The Mamaearth Vitamin C Daily Glow Face Serum is a lightweight serum for men and women that helps brighten dull skin for a healthy, natural glow. It is formulated with Vitamin C along with turmeric, and suits both oily and dry skin. Dermatologically tested and free from parabens, sulphates and mineral oil, it can be used daily under your moisturiser.', '[["Brand","Mamaearth"],["Item form","Serum"],["Skin type","Oily and dry skin"],["Key ingredients","Vitamin C, turmeric"],["Use","Face, daily brightening"],["Suitable for","Men and women"],["Free from","Parabens, sulphates, mineral oil"]]'::jsonb, 219, 25, null, null, null),
  ('in-61vmEu4MuZL', 'IN', 'beauty', 'Minimalist 10% Vitamin C Face Serum for Glowing Skin, Brightening & Dark Spot Treatment', 'Minimalist', '/products/in/61vmEu4MuZL.jpg', 28400, null, null, false, 'Bestseller', '5K+ bought in past month', 'Minimalist Official Store', 'Amazon', array['Made for Indian skin and climate', 'Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow']::text[], 'The Minimalist 10% Vitamin C Face Serum targets dullness, uneven tone and dark spots for brighter-looking skin. It uses ethyl ascorbic acid, a stable form of Vitamin C, in a lightweight formula that absorbs quickly. Made with Indian skin and climate in mind, it is dermatologically tested and free from parabens, sulphates and mineral oil. Apply a few drops daily before moisturiser and sunscreen.', '[["Brand","Minimalist"],["Item form","Serum"],["Skin type","All skin types"],["Key ingredients","10% Vitamin C (ethyl ascorbic acid)"],["Use","Brightening, dark spot care"],["Free from","Parabens, sulphates, mineral oil"]]'::jsonb, 149, 26, null, null, null),
  ('in-515lLW9XLkL', 'IN', 'beauty', 'Minimalist Niacinamide 5% Face Serum with Hyaluronic Acid, Reduces Dark Spots, Controls Oil', 'Minimalist', '/products/in/515lLW9XLkL.jpg', 24900, 50900, 51, true, null, '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Made for Indian skin and climate', 'Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow']::text[], 'This Minimalist face serum combines 5% niacinamide with hyaluronic acid to help fade dark spots, control excess oil and keep skin hydrated. The niacinamide works on uneven tone and visible pores, while hyaluronic acid draws in moisture so skin does not feel tight. Formulated for Indian skin and climate, it is dermatologically tested and free from parabens, sulphates and mineral oil.', '[["Brand","Minimalist"],["Item form","Serum"],["Skin type","All skin types, including oily"],["Key ingredients","5% niacinamide, hyaluronic acid"],["Use","Dark spots, oil control"],["Free from","Parabens, sulphates, mineral oil"]]'::jsonb, 182, 27, null, null, null),
  ('in-51fdXXIWFL', 'IN', 'beauty', 'Mamaearth Rice Dewy Bright Face Wash with Rice Water & Niacinamide, 100ml', 'Mamaearth', '/products/in/51fdXXIWFL.jpg', 27500, null, null, false, 'Bestseller', '1K+ bought in past month', 'Mamaearth Official Store', 'Amazon', array['Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow', 'Suitable for all skin types']::text[], 'The Mamaearth Rice Dewy Bright Face Wash cleanses away dirt and excess oil while leaving skin soft and refreshed. It is formulated with rice water and niacinamide to help brighten skin for a dewy, glass-skin look. Dermatologically tested and free from parabens, sulphates and mineral oil, this 100 ml face wash is gentle enough for daily use on all skin types.', '[["Brand","Mamaearth"],["Item form","Face wash"],["Skin type","All skin types"],["Key ingredients","Rice water, niacinamide"],["Item volume","100 ml"],["Use","Daily face cleansing"],["Free from","Parabens, sulphates, mineral oil"]]'::jsonb, 73, 28, null, null, null),
  ('in-51c42aoYEeL', 'IN', 'beauty', 'Lakme Peach Milk Sunscreen Moisturiser SPF 50 PA+++ with Pro-Ceramides, 2-in-1 Daily Face Cream', 'Lakme', '/products/in/51c42aoYEeL.jpg', 30200, 36900, 18, true, null, null, 'Appario Retail Private Ltd', 'Amazon', array['Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow', 'Suitable for all skin types']::text[], 'The Lakme Peach Milk Sunscreen Moisturiser is a 2-in-1 daily face cream that hydrates skin while protecting it from the sun with SPF 50 PA+++. Enriched with peach milk and pro-ceramides, it helps keep skin soft and supports the moisture barrier. Its light cream texture layers easily under make-up, and it is dermatologically tested for everyday use on all skin types.', '[["Brand","Lakme"],["Item form","Cream"],["SPF","50"],["PA rating","PA+++"],["Key ingredients","Peach milk, pro-ceramides"],["Skin type","All skin types"],["Use","Daily moisturising and sun protection"]]'::jsonb, 34, 29, null, null, null),
  ('in-61BKbjrFySL', 'IN', 'beauty', 'Lotus Professional PhytoRx Sunblock Mist SPF 50 PA+++, Non-Greasy Finish, High Sun Protection', 'Lotus', '/products/in/61BKbjrFySL.jpg', 65100, 121900, 47, true, null, '500+ bought in past month', 'Lotus Official Store', 'Amazon', array['Made for Indian skin and climate', 'Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow']::text[], 'The Lotus Professional PhytoRx Sunblock Mist offers high sun protection with SPF 50 PA+++ in a convenient spray format. The fine mist spreads evenly over the skin and dries to a non-greasy finish, making it easy to reapply through the day, even on the go. Suited to Indian skin and climate, it is dermatologically tested for regular use.', '[["Brand","Lotus"],["Product line","Lotus Professional PhytoRx"],["Item form","Mist spray"],["SPF","50"],["PA rating","PA+++"],["Finish","Non-greasy"],["Use","Sun protection, easy reapplication"]]'::jsonb, 148, 30, null, null, null),
  ('in-61cZOENaP1L', 'IN', 'beauty', 'Mamaearth Korean Glass Skin Combo, Rice Face Wash 100ml + Rice Oil-Free Moisturizer 80g', 'Mamaearth', '/products/in/61cZOENaP1L.jpg', 43300, null, null, false, null, null, 'Appario Retail Private Ltd', 'Amazon', array['Made for Indian skin and climate', 'Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow']::text[], 'The Mamaearth Korean Glass Skin Combo pairs two rice-based essentials for a simple daily routine: the Rice Face Wash (100 ml) to cleanse away dirt and oil, and the Rice Oil-Free Moisturiser (80 g) to hydrate without a heavy feel. Inspired by the Korean glass-skin look, the duo helps skin appear smooth and luminous. Both are dermatologically tested and free from parabens, sulphates and mineral oil.', '[["Brand","Mamaearth"],["Item form","Face wash and moisturiser"],["Contents","Rice Face Wash 100 ml, Rice Oil-Free Moisturiser 80 g"],["Number of items","2"],["Key ingredient","Rice water"],["Skin type","All skin types"],["Use","Daily cleansing and moisturising"]]'::jsonb, 318, 31, null, null, null),
  ('in-81loPDFiwL', 'IN', 'books', 'The Housemaid: An Absolutely Addictive Psychological Thriller (The Housemaid, Book 1)', 'Freida McFadden', '/products/in/81loPDFiwL.jpg', 33500, 38900, 14, true, 'Bestseller', '10K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Millie is desperate for a fresh start, so when the wealthy Winchesters offer her a live-in job cleaning their beautiful Long Island home, it seems too good to be true. She gets a small room in the attic and a chance to leave her past behind. But Nina Winchester''s moods swing wildly, the house hides unsettling secrets, and Millie soon realises that some doors are locked for a reason. The first book in the Housemaid series.', '[["Author","Freida McFadden"],["Format","Paperback"],["Language","English"],["Genre","Psychological thriller"],["Series","The Housemaid, Book 1"],["Publisher","Bookouture"]]'::jsonb, 76, 32, null, null, null),
  ('in-7144dxKjVL', 'IN', 'books', 'The Art of War', 'Sun Tzu', '/products/in/7144dxKjVL.jpg', 11500, 13900, 17, true, 'Bestseller', '5K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'The Art of War is the ancient Chinese treatise on military strategy attributed to the general Sun Tzu. Across thirteen concise chapters, it examines planning, leadership, deception, terrain and the value of knowing both yourself and your opponent. Written more than two thousand years ago, its ideas are still studied today by readers in business, sport, politics and everyday decision-making.', '[["Author","Sun Tzu"],["Format","Paperback"],["Language","English"],["Genre","Classic non-fiction"],["Subject","Military strategy, philosophy"],["Chapters","13"]]'::jsonb, 166, 33, null, null, null),
  ('in-81Ypb9lrEQL', 'IN', 'books', 'War and Peace by Leo Tolstoy, Premium Classic Edition, Historical Fiction, Russian Literature', 'Leo Tolstoy', '/products/in/81Ypb9lrEQL.jpg', 59900, null, null, false, 'Amazon''s Choice', '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Leo Tolstoy''s War and Peace follows several aristocratic Russian families as Napoleon''s armies sweep across Europe and invade Russia. Through characters such as the restless Pierre Bezukhov, the ambitious Prince Andrei Bolkonsky and the spirited Natasha Rostova, the novel moves between glittering ballrooms and brutal battlefields. It is a sweeping portrait of love, ambition and history, presented here in a premium classic edition.', '[["Author","Leo Tolstoy"],["Format","Paperback"],["Language","English"],["Genre","Historical fiction"],["Edition","Premium Classic Edition"],["Original language","Russian"]]'::jsonb, 161, 34, null, null, null),
  ('in-81t6xQeZA8L', 'IN', 'books', 'The Stationery Shop of Tehran', 'Marjan Kamali', '/products/in/81t6xQeZA8L.jpg', 28300, null, null, false, 'Bestseller', '5K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'In the summer of 1953, seventeen-year-old Roya escapes the political unrest gripping Tehran by losing herself in the poetry and books of a small neighbourhood stationery shop. There she meets Bahman, a passionate young idealist, and the two fall deeply in love. When a planned meeting in the town square goes wrong amid the upheaval of a coup, they are torn apart. Decades later, in America, Roya is given an unexpected chance to learn what really happened.', '[["Author","Marjan Kamali"],["Format","Paperback"],["Language","English"],["Genre","Historical fiction, romance"],["Setting","Tehran and the United States"],["Type","Novel"]]'::jsonb, 208, 35, null, null, null),
  ('in-813P4lxRaLL', 'IN', 'books', 'Samsara: Enter the Valley of the Gods, Indian Mythological Fiction Novel', 'Saksham Garg', '/products/in/813P4lxRaLL.jpg', 21800, 25900, 16, true, null, '500+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Aman Chandra, a seventeen-year-old from Delhi, is abruptly taken from his ordinary life along with ten other chosen teenagers and brought to Vanyasa, a secret Himalayan valley where gods, immortal yogis and mythical creatures live. Given one year to master yogic magic before a dangerous journey, Aman also begins to uncover the truth about his father. This Indian mythological fantasy blends adventure, friendship and ancient lore.', '[["Author","Saksham Garg"],["Format","Paperback"],["Language","English"],["Genre","Indian mythological fantasy"],["Subtitle","Enter the Valley of the Gods"],["Publisher","Penguin Random House India"]]'::jsonb, 5, 36, null, null, null),
  ('in-81tmzGnqseL', 'IN', 'books', 'The Kalki Trilogy (Set of 3 Books): Avatar of Vishnu, Eye of Brahma and Sword of Shiva', 'Kevin Missal', '/products/in/81tmzGnqseL.jpg', 57900, 94900, 39, true, null, '500+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'This three-book set collects Kevin Missal''s Kalki trilogy, a retelling inspired by the legend of Kalki, the tenth avatar of Vishnu. In the village of Shambhala, young Kalki Hari discovers extraordinary abilities and a destiny that sets him against the ruthless Kali, who holds power over the land. Across Avatar of Vishnu, Eye of Brahma and Sword of Shiva, the story unfolds as an epic of battles, loyalty and dharma.', '[["Author","Kevin Missal"],["Format","Paperback"],["Language","English"],["Genre","Mythological fiction"],["Number of books","3"],["Publisher","HarperCollins India"]]'::jsonb, 99, 37, null, null, null),
  ('in-81AFx0AuGL', 'IN', 'books', 'The Best of Sherlock Holmes (Set of 2 Books), Adventures of Sherlock Holmes & Complete Novels', 'Arthur Conan Doyle', '/products/in/81AFx0AuGL.jpg', 36900, 56900, 35, true, 'Amazon''s Choice', null, 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'This two-book set brings together classic detective fiction by Arthur Conan Doyle, featuring Sherlock Holmes and his loyal companion Dr John Watson. One volume collects The Adventures of Sherlock Holmes, a series of short cases solved through sharp observation and deduction, while the other gathers the complete Holmes novels, including A Study in Scarlet and The Hound of the Baskervilles. Set largely in Victorian London, the stories remain gripping today.', '[["Author","Arthur Conan Doyle"],["Format","Paperback"],["Language","English"],["Genre","Detective fiction"],["Number of books","2"],["Contents","Short stories and complete novels"]]'::jsonb, 164, 38, null, null, null),
  ('in-710oqNs2JL', 'IN', 'toys', 'Novo Baby Smart Activity Fun & Learning Blocks, Geometric Educational Sorter Toy', 'Novo', '/products/in/710oqNs2JL.jpg', 18000, null, null, false, null, '500+ bought in past month', 'Novo Official Store', 'Amazon', array['Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present', 'Recommended for hours of independent fun']::text[], 'The Novo Baby Smart Activity Fun & Learning Blocks set is a geometric shape sorter that helps little ones learn shapes and colours through hands-on play. Children match each block to the right opening, building hand-eye coordination, fine motor skills and early problem-solving. Made from kid-safe, durable materials, it offers screen-free fun at home and makes a thoughtful birthday or return gift.', '[["Brand","Novo"],["Toy type","Shape sorter"],["Educational focus","Shapes, colours, motor skills"],["Batteries","Not required"],["Material","Kid-safe, durable materials"],["Play type","Screen-free, hands-on"]]'::jsonb, 36, 39, null, null, null),
  ('in-71VAUdhYJGL', 'IN', 'toys', 'Novo Baby Wooden ABCD Learning Board for Kids, Activity Toy for Toddlers & Preschoolers', 'Novo', '/products/in/71VAUdhYJGL.jpg', 27400, 49900, 45, true, 'Limited time deal', null, 'Novo Official Store', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'The Novo Baby Wooden ABCD Learning Board introduces toddlers and preschoolers to the alphabet through tactile, hands-on play. Children can explore each letter by sight and touch, building letter recognition, early vocabulary and fine motor skills along the way. The sturdy wooden construction is made to handle daily use, and the screen-free design encourages focused, independent learning at home or in the classroom.', '[["Brand","Novo"],["Material","Wood"],["Recommended age","Toddlers and preschoolers"],["Toy type","Learning board"],["Educational focus","Alphabet, letter recognition"],["Batteries","Not required"]]'::jsonb, 29, 40, null, null, null),
  ('in-61vq6mEiQ7L', 'IN', 'toys', 'Storio Montessori Talking Flash Cards for Kids 2-5 Years, Rechargeable Educational Learning Toy', 'Storio', '/products/in/61vq6mEiQ7L.jpg', 32800, 44900, 27, true, null, null, 'RetailEZ Private Limited', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'The Storio Montessori Talking Flash Cards make early learning interactive for children aged 2 to 5 years. Slide a card into the reader and it speaks the word aloud, helping kids learn new words and build vocabulary through repetition. The rechargeable device avoids the need for disposable batteries, and the screen-free format keeps young learners engaged without a phone or tablet.', '[["Brand","Storio"],["Recommended age","2-5 years"],["Toy type","Talking flash card reader"],["Batteries","Rechargeable"],["Educational focus","Vocabulary, early language"],["Play type","Screen-free"]]'::jsonb, 233, 41, null, null, null),
  ('in-810NYpQWZ1L', 'IN', 'toys', 'Eitheo Kids Learning Phone Toy, Rechargeable Talking Mobile for Kids 2-6 Years, 24 Activities', 'Eitheo', '/products/in/810NYpQWZ1L.jpg', 33800, null, null, false, null, null, 'Eitheo Official Store', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'The Eitheo Kids Learning Phone is a rechargeable talking toy mobile for children aged 2 to 6 years, packed with 24 learning activities. Kids can press the buttons to explore sounds, voices and learning games while practising pretend phone calls. It builds curiosity, listening and fine motor skills, and the rechargeable battery means no frequent battery changes. It is a screen-free alternative to handing over a real phone.', '[["Brand","Eitheo"],["Recommended age","2-6 years"],["Toy type","Toy learning phone"],["Activities","24"],["Batteries","Rechargeable"],["Educational focus","Listening, early learning"]]'::jsonb, 70, 42, null, null, null),
  ('in-71PRHle65CL', 'IN', 'toys', 'Kids Phone Rechargeable Toy with 24 Learning Modes, Talking Dummy Mobile for Kids 2-12', null, '/products/in/71PRHle65CL.jpg', 38400, null, null, false, null, null, 'Appario Retail Private Ltd', 'Amazon', array['Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present', 'Recommended for hours of independent fun']::text[], 'This rechargeable kids phone toy offers 24 learning modes in a pretend mobile designed for children aged 2 to 12. Children can tap through talking features and learning activities while imitating grown-up phone calls, which builds curiosity and early learning skills. Made from kid-safe, durable materials, it provides screen-free entertainment and is easy to recharge instead of replacing batteries.', '[["Brand","Generic"],["Recommended age","2-12 years"],["Toy type","Toy learning phone"],["Learning modes","24"],["Batteries","Rechargeable"],["Play type","Screen-free, pretend play"]]'::jsonb, 249, 43, null, null, null),
  ('in-817az4dHG2L', 'IN', 'toys', 'Eitheo Geometric Angle Blocks for Kids, 26 Pcs Montessori Sorting & Stacking Educational Toy', 'Eitheo', '/products/in/817az4dHG2L.jpg', 13800, null, null, false, null, '500+ bought in past month', 'Eitheo Official Store', 'Amazon', array['Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present', 'Recommended for hours of independent fun']::text[], 'The Eitheo Geometric Angle Blocks set includes 26 pieces for Montessori-style sorting and stacking play. Children can arrange the blocks by shape and angle, stack them into towers or create their own patterns, developing spatial awareness, early geometry and hand-eye coordination. Made from kid-safe, durable materials, the set encourages open-ended, screen-free play and makes a thoughtful return gift.', '[["Brand","Eitheo"],["Pieces","26"],["Toy type","Sorting and stacking blocks"],["Educational focus","Shapes, angles, spatial skills"],["Batteries","Not required"],["Play style","Montessori-inspired"]]'::jsonb, 283, 44, null, null, null),
  ('in-61qEWRcwEUL', 'IN', 'sports', 'Flexnest Adjustable Iron Dumbbells Set, Easy Weight Adjustment 2.5kg-24kg, Home Workout', 'Flexnest', '/products/in/61qEWRcwEUL.jpg', 1699800, null, null, false, null, null, 'Appario Retail Private Ltd', 'Amazon', array['Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle', 'Ideal for home strength training']::text[], 'The Flexnest Adjustable Iron Dumbbells Set lets you change weights easily from 2.5 kg up to 24 kg, so one compact set can replace a rack of fixed dumbbells. Iron construction gives a solid, durable feel, and the secure locking mechanism keeps the plates in place during lifts. The non-slip grip handle adds control, making it well suited to curls, presses, rows and full-body home workouts.', '[["Brand","Flexnest"],["Weight range","2.5 kg to 24 kg"],["Material","Iron"],["Type","Adjustable dumbbells"],["Locking","Secure weight lock"],["Grip","Non-slip handle"],["Use","Home strength training"]]'::jsonb, 351, 45, null, null, null),
  ('in-618Nlj8pN3L', 'IN', 'sports', 'Burnlab 6-in-1 Multifunctional Weight Training Kit, Dumbbells, Kettlebells, Barbells & Push-up Brackets', 'Burnlab', '/products/in/618Nlj8pN3L.jpg', 419900, 540900, 22, true, null, null, 'Cloudtail India', 'Amazon', array['Adjustable weight adapts as your strength grows', 'Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle']::text[], 'The Burnlab 6-in-1 Multifunctional Weight Training Kit is a versatile home gym set that converts between dumbbells, kettlebells, a barbell and push-up brackets. The adjustable weight lets you increase the load as your strength grows, and the secure locking mechanism keeps everything firmly in place. Non-slip grips add control, and the space-saving design covers full-body training without a bulky rack.', '[["Brand","Burnlab"],["Type","6-in-1 weight training kit"],["Configurations","Dumbbells, kettlebells, barbell, push-up brackets"],["Weight","Adjustable"],["Grip","Non-slip"],["Use","Home strength training"]]'::jsonb, 113, 46, null, null, null),
  ('in-71WvlgmKiL', 'IN', 'sports', 'Amazon Brand Symactive PVC 3-in-1 Convertible Dumbbells Set', 'Symactive', '/products/in/71WvlgmKiL.jpg', 65900, 111900, 41, true, null, '100+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['Adjustable weight adapts as your strength grows', 'Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle']::text[], 'The Symactive PVC 3-in-1 Convertible Dumbbells Set lets you switch between three training configurations, making it a versatile addition to a home gym. The PVC plates are easy to wipe clean, and the weight can be adjusted as your strength improves. A secure locking mechanism keeps the plates in place, while non-slip grip handles support safer, more controlled lifting.', '[["Brand","Symactive"],["Type","3-in-1 convertible dumbbell set"],["Material","PVC"],["Weight","Adjustable"],["Locking","Secure locking mechanism"],["Grip","Non-slip handle"]]'::jsonb, 372, 47, null, null, null),
  ('in-61NEUWb5A4L', 'IN', 'sports', 'Amazon Brand Symactive 20 Kg Adjustable Dumbbell Set, Durable PVC Plates with Secure Weight-Locking', 'Symactive', '/products/in/61NEUWb5A4L.jpg', 79900, 91900, 13, true, null, '500+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Adjustable weight adapts as your strength grows', 'Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle']::text[], 'The Symactive 20 kg Adjustable Dumbbell Set uses durable PVC weight plates that you can add or remove to match your workout, from light toning to heavier strength sessions. A secure weight-locking system holds the plates firmly on the rods during lifts. The non-slip grip handles provide control, and the space-saving set is well suited to building a compact home gym.', '[["Brand","Symactive"],["Total weight","20 kg"],["Material","PVC plates"],["Type","Adjustable dumbbell set"],["Locking","Secure weight lock"],["Grip","Non-slip handle"],["Use","Home workouts"]]'::jsonb, 227, 48, null, null, null),
  ('in-51RCPRgChnL', 'IN', 'sports', 'FitBox Sports Intruder 20 Kg Adjustable PVC Dumbbells with Rods for Home Gym & Strength Training', 'FitBox', '/products/in/51RCPRgChnL.jpg', 74900, null, null, false, null, '1K+ bought in past month', 'FitBox Official Store', 'Amazon', array['Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle', 'Ideal for home strength training']::text[], 'The FitBox Sports Intruder set gives you 20 kg of adjustable PVC weight plates along with dumbbell rods, so you can set up a home gym for strength training. Add or remove plates to adjust the load for curls, presses, rows and more. The secure locking mechanism keeps the plates firmly in place, and the non-slip grip helps you maintain control through every rep.', '[["Brand","FitBox"],["Model name","Intruder"],["Total weight","20 kg"],["Material","PVC plates"],["Included components","PVC weight plates, dumbbell rods"],["Grip","Non-slip handle"],["Use","Home gym, strength training"]]'::jsonb, 91, 49, null, null, null),
  ('in-71br5ecT1kL', 'IN', 'sports', 'Sparnod Fitness SAD 12.5 Adjustable Dumbbell, 12.5kg with 11 Weight Increments', 'Sparnod', '/products/in/71br5ecT1kL.jpg', 699900, null, null, false, null, null, 'Cocoblu Retail', 'Amazon', array['Adjustable weight adapts as your strength grows', 'Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle']::text[], 'The Sparnod Fitness SAD 12.5 is an adjustable dumbbell that goes up to 12.5 kg, with 11 weight increments to choose from. Changing the load is quick, so you can move between exercises without swapping equipment, and the compact design takes up far less space than a set of fixed dumbbells. A secure locking mechanism and non-slip grip keep each lift steady and controlled.', '[["Brand","Sparnod"],["Model","SAD 12.5"],["Maximum weight","12.5 kg"],["Weight increments","11"],["Type","Adjustable dumbbell"],["Grip","Non-slip handle"],["Use","Home strength training"]]'::jsonb, 197, 50, null, null, null),
  ('in-710aan3QRaL', 'IN', 'sports', 'Sparnod Fitness SAD-25 Adjustable 3-in-1 Dumbbell Set, 3-24kg Quick Weight Change, Barbell, Kettlebell', 'Sparnod', '/products/in/710aan3QRaL.jpg', 1199900, null, null, false, null, null, 'Sparnod Official Store', 'Amazon', array['Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle', 'Ideal for home strength training']::text[], 'The Sparnod Fitness SAD-25 is a 3-in-1 adjustable set that works as dumbbells, a barbell or a kettlebell, with weights ranging from 3 kg to 24 kg. Quick weight changes make it easy to switch between exercises mid-workout. The space-saving design replaces several pieces of equipment, while secure locking and a non-slip grip help keep every lift safe and controlled.', '[["Brand","Sparnod"],["Model","SAD-25"],["Weight range","3 kg to 24 kg"],["Type","3-in-1 adjustable dumbbell set"],["Configurations","Dumbbell, barbell, kettlebell"],["Grip","Non-slip handle"],["Use","Home strength training"]]'::jsonb, 308, 51, null, null, null),
  ('in-51nBTTG3hNL', 'IN', 'electronics', 'OnePlus Nord Buds 3r TWS Earbuds, up to 54H Playback, 2-Mic Clear Calls, 3D Spatial Audio, 12.4mm Drivers, Bluetooth 5.4', 'OnePlus', '/products/in/51nBTTG3hNL.jpg', 199900, null, null, false, null, '5K+ bought in past month', 'OnePlus Official Store', 'Amazon', array['Immersive sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play']::text[], 'The OnePlus Nord Buds 3r are true wireless earbuds with 12.4 mm drivers and 3D spatial audio for a wide, immersive soundstage. With the charging case, they deliver up to 54 hours of total playback. A two-mic setup helps keep calls clear, and Bluetooth 5.4 provides a stable connection with your phone. The compact case slips easily into a pocket for everyday use.', '[["Brand","OnePlus"],["Model name","Nord Buds 3r"],["Form factor","True wireless, in-ear"],["Connectivity","Bluetooth 5.4"],["Driver size","12.4 mm"],["Battery life","Up to 54 hours with case"],["Microphone","2 mics for calls"],["Audio","3D spatial audio"]]'::jsonb, 88, 52, null, null, null),
  ('in-61vEGUBSswL', 'IN', 'electronics', 'Noise Buds Mini Truly Wireless Earbuds (2026), Half In-Ear Design, 40H Playtime, Quad Mic ENC, 13mm Driver, Bluetooth 5.3', 'Noise', '/products/in/61vEGUBSswL.jpg', 89900, null, null, false, null, '1K+ bought in past month', 'Noise Official Store', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play', 'Comfortable cushions for all-day wear']::text[], 'The 2026 Noise Buds Mini are compact true wireless earbuds with a half in-ear design that sits lightly in the ear without a deep seal. 13 mm drivers deliver lively sound, and a quad-mic setup with environmental noise cancellation helps keep your voice clear on calls. Total playtime reaches up to 40 hours with the case, and Bluetooth 5.3 keeps the connection steady.', '[["Brand","Noise"],["Model name","Buds Mini (2026)"],["Form factor","True wireless, half in-ear"],["Connectivity","Bluetooth 5.3"],["Driver size","13 mm"],["Battery life","Up to 40 hours with case"],["Microphone","Quad mic with ENC"]]'::jsonb, 149, 53, null, null, null),
  ('in-71FOccCOQmL', 'IN', 'electronics', 'boAt Airdopes 219 TWS Earbuds, 4 Mics ENx Tech, 40H Battery, App Support, Bluetooth Wireless, Fast Charging', 'boAt', '/products/in/71FOccCOQmL.jpg', 109900, null, null, false, null, '1K+ bought in past month', 'boAt Official Store', 'Amazon', array['Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play', 'Comfortable cushions for all-day wear']::text[], 'The boAt Airdopes 219 are true wireless earbuds designed for everyday listening and calls. Four mics with ENx technology help filter background noise so your voice stays clear, and total playback reaches up to 40 hours with the charging case. Fast charging gets you back to your music quickly, while app support lets you manage settings from your smartphone.', '[["Brand","boAt"],["Model name","Airdopes 219"],["Form factor","True wireless, in-ear"],["Connectivity","Bluetooth"],["Battery life","Up to 40 hours with case"],["Microphone","4 mics with ENx technology"],["Charging","Fast charging, USB Type-C"],["App support","Yes"]]'::jsonb, 368, 54, null, null, null),
  ('in-81TGXuOMAL', 'IN', 'electronics', 'boAt Nirvana Ion TWS Earbuds, 120H Battery, Crystal Bionic Sound, Dual EQ Modes, 4 Mics ENx, IPX4, Bluetooth 5.2', 'boAt', '/products/in/81TGXuOMAL.jpg', 179900, 308900, 42, true, null, '5K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Immersive sound with deep, punchy bass', 'Bluetooth 5.3 stable wireless connection up to 10 m', 'Built-in mic with ENx tech for clear calls', 'Fast USB-C charging — 10 min for hours of play']::text[], 'The boAt Nirvana Ion true wireless earbuds offer up to 120 hours of total playback with the charging case, making them well suited to long trips. Crystal Bionic Sound and dual EQ modes let you switch between sound profiles, while four mics with ENx technology keep calls clear. An IPX4 rating protects against sweat and splashes, and Bluetooth 5.2 provides a stable connection.', '[["Brand","boAt"],["Model name","Nirvana Ion"],["Form factor","True wireless, in-ear"],["Connectivity","Bluetooth 5.2"],["Battery life","Up to 120 hours with case"],["Microphone","4 mics with ENx technology"],["Sound","Crystal Bionic Sound, dual EQ modes"],["Water resistance","IPX4"]]'::jsonb, 79, 55, null, null, null),
  ('in-71r2ySSfgBL', 'IN', 'computers', 'HP Victus Gaming Laptop, AMD Ryzen 7 7445HS, 6GB RTX 4050, 16GB DDR5, 512GB SSD, 15.6" FHD 144Hz IPS, Windows 11', 'HP', '/products/in/71r2ySSfgBL.jpg', 10799000, null, null, false, null, null, 'HP Official Store', 'Amazon', array['Snappy everyday performance for work and study', 'Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds']::text[], 'The HP Victus gaming laptop combines an AMD Ryzen 7 7445HS processor with NVIDIA GeForce RTX 4050 graphics carrying 6 GB of dedicated memory, enough to run popular games and creative apps at Full HD. Its 15.6-inch IPS display refreshes at 144 Hz for smoother motion in fast-paced titles. 16 GB of DDR5 RAM and a 512 GB SSD keep loading times short, and Windows 11 comes pre-installed.', '[["Brand","HP"],["Model name","Victus Gaming Laptop"],["Screen size","15.6 inches"],["Display","Full HD IPS, 144 Hz"],["Processor","AMD Ryzen 7 7445HS"],["Graphics","NVIDIA GeForce RTX 4050, 6 GB"],["RAM","16 GB DDR5"],["Storage","512 GB SSD"],["Operating system","Windows 11"]]'::jsonb, 4, 56, null, null, null),
  ('in-61aLy7kImQL', 'IN', 'computers', 'HP OmniBook 5 OLED (Previously Pavilion), Snapdragon X 45 TOPS, 16GB LPDDR5x, 512GB SSD, 2K 14" Display, Windows 11', 'HP', '/products/in/61aLy7kImQL.jpg', 7999000, null, null, false, null, null, 'HP Official Store', 'Amazon', array['Snappy everyday performance for work and study', 'Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds']::text[], 'The HP OmniBook 5 OLED, successor to the Pavilion line, is a 14-inch laptop powered by the Qualcomm Snapdragon X processor with an NPU rated at 45 TOPS for on-device AI features in Windows 11. The 2K OLED display delivers deep blacks and vivid colour, and 16 GB of LPDDR5x memory with a 512 GB SSD keeps everyday work responsive. Its efficient Arm-based chip is designed for long battery life.', '[["Brand","HP"],["Model name","OmniBook 5 OLED"],["Screen size","14 inches"],["Display","2K OLED"],["Processor","Qualcomm Snapdragon X"],["AI performance","NPU up to 45 TOPS"],["RAM","16 GB LPDDR5x"],["Storage","512 GB SSD"],["Operating system","Windows 11"]]'::jsonb, 256, 57, null, null, null),
  ('in-41bdNUDc8pL', 'IN', 'computers', 'Acer Aspire 3 Laptop, Intel Celeron N4500, 8GB LPDDR4X, 256GB SSD, 15.6" HD, Windows 11 Home, HD Webcam', 'Acer', '/products/in/41bdNUDc8pL.jpg', 3564000, 5031900, 29, true, null, null, 'Cloudtail India', 'Amazon', array['Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds', 'Windows 11 with lifetime validity']::text[], 'The Acer Aspire 3 is an entry-level 15.6-inch laptop for basic everyday computing, powered by an Intel Celeron N4500 processor. It comes with 8 GB of LPDDR4X memory and a 256 GB SSD, which boots faster than a traditional hard drive. The HD display and built-in HD webcam cover online classes, video calls, browsing and document work, and Windows 11 Home is pre-installed.', '[["Brand","Acer"],["Model name","Aspire 3"],["Screen size","15.6 inches"],["Resolution","HD"],["Processor","Intel Celeron N4500"],["RAM","8 GB LPDDR4X"],["Storage","256 GB SSD"],["Webcam","HD"],["Operating system","Windows 11 Home"]]'::jsonb, 100, 58, null, null, null),
  ('in-71D9HSayVSL', 'IN', 'computers', 'Lenovo IdeaPad Slim 3, 13th Gen Intel Core i5-13420H, 24GB RAM, 1TB SSD, 15.3" WUXGA IPS, Windows 11, Office 2024', 'Lenovo', '/products/in/71D9HSayVSL.jpg', 8769000, 10115900, 13, true, null, null, 'Appario Retail Private Ltd', 'Amazon', array['Crisp Full-HD anti-glare display', 'All-day battery for work on the go', 'Fast SSD storage boots in seconds', 'Windows 11 with lifetime validity']::text[], 'The Lenovo IdeaPad Slim 3 pairs a 13th Gen Intel Core i5-13420H processor with a generous 24 GB of RAM and a 1 TB SSD, giving plenty of room for multitasking and large files. Its 15.3-inch WUXGA IPS display has a 16:10 aspect ratio that shows more of each page. Windows 11 and Office 2024 come included, so it is ready for study and work straight out of the box.', '[["Brand","Lenovo"],["Model name","IdeaPad Slim 3"],["Screen size","15.3 inches"],["Display","WUXGA IPS"],["Processor","Intel Core i5-13420H (13th Gen)"],["RAM","24 GB"],["Storage","1 TB SSD"],["Operating system","Windows 11"],["Software","Microsoft Office 2024"]]'::jsonb, 48, 59, null, null, null),
  ('in-51K1LMDAvkL', 'IN', 'home-kitchen', 'Hawkins 3 Litre Contura Black Pressure Cooker, Hard Anodised Inner Lid Cooker, Handi Cooker, Induction & Gas (CB30)', 'Hawkins', '/products/in/51K1LMDAvkL.jpg', 205900, null, null, false, 'Bestseller', '5K+ bought in past month', 'Hawkins Official Store', 'Amazon', array['Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking', 'Backed by a manufacturer warranty']::text[], 'The Hawkins Contura Black 3 litre is a hard anodised inner lid pressure cooker with a handi-style curved body that makes stirring and serving easier. The hard anodised surface is tough enough for daily cooking, and the inner lid is sealed from within by steam pressure for safe operation. It works on induction and gas cooktops, and the 3 litre capacity suits families of three to four.', '[["Brand","Hawkins"],["Model","CB30"],["Capacity","3 litres"],["Material","Hard anodised aluminium"],["Lid type","Inner lid"],["Body shape","Handi, curved Contura body"],["Compatible cooktops","Induction and gas"],["Colour","Black"]]'::jsonb, 191, 60, 'hawkins-contura-black', 'Size', '3 Litre'),
  ('in-51z8bjUc4kL', 'IN', 'home-kitchen', 'Hawkins Classic 2 Litre Pressure Cooker, Straight Body, Gas Compatible, Ideal for 2-3 Persons, ISI Certified', 'Hawkins', '/products/in/51z8bjUc4kL.jpg', 127600, 191900, 34, true, 'Bestseller', '5K+ bought in past month', 'Hawkins Official Store', 'Amazon', array['Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking', 'Backed by a manufacturer warranty']::text[], 'The Hawkins Classic 2 litre pressure cooker has a straight aluminium body and the traditional Hawkins inner lid, which seals from within under steam pressure. Sized for two to three people, it handles daily dal, rice and vegetables quickly on a gas stove. The cooker is ISI certified, and its lightweight build heats up fast to save cooking time and fuel.', '[["Brand","Hawkins"],["Model name","Classic"],["Capacity","2 litres"],["Material","Aluminium"],["Lid type","Inner lid"],["Compatible cooktops","Gas"],["Suitable for","2-3 persons"],["Certification","ISI"]]'::jsonb, 312, 61, null, null, null),
  ('in-510szauOgxL', 'IN', 'home-kitchen', 'Pigeon by Stovekraft All in One Super Cooker 620-H, 3 Litre Hard Anodised Outer Lid Pressure Cooker, Black Aluminium', 'Pigeon', '/products/in/510szauOgxL.jpg', 199900, 316900, 37, true, null, '1K+ bought in past month', 'Pigeon Official Store', 'Amazon', array['ISI-marked, made in India for everyday cooking', 'Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking']::text[], 'The Pigeon All in One Super Cooker 620-H is a 3 litre hard anodised aluminium pressure cooker with an outer lid that is quick to open and close. Its black hard anodised finish is durable and resists everyday wear, and the versatile design is meant to take on a range of daily dishes in a single vessel. It works on gas and induction cooktops and carries the ISI mark.', '[["Brand","Pigeon"],["Model","620-H"],["Capacity","3 litres"],["Material","Hard anodised aluminium"],["Lid type","Outer lid"],["Compatible cooktops","Gas and induction"],["Colour","Black"]]'::jsonb, 316, 62, null, null, null),
  ('in-51ZHXd88HjL', 'IN', 'home-kitchen', 'Butterfly Curve 2 Litre Stainless Steel Outer Lid Pressure Cooker, Triply Base, Induction & Gas Stove Compatible', 'Butterfly', '/products/in/51ZHXd88HjL.jpg', 153900, null, null, false, 'Bestseller', '5K+ bought in past month', 'Butterfly Official Store', 'Amazon', array['Works on gas and induction cooktops', 'Sturdy build with a secure locking lid', 'Even heat for faster, fuel-saving cooking', 'Backed by a manufacturer warranty']::text[], 'The Butterfly Curve 2 litre pressure cooker is made of stainless steel with a triply base that spreads heat evenly and helps prevent food from sticking or burning. The outer lid is easy to open and close, and the cooker works on both induction and gas stoves. Its curved body and 2 litre capacity make it handy for small families and everyday cooking.', '[["Brand","Butterfly"],["Model name","Curve"],["Capacity","2 litres"],["Material","Stainless steel"],["Base","Triply"],["Lid type","Outer lid"],["Compatible cooktops","Induction and gas"]]'::jsonb, 118, 63, null, null, null),
  ('in-712NemmvADL', 'IN', 'fashion', 'SPARX Women Pull-On Sneaker Shoes, Lightweight Slip-On Running & Walking Shoes', 'Sparx', '/products/in/712NemmvADL.jpg', 69900, 102900, 32, true, 'Bestseller', '1K+ bought in past month', 'Sparx Official Store', 'Amazon', array['Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking', 'Everyday comfort for Indian roads and weather']::text[], 'These Sparx pull-on sneakers for women slip on and off without laces, making them easy to wear for quick errands, walks and light runs. The lightweight build keeps feet from feeling weighed down, while a cushioned sole absorbs impact with every step. An anti-skid outsole provides grip on everyday surfaces, and the simple silhouette pairs well with casual and athleisure outfits.', '[["Brand","Sparx"],["Department","Women"],["Shoe type","Sneakers"],["Closure","Pull-on (slip-on)"],["Outsole","Cushioned, anti-skid"],["Use","Running and walking"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 368, 64, null, null, null),
  ('in-61IZBgcmGL', 'IN', 'fashion', 'Campus Women Claire Running Shoes, Cushioned Lace-Up Sports Shoes', 'Campus', '/products/in/61IZBgcmGL.jpg', 107900, null, null, false, null, '1K+ bought in past month', 'Campus Official Store', 'Amazon', array['Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking', 'Everyday comfort for Indian roads and weather']::text[], 'The Campus Claire running shoes for women offer cushioned comfort for daily workouts and walks. The padded sole absorbs impact as you move, while the anti-skid outsole helps keep your footing steady on roads and gym floors. A lace-up closure gives a secure, adjustable fit, and the sporty design works for both exercise and casual outings.', '[["Brand","Campus"],["Model name","Claire"],["Department","Women"],["Shoe type","Running shoes"],["Closure","Lace-up"],["Outsole","Cushioned, anti-skid"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 142, 65, null, null, null),
  ('in-61vRXtZcy7L', 'IN', 'fashion', 'ASIAN Women Sports Running Shoes, Walking, Gym Casual Lace-Up Sneakers for Girls', 'ASIAN', '/products/in/61vRXtZcy7L.jpg', 69900, null, null, false, 'Bestseller', '1K+ bought in past month', 'ASIAN Official Store', 'Amazon', array['Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking', 'Everyday comfort for Indian roads and weather']::text[], 'These ASIAN sports running shoes for women and girls are made for walking, gym workouts and casual wear. A cushioned sole helps absorb impact over long days on your feet, while the anti-skid outsole gives dependable grip. The lace-up sneaker design offers an adjustable fit and a sporty look that pairs easily with jeans or activewear.', '[["Brand","ASIAN"],["Department","Women"],["Shoe type","Running shoes, sneakers"],["Closure","Lace-up"],["Outsole","Cushioned, anti-skid"],["Use","Running, walking, gym and casual"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 398, 66, null, null, null),
  ('in-61abSFH0qL', 'IN', 'fashion', 'Campus Women Alice Running Shoes, Breathable Lace-Up Everyday Trainers', 'Campus', '/products/in/61abSFH0qL.jpg', 91900, 190900, 52, true, 'Limited time deal', '1K+ bought in past month', 'Campus Official Store', 'Amazon', array['Lightweight, breathable mesh upper keeps feet cool', 'Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking']::text[], 'The Campus Alice running shoes for women are breathable, lace-up everyday trainers designed for comfort from morning walks to evening workouts. A mesh upper allows air to flow and keeps feet cool, while the cushioned sole softens each stride. The anti-skid outsole provides reliable grip, and the lace-up closure lets you fine-tune the fit.', '[["Brand","Campus"],["Model name","Alice"],["Department","Women"],["Shoe type","Running shoes, everyday trainers"],["Closure","Lace-up"],["Upper material","Breathable mesh"],["Outsole","Cushioned, anti-skid"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 383, 67, null, null, null),
  ('in-61tvXQQDhL', 'IN', 'beauty', 'Minimalist Sunscreen SPF 50 PA++++ with Niacinamide & Multi-Vitamins, Broad Spectrum, Hydrating for Dry & All Skin, 50g', 'Minimalist', '/products/in/61tvXQQDhL.jpg', 24500, 40900, 40, true, 'Bestseller', '5K+ bought in past month', 'Minimalist Official Store', 'Amazon', array['Made for Indian skin and climate', 'Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow']::text[], 'The Minimalist SPF 50 PA++++ sunscreen offers broad-spectrum protection against UVA and UVB rays in a hydrating formula suited to dry and all skin types. It is enriched with niacinamide and multi-vitamins to care for skin while shielding it from the sun. Made for Indian skin and climate, the 50 g tube is dermatologically tested and easy to wear every day.', '[["Brand","Minimalist"],["SPF","50"],["PA rating","PA++++"],["Protection","Broad spectrum (UVA and UVB)"],["Key ingredients","Niacinamide, multi-vitamins"],["Skin type","Dry and all skin types"],["Item weight","50 g"]]'::jsonb, 4, 68, null, null, null),
  ('in-51gQUz3N6ZL', 'IN', 'beauty', 'The Derma Co 1% Hyaluronic Sunscreen Aqua Gel SPF 50 PA++++, Hydrating, Lightweight & Non-Greasy, No White Cast, 50g', 'The Derma Co', '/products/in/51gQUz3N6ZL.jpg', 23300, null, null, false, 'Bestseller', '5K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Made for Indian skin and climate', 'Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow']::text[], 'The Derma Co 1% Hyaluronic Sunscreen Aqua Gel provides SPF 50 PA++++ protection in a lightweight gel texture that absorbs quickly. Hyaluronic acid helps keep skin hydrated, and the non-greasy formula leaves no white cast, making it comfortable for daily wear under make-up or on its own. Designed for Indian skin and climate, this 50 g sunscreen is dermatologically tested.', '[["Brand","The Derma Co"],["Item form","Gel"],["SPF","50"],["PA rating","PA++++"],["Key ingredients","1% hyaluronic acid"],["Finish","Non-greasy, no white cast"],["Item weight","50 g"]]'::jsonb, 324, 69, null, null, null),
  ('in-51Y0eeQykEL', 'IN', 'beauty', 'Aqualogica Glow+ Dewy Gel Sunscreen SPF 50+ PA++++, In-Vivo Tested, New-Age UV Filters, 12-Hour Sun Protection, 80g', 'Aqualogica', '/products/in/51Y0eeQykEL.jpg', 36800, 46900, 22, true, 'Bestseller', '5K+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['Made for Indian skin and climate', 'Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow']::text[], 'The Aqualogica Glow+ Dewy Gel Sunscreen offers SPF 50+ PA++++ protection using new-age UV filters, with in-vivo testing behind its sun protection claims. The light gel texture leaves a dewy, radiant finish and is formulated to provide up to 12 hours of sun protection. Suited to Indian skin and climate, the 80 g sunscreen is dermatologically tested and easy to wear every day.', '[["Brand","Aqualogica"],["Item form","Gel"],["SPF","50+"],["PA rating","PA++++"],["Finish","Dewy"],["Protection","Up to 12 hours, in-vivo tested"],["Item weight","80 g"]]'::jsonb, 256, 70, null, null, null);
insert into public.products (id, market_id, category_slug, title, brand, image, price_minor, list_minor, deal_pct, deal, badge, bought_past_month, seller, ships_from, bullets, description, details, stock, position, variant_group, variant_axis, variant_label) values
  ('in-61ckTgN44WL', 'IN', 'beauty', 'Dot & Key Vitamin C + E Super Bright Sunscreen SPF 50+ PA++++, In-Vivo Tested, Water-Light Fluid, No White Cast, 50g', 'Dot & Key', '/products/in/61ckTgN44WL.jpg', 39600, null, null, false, 'Bestseller', '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow', 'Suitable for all skin types']::text[], 'The Dot & Key Vitamin C + E Super Bright Sunscreen combines SPF 50+ PA++++ sun protection with Vitamins C and E to help brighten skin and support an even tone. Its water-light fluid texture spreads easily and leaves no white cast, and its protection has been in-vivo tested. The 50 g sunscreen is dermatologically tested and suits all skin types for daily use.', '[["Brand","Dot & Key"],["Item form","Fluid"],["SPF","50+"],["PA rating","PA++++"],["Key ingredients","Vitamin C, Vitamin E"],["Finish","No white cast"],["Skin type","All skin types"],["Item weight","50 g"]]'::jsonb, 69, 71, null, null, null),
  ('in-A1dtQsoQEL', 'IN', 'books', 'The Palace of Illusions: 15th Anniversary Edition by Chitra Banerjee Divakaruni', 'Chitra Banerjee Divakaruni', '/products/in/A1dtQsoQEL.jpg', 33000, 47900, 31, true, 'Amazon''s Choice', '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'The Palace of Illusions retells the Mahabharata through the eyes of Panchaali, better known as Draupadi, who is born from fire and destined to change the course of history. From her lonely childhood in her father''s palace to her marriage to the five Pandava brothers and the great war that follows, she shares her hopes, frustrations and complicated friendships. This 15th anniversary edition celebrates a much-loved feminist retelling of the epic.', '[["Author","Chitra Banerjee Divakaruni"],["Format","Paperback"],["Language","English"],["Genre","Mythological fiction"],["Edition","15th Anniversary Edition"],["Based on","The Mahabharata"]]'::jsonb, 263, 72, null, null, null),
  ('in-61qTWmEi5GL', 'IN', 'books', 'Never Lie: An Addictive Psychological Thriller with Mind-Bending Twists by Freida McFadden', 'Freida McFadden', '/products/in/61qTWmEi5GL.jpg', 35500, 41900, 15, true, null, '10K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Newlyweds Tricia and Ethan are searching for their first home when a viewing leads them to the isolated manor of Dr Adrienne Hale, a psychiatrist who vanished without a trace years earlier. When a snowstorm traps them inside, Tricia stumbles on hidden recordings of Dr Hale''s sessions with her patients. As she listens, the tapes reveal unsettling secrets, and Tricia starts to wonder whether she and Ethan are truly safe.', '[["Author","Freida McFadden"],["Format","Paperback"],["Language","English"],["Genre","Psychological thriller"],["Type","Standalone novel"]]'::jsonb, 3, 73, null, null, null),
  ('in-814n9NoAW4L', 'IN', 'books', 'Anxious People: The No. 1 New York Times Bestseller, Now a Netflix Series by Fredrik Backman', 'Fredrik Backman', '/products/in/814n9NoAW4L.jpg', 43400, 61900, 30, true, 'Bestseller', '5K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'A failed bank robbery in a small Swedish town turns into a hostage situation when the would-be robber bursts into an apartment viewing full of strangers. Over one chaotic day, the hostages, including a retired couple, a banker and a young couple expecting a baby, reveal their fears, regrets and quiet kindnesses. Told with warmth and humour, Fredrik Backman''s novel is a moving story about friendship, forgiveness and the anxieties we all carry.', '[["Author","Fredrik Backman"],["Format","Paperback"],["Language","English"],["Genre","Contemporary fiction"],["Original language","Swedish"],["Adaptation","Netflix series"]]'::jsonb, 179, 74, null, null, null),
  ('in-71xxddxprOL', 'IN', 'books', 'Days at the Morisaki Bookshop: The Perfect Book to Curl Up With, Japanese Translated Fiction', 'Satoshi Yagisawa', '/products/in/71xxddxprOL.jpg', 25900, null, null, false, 'Amazon''s Choice', '1K+ bought in past month', 'Cloudtail India', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'When her boyfriend casually announces he is marrying someone else, twenty-five-year-old Takako is left heartbroken and adrift. Her eccentric uncle Satoru offers her a free room above the Morisaki Bookshop, his second-hand store in Tokyo''s Jimbocho book district. Though she has never been much of a reader, Takako slowly discovers the comfort of books, the quiet charm of the neighbourhood and new connections that help her begin again.', '[["Author","Satoshi Yagisawa"],["Translator","Eric Ozawa"],["Format","Paperback"],["Language","English"],["Genre","Japanese translated fiction"],["Setting","Jimbocho, Tokyo"]]'::jsonb, 27, 75, null, null, null),
  ('in-71APFtgsw4L', 'IN', 'toys', 'Smartivity Montessori Slide Puzzle, Wooden Toy for Kids 4-8 Years, Colour & Pattern Matching Learning Toy', 'Smartivity', '/products/in/71APFtgsw4L.jpg', 45600, 84900, 46, true, null, null, 'Smartivity Official Store', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'The Smartivity Montessori Slide Puzzle is a wooden learning toy for children aged 4 to 8 years. Kids slide pieces around the board to match colours and complete patterns, building logic, concentration and problem-solving skills as they go. The wooden build is sturdy for repeated play, and the screen-free challenge is well suited to independent play at home or on the go.', '[["Brand","Smartivity"],["Recommended age","4-8 years"],["Material","Wood"],["Toy type","Slide puzzle"],["Educational focus","Colour and pattern matching, logic"],["Batteries","Not required"]]'::jsonb, 119, 76, null, null, null),
  ('in-71wtNAEfGEL', 'IN', 'toys', 'VEBETO Kids Piano Keyboard with Mic, 37 Keys, 8 Rhythms, 8 Tones, 6 Demos, Portable Electronic Musical Toy', 'VEBETO', '/products/in/71wtNAEfGEL.jpg', 69800, 96900, 28, true, null, '1K+ bought in past month', 'VEBETO Official Store', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'The VEBETO Kids Piano Keyboard is a portable electronic keyboard with 37 keys and a microphone, letting children play, sing and explore music. It includes 8 rhythms, 8 tones and 6 demo songs to experiment with, helping build a sense of rhythm, listening skills and confidence. Compact and easy to carry, it is a fun introduction to music at home and a cheerful birthday gift idea.', '[["Brand","VEBETO"],["Toy type","Electronic piano keyboard"],["Keys","37"],["Rhythms","8"],["Tones","8"],["Demo songs","6"],["Included components","Keyboard, microphone"]]'::jsonb, 326, 77, null, null, null),
  ('in-6131DPnzIL', 'IN', 'toys', 'WireScorts Baby & Toddler First Educational Blocks, Shape Sorter, Colours & ABCD Learning Toy for 1+ Years', 'WireScorts', '/products/in/6131DPnzIL.jpg', 23900, null, null, false, null, '1K+ bought in past month', 'WireScorts Official Store', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'The WireScorts First Educational Blocks set is a shape sorter designed for babies and toddlers aged 1 year and up. Little ones learn shapes, colours and ABCD letters as they fit blocks into matching slots, building hand-eye coordination and fine motor skills. Made from kid-safe, durable materials, it offers engaging screen-free play and makes a thoughtful first-birthday gift.', '[["Brand","WireScorts"],["Recommended age","1 year and up"],["Toy type","Shape sorter blocks"],["Educational focus","Shapes, colours, alphabet"],["Batteries","Not required"],["Material","Kid-safe, durable materials"]]'::jsonb, 290, 78, null, null, null),
  ('in-61TXpN40ROL', 'IN', 'toys', 'Humming Bird Kids 80 Pcs Big Mega Blocks, Building & Construction Set for Boys & Girls, Multicolour', 'Humming Bird', '/products/in/61TXpN40ROL.jpg', 29900, null, null, false, null, '1K+ bought in past month', 'Humming Bird Official Store', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'The Humming Bird Big Mega Blocks set includes 80 large, multicolour building pieces for boys and girls. The big blocks are easy for small hands to grip and connect, letting children build towers, houses and vehicles from their imagination. Construction play like this develops creativity, motor skills and spatial thinking, and the set is great for sharing with siblings and friends.', '[["Brand","Humming Bird"],["Pieces","80"],["Toy type","Building and construction blocks"],["Block size","Big"],["Colour","Multicolour"],["Educational focus","Creativity, motor skills"],["Batteries","Not required"]]'::jsonb, 167, 79, null, null, null),
  ('in-6197rTwYArL', 'IN', 'sports', 'Amazon Basics Rubber Encased Hex Dumbbell Weight, Set of 2, 2.5 Kg, Black', 'Amazon Basics', '/products/in/6197rTwYArL.jpg', 113900, null, null, false, 'Amazon''s Choice', '5K+ bought in past month', 'Amazon Basics Official Store', 'Amazon', array['Adjustable weight adapts as your strength grows', 'Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle']::text[], 'This set of two rubber-encased hex dumbbells, each weighing 2.5 kg, is well suited to toning, warm-ups and light strength training at home. The hexagonal ends stop the dumbbells from rolling away when set down, and the rubber coating helps protect floors and reduce noise. A non-slip handle offers a secure grip, and the black finish looks neat in any home gym.', '[["Brand","Amazon Basics"],["Weight","2.5 kg each"],["Quantity","Set of 2"],["Shape","Hexagonal"],["Material","Rubber encased"],["Colour","Black"],["Use","Home workouts, toning"]]'::jsonb, 287, 80, null, null, null),
  ('in-710SxepIfiL', 'IN', 'sports', 'Lifelong PVC Hex Dumbbells Pack of 2 (3 Kg x 2) for Home Gym, Fitness Weights for Men & Women', 'Lifelong', '/products/in/710SxepIfiL.jpg', 35400, null, null, false, 'Bestseller', '5K+ bought in past month', 'Lifelong Official Store', 'Amazon', array['Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle', 'Ideal for home strength training']::text[], 'The Lifelong PVC Hex Dumbbells come as a pair of 3 kg weights for toning, aerobics and light strength training at home. The hexagonal shape keeps them from rolling when placed on the floor, and the PVC coating is easy to wipe clean. A comfortable, non-slip grip handle helps you stay in control, making them a practical choice for both men and women.', '[["Brand","Lifelong"],["Weight","3 kg each"],["Quantity","Pack of 2"],["Shape","Hexagonal"],["Material","PVC"],["Use","Home gym, toning"],["Suitable for","Men and women"]]'::jsonb, 49, 81, null, null, null),
  ('in-71uneWbTPpL', 'IN', 'sports', 'Kore 20 Kg PVC-DM Combo Home Gym Dumbbells Kit (3 Kg x 4 + 2 Kg x 4 Plates), Black', 'Kore', '/products/in/71uneWbTPpL.jpg', 74900, 93900, 20, true, 'Bestseller', '1K+ bought in past month', 'Kore Official Store', 'Amazon', array['Adjustable weight adapts as your strength grows', 'Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle']::text[], 'The Kore 20 kg PVC-DM Combo is a home gym dumbbell kit built around PVC weight plates: four 3 kg plates and four 2 kg plates. Mixing the plates lets you adjust the load for different exercises and increase it as your strength improves. The durable PVC finish is easy to wipe clean, and the black colour gives the kit a neat look in any workout space.', '[["Brand","Kore"],["Total weight","20 kg"],["Plates","3 kg x 4, 2 kg x 4"],["Material","PVC"],["Colour","Black"],["Type","Dumbbell kit"],["Use","Home gym, strength training"]]'::jsonb, 156, 82, null, null, null),
  ('in-61mUc9vBJqL', 'IN', 'sports', 'RUBX Rubber Coated Professional Hex Dumbbells (Pack of 2), 5 Kg x 2 (Total 10 Kg), Silver', 'RUBX', '/products/in/61mUc9vBJqL.jpg', 160900, 250900, 36, true, 'Bestseller', '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Adjustable weight adapts as your strength grows', 'Space-saving design for a home gym', 'Secure locking mechanism for safe lifting', 'Durable, non-slip grip handle']::text[], 'The RUBX Professional Hex Dumbbells come as a pair of 5 kg weights, totalling 10 kg, for strength training at home or in the gym. A rubber coating protects floors and reduces clanking, and the hexagonal ends stop the dumbbells from rolling away between sets. The non-slip handle offers a secure grip for curls, presses and rows, and the silver finish gives a smart look.', '[["Brand","RUBX"],["Weight","5 kg each (10 kg total)"],["Quantity","Pack of 2"],["Shape","Hexagonal"],["Material","Rubber coated"],["Colour","Silver"],["Use","Strength training"]]'::jsonb, 114, 83, null, null, null),
  ('in-719GNPKA8OL', 'IN', 'mobiles', 'Redmi 15C 5G Prime Edition (Dusk Purple, 6GB RAM, 128GB Storage), 6000mAh Battery, 50MP AI Camera', 'Redmi', '/products/in/719GNPKA8OL.jpg', 1949900, 3200900, 39, true, 'Limited time deal', '1K+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['5G-ready with fast, lag-free everyday performance', 'Big, bright display for video, gaming & scrolling', 'All-day battery with fast charging support', 'Sharp AI cameras capture crisp photos day or night']::text[], 'The Redmi 15C 5G Prime Edition brings 5G connectivity to everyday use, with 6 GB of RAM and 128 GB of storage for apps, photos and videos. Its 6000 mAh battery is built to last through long days of streaming, gaming and calls, and fast charging support helps you top up quickly. The 50 MP AI camera captures sharp photos in varied lighting, all wrapped in a Dusk Purple finish.', '[["Brand","Redmi"],["Model name","15C 5G Prime Edition"],["RAM","6 GB"],["Storage","128 GB"],["Battery","6000 mAh"],["Rear camera","50 MP AI camera"],["Network","5G"],["Colour","Dusk Purple"]]'::jsonb, 163, 84, null, null, null),
