  ('in-61D9CLCf5KL', 'IN', 'mobiles', 'Lava Bold N4 Lite (Ghost Silver, 3GB RAM, 32GB Storage), 5000mAh Battery, Made in India', 'Lava', '/products/in/61D9CLCf5KL.jpg', 839900, 1234900, 32, true, 'Limited time deal', null, 'Lava Official Store', 'Amazon', array['5G-ready with fast, lag-free everyday performance', 'Big, bright display for video, gaming & scrolling', 'All-day battery with fast charging support', 'Sharp AI cameras capture crisp photos day or night']::text[], 'The Lava Bold N4 Lite is an entry-level smartphone made in India, designed for calls, messaging, social media and everyday browsing. It comes with 3 GB of RAM and 32 GB of storage for essential apps, and a 5000 mAh battery built to last through the day. The Ghost Silver finish gives it a clean, modern look, making it a practical first phone or backup device.', '[["Brand","Lava"],["Model name","Bold N4 Lite"],["RAM","3 GB"],["Storage","32 GB"],["Battery","5000 mAh"],["Colour","Ghost Silver"],["Country of origin","India"]]'::jsonb, 42, 94, null, null, null),
  ('in-819ZWX2Nm9L', 'IN', 'wearables', 'Noise Diva Araya Smartwatch for Women, 1.32" AMOLED Display, BT Calling, 100+ Sports Modes, Metal Build', 'Noise', '/products/in/819ZWX2Nm9L.jpg', 549900, 662900, 17, true, null, null, 'Noise Official Store', 'Amazon', array['Bright display with hundreds of customisable watch faces', 'Bluetooth calling with built-in mic & speaker', 'Tracks heart rate, SpO2, sleep & 100+ sports modes', 'Multi-day battery life on a single charge']::text[], 'The Noise Diva Araya is a smartwatch designed for women, combining a metal build with a crisp 1.32-inch AMOLED display and customisable watch faces. Bluetooth calling lets you make and take calls from your wrist, while 100+ sports modes cover everything from walks to yoga. It tracks heart rate, SpO2 and sleep, and offers multi-day battery life on a single charge.', '[["Brand","Noise"],["Model name","Diva Araya"],["Display","1.32-inch AMOLED"],["Bluetooth calling","Yes"],["Sports modes","100+"],["Build","Metal"],["Health tracking","Heart rate, SpO2, sleep"],["Department","Women"]]'::jsonb, 161, 95, null, null, null),
  ('in-61Cx3vx0mLL', 'IN', 'wearables', 'Fire-Boltt Phoenix Pro 1.39" Bluetooth Calling Smartwatch, 120+ Sports Modes, SpO2 & Heart Rate Monitor', 'Fire-Boltt', '/products/in/61Cx3vx0mLL.jpg', 129900, null, null, false, null, '5K+ bought in past month', 'Fire-Boltt Official Store', 'Amazon', array['Bright display with hundreds of customisable watch faces', 'Bluetooth calling with built-in mic & speaker', 'Tracks heart rate, SpO2, sleep & 100+ sports modes', 'Multi-day battery life on a single charge']::text[], 'The Fire-Boltt Phoenix Pro smartwatch features a 1.39-inch display and Bluetooth calling, so you can answer calls directly from your wrist using the built-in mic and speaker. It offers 120+ sports modes for tracking a wide range of workouts, along with heart rate and SpO2 monitoring. Hundreds of watch faces let you personalise the look, and the battery lasts multiple days per charge.', '[["Brand","Fire-Boltt"],["Model name","Phoenix Pro"],["Display","1.39-inch"],["Bluetooth calling","Yes"],["Sports modes","120+"],["Health tracking","Heart rate, SpO2"],["Battery life","Multi-day"]]'::jsonb, 34, 96, null, null, null),
  ('in-61aIxLJVJCL', 'IN', 'wearables', 'Noise Pulse 4 Max 1.96" AMOLED Display Smartwatch, AI Voice Assistant, BT Calling, Metallic Finish', 'Noise', '/products/in/61aIxLJVJCL.jpg', 279900, 389900, 28, true, null, '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Bright display with hundreds of customisable watch faces', 'Bluetooth calling with built-in mic & speaker', 'Tracks heart rate, SpO2, sleep & 100+ sports modes', 'Multi-day battery life on a single charge']::text[], 'The Noise Pulse 4 Max smartwatch features a large 1.96-inch AMOLED display with a metallic finish for a polished look on the wrist. An AI voice assistant lets you use voice commands, and Bluetooth calling means you can take calls without reaching for your phone. It tracks heart rate, SpO2, sleep and 100+ sports modes, with battery life that lasts several days.', '[["Brand","Noise"],["Model name","Pulse 4 Max"],["Display","1.96-inch AMOLED"],["Bluetooth calling","Yes"],["Voice assistant","AI voice assistant"],["Finish","Metallic"],["Health tracking","Heart rate, SpO2, sleep"]]'::jsonb, 32, 97, null, null, null),
  ('in-61ATaTpvEQL', 'IN', 'wearables', 'Noise Twist Round 1.38" TFT Display Smartwatch, BT Calling, 100 Sports Modes, 7-Day Battery Life', 'Noise', '/products/in/61ATaTpvEQL.jpg', 159900, null, null, false, 'Bestseller', '1K+ bought in past month', 'Cocoblu Retail', 'Amazon', array['Bluetooth calling with built-in mic & speaker', 'Tracks heart rate, SpO2, sleep & 100+ sports modes', 'Multi-day battery life on a single charge', 'Water-resistant, built for workouts and daily wear']::text[], 'The Noise Twist Round smartwatch pairs a classic round dial with a 1.38-inch TFT display and Bluetooth calling for hands-free conversations. It supports 100 sports modes and tracks heart rate, SpO2 and sleep to help you stay on top of your health. A battery life of up to 7 days means fewer charges, and its water-resistant build is made for workouts and daily wear.', '[["Brand","Noise"],["Model name","Twist Round"],["Display","1.38-inch TFT, round dial"],["Bluetooth calling","Yes"],["Sports modes","100"],["Battery life","Up to 7 days"],["Water resistance","Water resistant"]]'::jsonb, 178, 98, null, null, null),
  ('in-71JLQrCFFL', 'IN', 'wearables', 'boAt Wave Sigma 3 Smartwatch, 2.01" HD Display, BT Calling, 700+ Watch Faces, IP68 Water Resistant', 'boAt', '/products/in/71JLQrCFFL.jpg', 149900, 220900, 32, true, null, '1K+ bought in past month', 'boAt Official Store', 'Amazon', array['Bright display with hundreds of customisable watch faces', 'Bluetooth calling with built-in mic & speaker', 'Tracks heart rate, SpO2, sleep & 100+ sports modes', 'Multi-day battery life on a single charge']::text[], 'The boAt Wave Sigma 3 smartwatch features a large 2.01-inch HD display and more than 700 watch faces, so you can change the look to suit your mood. Bluetooth calling lets you manage calls from your wrist, and IP68 water resistance protects against sweat, rain and splashes. It also tracks heart rate, SpO2, sleep and 100+ sports modes, with multi-day battery life.', '[["Brand","boAt"],["Model name","Wave Sigma 3"],["Display","2.01-inch HD"],["Bluetooth calling","Yes"],["Watch faces","700+"],["Water resistance","IP68"],["Health tracking","Heart rate, SpO2, sleep"]]'::jsonb, 295, 99, null, null, null),
  ('in-71S8pDT9EiL', 'IN', 'kitchen-appliances', 'Havells Prisma 750W Mixer Grinder, 4 Jars, 3 Speed with Pulse, Stainless Steel Blades, 5-Year Motor Warranty', 'Havells', '/products/in/71S8pDT9EiL.jpg', 429000, null, null, false, null, '1K+ bought in past month', 'Havells Official Store', 'Amazon', array['Grinds masalas, chutneys and batters in seconds', 'Stainless steel jars and blades for wet and dry grinding', 'Overload protection keeps the motor safe on long runs', 'Locking lids and anti-skid feet for steady, spill-free use']::text[], 'The Havells Prisma is a 750 W mixer grinder that comes with four jars to handle everything from dry masalas and chutneys to idli and dosa batter. Three speed settings plus a pulse function give you control over texture, and stainless steel blades cut through ingredients efficiently. Overload protection helps safeguard the motor, which is backed by a 5-year warranty.', '[["Brand","Havells"],["Model name","Prisma"],["Wattage","750 W"],["Jars","4"],["Speed settings","3 speeds with pulse"],["Blade material","Stainless steel"],["Warranty","5 years on motor"],["Safety","Overload protection"]]'::jsonb, 166, 100, null, null, null),
  ('in-71Swqb9mXvL', 'IN', 'kitchen-appliances', 'Philips HR7732 Mixer Grinder 1000W, 4 Jars, Double Ball Bearing Motor, Unique Modes for Different Textures', 'Philips', '/products/in/71Swqb9mXvL.jpg', 769900, null, null, false, null, '1K+ bought in past month', 'Philips Official Store', 'Amazon', array['Stainless steel jars and blades for wet and dry grinding', 'Overload protection keeps the motor safe on long runs', 'Locking lids and anti-skid feet for steady, spill-free use', 'Backed by a manufacturer warranty']::text[], 'The Philips HR7732 is a 1000 W mixer grinder with four jars for grinding, blending and making batters at home. Its double ball bearing motor is built for smooth, stable performance, and dedicated modes help you get the right texture for different recipes. Stainless steel jars and blades handle both wet and dry grinding, and locking lids with anti-skid feet keep it steady on the counter.', '[["Brand","Philips"],["Model","HR7732"],["Wattage","1000 W"],["Jars","4"],["Motor","Double ball bearing"],["Modes","Texture-specific modes"],["Blade material","Stainless steel"]]'::jsonb, 50, 101, null, null, null),
  ('in-71nBpK0uJL', 'IN', 'kitchen-appliances', 'Bosch TrueMixx Pro Mixer Grinder MGM8642BIN, 750W, 4 Jars, Stone Pounding Technology, Black', 'Bosch', '/products/in/71nBpK0uJL.jpg', 609900, null, null, false, 'Amazon''s Choice', '1K+ bought in past month', 'Cocoblu Retail', 'Amazon', array['Grinds masalas, chutneys and batters in seconds', 'Stainless steel jars and blades for wet and dry grinding', 'Overload protection keeps the motor safe on long runs', 'Locking lids and anti-skid feet for steady, spill-free use']::text[], 'The Bosch TrueMixx Pro MGM8642BIN is a 750 W mixer grinder with four jars for everyday Indian cooking, from spice powders to chutneys and batters. It features Stone Pounding Technology, designed to recreate the texture of traditional hand-pounded masalas. Stainless steel blades handle wet and dry grinding, overload protection guards the motor, and the black finish suits modern kitchens.', '[["Brand","Bosch"],["Model name","TrueMixx Pro"],["Model","MGM8642BIN"],["Wattage","750 W"],["Jars","4"],["Special feature","Stone Pounding Technology"],["Blade material","Stainless steel"],["Colour","Black"]]'::jsonb, 388, 102, null, null, null),
  ('in-61P8ZSaqBHL', 'IN', 'kitchen-appliances', 'Sujata MG01 Mixer Grinder 1000W, 3 Jars, Double Ball Bearing Motor, 24000 RPM, 90 Min Non-Stop Running', 'Sujata', '/products/in/61P8ZSaqBHL.jpg', 669000, 1171900, 43, true, null, '5K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Grinds masalas, chutneys and batters in seconds', 'Stainless steel jars and blades for wet and dry grinding', 'Overload protection keeps the motor safe on long runs', 'Locking lids and anti-skid feet for steady, spill-free use']::text[], 'The Sujata MG01 mixer grinder runs on a 1000 W motor with double ball bearings, spinning at up to 24,000 RPM for fast grinding. It is rated for up to 90 minutes of non-stop running, making it suitable for large batches of batter, masala and chutney. Three stainless steel jars cover wet and dry grinding, and overload protection helps keep the motor safe.', '[["Brand","Sujata"],["Model","MG01"],["Wattage","1000 W"],["Jars","3"],["Motor speed","24,000 RPM"],["Motor","Double ball bearing"],["Continuous running","Up to 90 minutes"],["Safety","Overload protection"]]'::jsonb, 91, 103, null, null, null),
  ('in-61Cln50mffL', 'IN', 'kitchen-appliances', 'Bajaj Rex 500W Mixer Grinder, 3 Stainless Steel Jars, Multifunctional Blades, Nutri-Pro Feature', 'Bajaj', '/products/in/61Cln50mffL.jpg', 219900, null, null, false, 'Bestseller', '1K+ bought in past month', 'Cloudtail India', 'Amazon', array['Stainless steel jars and blades for wet and dry grinding', 'Overload protection keeps the motor safe on long runs', 'Locking lids and anti-skid feet for steady, spill-free use', 'Backed by a manufacturer warranty']::text[], 'The Bajaj Rex is a 500 W mixer grinder with three stainless steel jars for daily kitchen tasks such as grinding masalas, making chutneys and blending batters. Multifunctional blades adapt to different ingredients, and the model includes the Bajaj Nutri-Pro feature. Compact and easy to use, it suits small families and everyday cooking, with overload protection to keep the motor safe.', '[["Brand","Bajaj"],["Model name","Rex"],["Wattage","500 W"],["Jars","3 stainless steel jars"],["Blades","Multifunctional"],["Special feature","Nutri-Pro"],["Safety","Overload protection"]]'::jsonb, 116, 104, null, null, null),
  ('in-518N3l4z1L', 'IN', 'beauty', 'Himalaya Purifying Neem Face Wash, 150ml, Soap-Free, Paraben & Phthalate Free, for Acne-Prone Skin', 'Himalaya', '/products/in/518N3l4z1L.jpg', 17800, 21900, 19, true, null, '5K+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['Made for Indian skin and climate', 'Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow']::text[], 'The Himalaya Purifying Neem Face Wash is a soap-free cleanser made for acne-prone skin. Its formula combines neem and turmeric, two herbs traditionally used for clear-looking skin, to remove dirt and excess oil without over-drying. It is free from parabens and phthalates, and the 150 ml tube is gentle enough for daily use, morning and night.', '[["Brand","Himalaya"],["Item form","Gel"],["Skin type","Acne-prone skin"],["Key ingredients","Neem, turmeric"],["Item volume","150 ml"],["Free from","Soap, parabens, phthalates"]]'::jsonb, 168, 105, null, null, null),
  ('in-71gqGCYkFuL', 'IN', 'beauty', 'Himalaya Hydrating Aloe Vera Face Wash, 200ml, Aloe Vera & Vitamin E, Creamy Gentle Cleanser', 'Himalaya', '/products/in/71gqGCYkFuL.jpg', 22500, 30900, 27, true, 'Bestseller', '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow', 'Suitable for all skin types']::text[], 'The Himalaya Hydrating Aloe Vera Face Wash is a creamy, gentle cleanser that removes dirt and impurities while helping skin retain moisture. Aloe vera soothes and hydrates, and vitamin E helps keep skin soft and nourished. Its creamy texture lathers gently, making it suitable for everyday use on all skin types, and the 200 ml tube lasts through regular daily use.', '[["Brand","Himalaya"],["Item form","Cream"],["Skin type","All skin types"],["Key ingredients","Aloe vera, vitamin E"],["Item volume","200 ml"],["Use","Daily gentle cleansing"]]'::jsonb, 270, 106, null, null, null),
  ('in-61ddBs1gCaL', 'IN', 'beauty', 'CeraVe Foaming Cleanser for Normal to Oily Skin, 236ml, Dermatologist-Developed with Ceramides & Niacinamide', 'CeraVe', '/products/in/61ddBs1gCaL.jpg', 111600, 139900, 20, true, null, '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Made for Indian skin and climate', 'Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow']::text[], 'The CeraVe Foaming Cleanser for normal to oily skin is a gel cleanser that lathers into a light foam to remove dirt, excess oil and make-up without disrupting the skin barrier. Developed with dermatologists, it contains three essential ceramides, niacinamide and hyaluronic acid to help maintain moisture while cleansing. The fragrance-free, non-comedogenic formula comes in a 236 ml bottle for daily use.', '[["Brand","CeraVe"],["Item form","Foaming gel"],["Skin type","Normal to oily skin"],["Key ingredients","Ceramides, niacinamide, hyaluronic acid"],["Item volume","236 ml"],["Use","Daily face cleansing"],["Special feature","Fragrance-free, non-comedogenic"]]'::jsonb, 104, 107, null, null, null),
  ('in-71ZrMvjZXZL', 'IN', 'beauty', 'Muuchstac Ocean Face Wash for Men, Fights Acne & Pimples, Oil Control, Brightens Skin, Pack of 3', 'Muuchstac', '/products/in/71ZrMvjZXZL.jpg', 29000, 45900, 37, true, 'Bestseller', '5K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Dermatologically tested, gentle for daily use', 'Free from parabens, sulphates and mineral oil', 'Deeply hydrates for a healthy, natural glow', 'Suitable for all skin types']::text[], 'The Muuchstac Ocean Face Wash is formulated for men''s skin, helping to fight acne and pimples while controlling excess oil through the day. Regular use helps clear away dirt and pollution for a cleaner, brighter-looking complexion. It is dermatologically tested and gentle enough for daily washing. This value pack contains three tubes, so you can keep one at home, one at the gym and one in your travel kit.', '[["Brand","Muuchstac"],["Item form","Face wash"],["Department","Men"],["Skin type","Oily and acne-prone skin"],["Benefits","Acne care, oil control, brightening"],["Pack size","3"],["Use","Daily face cleansing"]]'::jsonb, 74, 108, null, null, null),
  ('in-717qtxFpeaL', 'IN', 'fashion', 'Jockey Mens Cotton Rich Regular Fit Half Sleeve Round Neck T-Shirt, Breathable Everyday Tee', 'Jockey', '/products/in/717qtxFpeaL.jpg', 99900, null, null, false, null, '1K+ bought in past month', 'Jockey Official Store', 'Amazon', array['Lightweight, breathable mesh upper keeps feet cool', 'Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking']::text[], 'This Jockey half-sleeve round neck T-shirt for men is made from cotton-rich fabric that feels soft and breathable against the skin. The regular fit gives a comfortable, easy shape that works for lounging at home, running errands or layering under a jacket. A versatile everyday basic, it pairs well with jeans, shorts or track pants.', '[["Brand","Jockey"],["Department","Men"],["Material","Cotton rich"],["Fit type","Regular fit"],["Sleeve type","Half sleeve"],["Neck style","Round neck"],["Care instructions","Machine wash"]]'::jsonb, 59, 109, null, null, null),
  ('in-514vCNWtZDL', 'IN', 'fashion', 'ADRO Mens Regular Fit Cotton Half Sleeve Round Neck Solid Casual T-Shirt', 'ADRO', '/products/in/514vCNWtZDL.jpg', 59900, 67900, 12, true, null, '1K+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking', 'Everyday comfort for Indian roads and weather']::text[], 'The ADRO solid round neck T-shirt for men is a half-sleeve casual essential made from cotton for breathable, all-day comfort. Its regular fit sits neatly without being tight, and the plain solid design makes it easy to style with jeans, chinos or shorts. It is a simple, versatile layer for college, weekends and travel.', '[["Brand","ADRO"],["Department","Men"],["Material","Cotton"],["Fit type","Regular fit"],["Sleeve type","Half sleeve"],["Neck style","Round neck"],["Pattern","Solid"],["Care instructions","Machine wash"]]'::jsonb, 3, 110, null, null, null),
  ('in-41uhw1abTpL', 'IN', 'fashion', 'TURMS Anti-Stain Mens Cotton Blend Half Sleeve Polo T-Shirt, Stretchable All-Day Comfort', 'TURMS', '/products/in/41uhw1abTpL.jpg', 94800, null, null, false, null, '500+ bought in past month', 'TURMS Official Store', 'Amazon', array['Lightweight, breathable mesh upper keeps feet cool', 'Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking']::text[], 'The TURMS anti-stain polo T-shirt for men is made from a stretchable cotton blend designed to resist everyday spills and stay presentable through the day. The half-sleeve polo collar design strikes a balance between smart and casual, suiting office days, travel and weekend outings. Its stretch fabric moves with you for all-day comfort.', '[["Brand","TURMS"],["Department","Men"],["Material","Cotton blend"],["Style","Polo collar"],["Sleeve type","Half sleeve"],["Special feature","Anti-stain, stretchable"],["Care instructions","Machine wash"]]'::jsonb, 29, 111, null, null, null),
  ('in-41T5wfyFb8L', 'IN', 'fashion', 'AWG All Weather Gear Mens Dry-Fit Round Neck Half Sleeve Sports & Gym T-Shirt', 'AWG', '/products/in/41T5wfyFb8L.jpg', 69900, null, null, false, null, null, 'AWG Official Store', 'Amazon', array['Lightweight, breathable mesh upper keeps feet cool', 'Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking']::text[], 'The AWG All Weather Gear dry-fit T-shirt for men is designed for sports and gym sessions, using a quick-drying fabric that helps move sweat away from the skin. The round neck and half sleeves allow free movement during workouts, runs and outdoor games. Lightweight and breathable, it also works as a comfortable everyday tee in warm weather.', '[["Brand","AWG"],["Department","Men"],["Material","Dry-fit fabric"],["Neck style","Round neck"],["Sleeve type","Half sleeve"],["Use","Sports and gym"],["Care instructions","Machine wash"]]'::jsonb, 340, 112, null, null, null),
  ('in-61xTfKaqUlL', 'IN', 'fashion', 'Lymio Mens Oversized Cotton Half Sleeve Round Neck Casual T-Shirt', 'Lymio', '/products/in/61xTfKaqUlL.jpg', 39900, 51900, 23, true, null, '1K+ bought in past month', 'Lymio Official Store', 'Amazon', array['Lightweight, breathable mesh upper keeps feet cool', 'Cushioned sole absorbs impact on every stride', 'Durable anti-skid outsole grips every surface', 'Lace-up fit for daily running, gym and walking']::text[], 'The Lymio oversized T-shirt for men offers a relaxed, roomy silhouette for a casual streetwear look. Made from cotton, it feels soft and breathable in warm weather. The half sleeves and round neck keep the style simple, so it pairs easily with jeans, joggers or cargo pants for college, outings and travel.', '[["Brand","Lymio"],["Department","Men"],["Material","Cotton"],["Fit type","Oversized"],["Sleeve type","Half sleeve"],["Neck style","Round neck"],["Care instructions","Machine wash"]]'::jsonb, 126, 113, null, null, null),
  ('in-91Sy3S198L', 'IN', 'books', 'The Lost Bookshop: The most charming and uplifting novel of the year', 'Evie Woods', '/products/in/91Sy3S198L.jpg', 35200, 57900, 39, true, null, '5K+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'The Lost Bookshop weaves together the stories of three people linked by a mysterious Dublin bookshop that seems to appear only to those who need it. In the 1920s, Opaline escapes an arranged marriage and builds a new life among books. In the present day, Martha, fleeing a painful past, takes a housekeeping job, while Henry searches for a legendary lost manuscript. A charming, uplifting tale of hope, courage and the magic of reading.', '[["Author","Evie Woods"],["Format","Paperback"],["Language","English"],["Genre","Historical fiction, magical realism"],["Setting","Dublin"],["Type","Novel"]]'::jsonb, 70, 114, null, null, null),
  ('in-919dIRLFTeL', 'IN', 'books', 'Broken Country: Amazon''s Book of the Year, the Million-Copy Bestseller', 'Clare Leslie Hall', '/products/in/919dIRLFTeL.jpg', 43100, null, null, false, null, '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'Beth and her husband Frank farm the land in a quiet corner of rural England, their marriage steady and settled. When Gabriel Wolfe, the man Beth once loved, returns to the village with his young son, long-buried feelings and old loyalties are stirred up. As the past collides with the present, a shocking death sets events in motion that will test everyone involved. A tense, emotional story of love and difficult choices.', '[["Author","Clare Leslie Hall"],["Format","Paperback"],["Language","English"],["Genre","Literary fiction, romance"],["Setting","Rural England"],["Type","Novel"]]'::jsonb, 397, 115, null, null, null),
  ('in-71q6gvpgW8L', 'IN', 'books', 'Greatest Works of Jane Austen (Set of 5 Books): Pride and Prejudice, Emma, Sense and Sensibility & more', 'Jane Austen', '/products/in/71q6gvpgW8L.jpg', 74900, 94900, 21, true, null, '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'This five-book collection gathers celebrated novels by Jane Austen, including Pride and Prejudice, Emma and Sense and Sensibility. Set among the country houses and drawing rooms of Regency England, the stories follow spirited heroines as they navigate love, family expectations, social class and marriage. Austen''s sharp wit and keen observation of human nature make these classics as engaging today as when they were first published.', '[["Author","Jane Austen"],["Format","Paperback"],["Language","English"],["Genre","Classic fiction"],["Number of books","5"],["Includes","Pride and Prejudice, Emma, Sense and Sensibility"]]'::jsonb, 312, 116, null, null, null),
  ('in-41y8H3QmVqL', 'IN', 'books', 'White Nights by Fyodor Dostoyevsky: A Timeless Story of Love, Longing & Solitude, Classic Russian Novella', 'Fyodor Dostoyevsky', '/products/in/41y8H3QmVqL.jpg', 10700, null, null, false, null, '1K+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'White Nights is Fyodor Dostoyevsky''s short, tender novella about a lonely young dreamer wandering the streets of St Petersburg during the summer white nights. One evening he meets Nastenka, a young woman waiting for someone who has promised to return, and over four nights they share confidences, hopes and memories. It is a gentle, bittersweet story of love, longing and solitude, told in the author''s lyrical early style.', '[["Author","Fyodor Dostoyevsky"],["Format","Paperback"],["Language","English"],["Genre","Classic fiction, novella"],["Original language","Russian"],["Setting","St Petersburg"]]'::jsonb, 107, 117, null, null, null),
  ('in-71m8hR9ZUfL', 'IN', 'books', 'Best of George Orwell Boxed Set (Animal Farm & 1984), Set of 2 Books', 'George Orwell', '/products/in/71m8hR9ZUfL.jpg', 24900, 42900, 42, true, null, '1K+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['A gripping read you won’t be able to put down', 'Print length crafted for immersive weekend reading', 'A reader-favourite pick with rave reviews', 'Beautifully written and impossible to forget']::text[], 'This boxed set brings together two landmark novels by George Orwell. Animal Farm is a sharp allegorical fable in which farm animals overthrow their human owner, only to see their ideals slowly twisted. Nineteen Eighty-Four follows Winston Smith, a clerk living under the ever-watchful eye of Big Brother in a totalitarian state that controls truth itself. Together they offer a powerful look at power, propaganda and freedom.', '[["Author","George Orwell"],["Format","Paperback (boxed set)"],["Language","English"],["Genre","Classic fiction, dystopian"],["Number of books","2"],["Includes","Animal Farm, Nineteen Eighty-Four"]]'::jsonb, 143, 118, null, null, null),
  ('in-81qgtF5lNL', 'IN', 'yoga', 'Wiselife True Alignment Yoga Mat with Strap, 6mm Anti-Slip TPE, Eco-Friendly for Men & Women', 'Wiselife', '/products/in/81qgtF5lNL.jpg', 118200, 143900, 18, true, null, '1K+ bought in past month', 'Wiselife Official Store', 'Amazon', array['Anti-slip texture keeps you steady in every pose', 'Cushioned, joint-friendly support for floor workouts', 'Light and easy to roll up and carry', 'Sweat-resistant surface that wipes clean']::text[], 'The Wiselife True Alignment yoga mat is made from 6 mm TPE, an eco-friendly material that cushions knees and joints while staying light. Its anti-slip texture helps you hold poses steadily, and the alignment-focused design supports correct positioning during practice. The included strap makes it easy to roll up and carry to class, and the sweat-resistant surface wipes clean.', '[["Brand","Wiselife"],["Thickness","6 mm"],["Material","TPE"],["Surface","Anti-slip texture"],["Included components","Yoga mat, carry strap"],["Suitable for","Men and women"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 209, 119, null, null, null),
  ('in-61mx7nZOGnL', 'IN', 'yoga', 'Lifelong Dual Color 6mm Anti-Slip TPE Yoga Mat for Gym Workout & Fitness, for Men & Women', 'Lifelong', '/products/in/61mx7nZOGnL.jpg', 57900, null, null, false, null, '1K+ bought in past month', 'Lifelong Official Store', 'Amazon', array['Anti-slip texture keeps you steady in every pose', 'Cushioned, joint-friendly support for floor workouts', 'Light and easy to roll up and carry', 'Sweat-resistant surface that wipes clean']::text[], 'The Lifelong Dual Color yoga mat is made from 6 mm anti-slip TPE that balances cushioning with stability for yoga, stretching and floor workouts. The textured surface helps prevent slipping during poses, and the two-tone design adds a touch of colour to your workout space. Lightweight and easy to roll up, it suits both home practice and gym sessions for men and women.', '[["Brand","Lifelong"],["Thickness","6 mm"],["Material","TPE"],["Colour","Dual colour"],["Surface","Anti-slip"],["Use","Yoga, gym and home workouts"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 315, 120, null, null, null),
  ('in-710zYiyB7XL', 'IN', 'yoga', 'Permo Fitness Mat 12mm, Foldable High-Density TPE Multi-Purpose Yoga Mat with Carry Strap', 'Permo', '/products/in/710zYiyB7XL.jpg', 399900, null, null, false, null, '500+ bought in past month', 'Permo Official Store', 'Amazon', array['Anti-slip texture keeps you steady in every pose', 'Cushioned, joint-friendly support for floor workouts', 'Light and easy to roll up and carry', 'Sweat-resistant surface that wipes clean']::text[], 'The Permo fitness mat is a thick 12 mm multi-purpose mat made from high-density TPE, offering extra cushioning for floor exercises, stretching and yoga. Unlike rolled mats, it folds flat for compact storage, and the included carry strap makes it easy to take along. The anti-slip texture keeps you steady, and the sweat-resistant surface wipes clean after workouts.', '[["Brand","Permo"],["Thickness","12 mm"],["Material","High-density TPE"],["Design","Foldable"],["Included components","Mat, carry strap"],["Use","Yoga, stretching and floor workouts"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 138, 121, null, null, null),
  ('in-51izPGxd0SL', 'IN', 'yoga', 'Lifelong 4mm EVA Anti-Slip Yoga Mat for Gym Workout & Home Exercise, for Men & Women, Black', 'Lifelong', '/products/in/51izPGxd0SL.jpg', 55000, 93900, 41, true, 'Limited time deal', '1K+ bought in past month', 'Lifelong Official Store', 'Amazon', array['Cushioned, joint-friendly support for floor workouts', 'Light and easy to roll up and carry', 'Sweat-resistant surface that wipes clean', 'Suits yoga, pilates, stretching and home workouts']::text[], 'The Lifelong 4 mm EVA yoga mat is a lightweight, anti-slip mat for yoga, pilates, stretching and home workouts. Its slimmer profile gives a stable feel for balancing poses while still cushioning the floor, and the black colour hides everyday marks. It rolls up easily for storage or carrying to the gym, and the sweat-resistant surface is simple to wipe clean.', '[["Brand","Lifelong"],["Thickness","4 mm"],["Material","EVA"],["Colour","Black"],["Surface","Anti-slip"],["Use","Yoga, pilates and home workouts"],["Care instructions","Wipe clean with a damp cloth"]]'::jsonb, 44, 122, null, null, null),
  ('in-81yuVZ1RhiL', 'IN', 'toys', 'Building Blocks Toy for Kids 5+, 200+ Piece STEM Construction Set, Creative Learning Play', null, '/products/in/81yuVZ1RhiL.jpg', 60900, null, null, false, null, '1K+ bought in past month', 'Cloudtail India', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'This STEM construction set offers more than 200 building pieces for children aged 5 and up. Kids can follow their imagination to create buildings, vehicles and structures, developing creativity, problem-solving and fine motor skills along the way. The large piece count makes it well suited to group play with siblings or friends, and the screen-free activity keeps young builders engaged for hours.', '[["Brand","Generic"],["Recommended age","5 years and up"],["Pieces","200+"],["Toy type","STEM construction set"],["Educational focus","Creativity, problem-solving"],["Batteries","Not required"]]'::jsonb, 196, 123, null, null, null),
  ('in-918VkKHJgvL', 'IN', 'toys', 'Magnetic Building Tiles for Kids, Set of 50 Big 75mm Tiles, Educational Stacking Blocks', null, '/products/in/918VkKHJgvL.jpg', 179900, null, null, false, 'Amazon''s Choice', '500+ bought in past month', 'RetailEZ Private Limited', 'Amazon', array['Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present', 'Recommended for hours of independent fun']::text[], 'This set of 50 magnetic building tiles lets children create flat patterns and 3D structures that click together with built-in magnets. The big 75 mm tiles are easy for small hands to handle, and building with them introduces shapes, geometry, balance and colour. Open-ended and screen-free, the tiles encourage creativity and problem-solving, whether children build alone or with friends.', '[["Brand","Generic"],["Pieces","50"],["Tile size","75 mm"],["Toy type","Magnetic building tiles"],["Educational focus","Shapes, geometry, creativity"],["Batteries","Not required"]]'::jsonb, 3, 124, null, null, null),
  ('in-71WasaFL9UL', 'IN', 'toys', 'Nesta Toys 115-Piece Wooden City Building Blocks Set, Alphabet A-Z, Numbers 0-9 & City Vehicles', 'Nesta', '/products/in/71WasaFL9UL.jpg', 229800, null, null, false, null, '500+ bought in past month', 'Nesta Official Store', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'The Nesta Toys Wooden City Building Blocks set comes with 115 pieces, including alphabet blocks from A to Z, numbers from 0 to 9 and city vehicles. Children can build their own town while learning letters and numbers through play. The wooden pieces are sturdy and pleasant to handle, and the set encourages creativity, early literacy, counting and imaginative storytelling.', '[["Brand","Nesta"],["Pieces","115"],["Material","Wood"],["Toy type","Building blocks set"],["Educational focus","Alphabet, numbers, creativity"],["Batteries","Not required"]]'::jsonb, 373, 125, null, null, null),
  ('in-714xdznLhsL', 'IN', 'toys', 'Skillmatics Brain Blocks, 3D Early STEM Building Blocks Game for Kids 4-8 Years', 'Skillmatics', '/products/in/714xdznLhsL.jpg', 94800, null, null, false, 'Amazon''s Choice', '500+ bought in past month', 'Skillmatics Official Store', 'Amazon', array['Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present', 'Recommended for hours of independent fun']::text[], 'Skillmatics Brain Blocks is a 3D early STEM building game for kids aged 4 to 8 years. Players look at picture challenge cards and race to recreate the structures using coloured blocks, practising spatial reasoning, visual perception and logical thinking. It can be played solo or with family and friends, making it a fun, screen-free way to build early STEM skills.', '[["Brand","Skillmatics"],["Product name","Brain Blocks"],["Recommended age","4-8 years"],["Toy type","3D building blocks game"],["Educational focus","Spatial reasoning, STEM"],["Players","Solo or group play"],["Batteries","Not required"]]'::jsonb, 3, 126, null, null, null),
  ('in-61T829hkQLL', 'IN', 'toys', 'DIY Building Blocks Set for Kids, 200 Pieces Construction Toy with 32 Wheels, Build 8 Toy Vehicles', null, '/products/in/61T829hkQLL.jpg', 29900, 35900, 17, true, null, '1K+ bought in past month', 'Appario Retail Private Ltd', 'Amazon', array['Sparks imaginative, screen-free play', 'Made from kid-safe, durable materials', 'Builds learning, creativity and motor skills', 'A great return-gift or birthday present']::text[], 'This DIY building blocks set includes 200 pieces and 32 wheels, giving children everything they need to build up to 8 different toy vehicles. Kids can follow a design or invent their own creations, developing creativity, problem-solving and fine motor skills as they go. The screen-free construction play is ideal for weekends and holidays, and it makes a great birthday or return gift.', '[["Brand","Generic"],["Pieces","200"],["Wheels","32"],["Toy type","Vehicle building blocks"],["Builds","Up to 8 toy vehicles"],["Educational focus","Creativity, problem-solving"],["Batteries","Not required"]]'::jsonb, 353, 127, null, null, null);
