insert into public.reviews (product_id, author_name, rating, title, body, verified, seeded, helpful_count, created_at) values
  ('6181VJVcgSL', 'Daniel P.', 5, 'A gift that went down well', 'Bought these as a birthday gift for my teenage son and he has barely taken them off since. He says the sound is way better than his old pair.', true, true, 245, '2026-03-06T00:00:00.000Z'),
  ('6181VJVcgSL', 'Kevin B.', 5, 'Great sound for the price', 'I wasn''t expecting much at this price point, but the sound is clear and balanced. Vocals come through crisp and the bass has real punch without muddying everything else.', true, true, 97, '2025-12-24T00:00:00.000Z'),
  ('6181VJVcgSL', 'Jennifer M.', 5, 'Ideal for working from home', 'I use these all day for meetings and music while I work from home. Light enough that I forget I''m wearing them, and the controls are easy to find without looking.', true, true, 94, '2026-01-30T00:00:00.000Z'),
  ('6181VJVcgSL', 'Chris A.', 5, 'Bass lovers will be happy', 'The bass is deep and full without drowning out the rest of the music. Hip hop and electronic tracks sound fantastic, and acoustic songs still feel natural.', true, true, 206, '2025-08-06T00:00:00.000Z'),
  ('6181VJVcgSL', 'Maria G.', 4, 'My new commute essential', 'I wear these on my morning commute every day and they block out most of the train noise. I arrive at work without a headache for once.', true, true, 217, '2026-08-29T00:00:00.000Z'),
  ('6181VJVcgSL', 'David R.', 4, 'Pairing is painless', 'Paired with my phone in seconds and they reconnect automatically every time I switch them on. Moving over to my laptop is also quick, which I really appreciate.', true, true, 324, '2026-02-06T00:00:00.000Z'),
  ('6181VJVcgSL', 'Emily C.', 3, 'Blocks some noise, not all', 'They cut out a good amount of background chatter in the office, but low rumbles like the air conditioning still come through. Comfort and sound are otherwise good.', true, true, 49, '2025-10-22T00:00:00.000Z'),
  ('6181VJVcgSL', 'Nicole D.', 2, 'Stopped charging after a month', 'Worked well for the first few weeks, then one day they simply refused to charge. Disappointing, since the sound was actually quite nice while it lasted.', false, true, 44, '2026-04-19T00:00:00.000Z'),
  ('51CnDMbXZzL', 'Chris A.', 5, 'Great on long flights', 'Took them on a long flight and they made the engine drone much easier to tune out. The battery was still going strong when we landed.', false, true, 284, '2026-08-08T00:00:00.000Z'),
  ('51CnDMbXZzL', 'Kevin B.', 5, 'Pairing is painless', 'Paired with my phone in seconds and they reconnect automatically every time I switch them on. Moving over to my laptop is also quick, which I really appreciate.', true, true, 245, '2025-07-12T00:00:00.000Z'),
  ('51CnDMbXZzL', 'Michael T.', 4, 'Solid build quality', 'They feel sturdier than I expected, with no creaking and a finish that hasn''t scratched after a month of being thrown into my backpack.', true, true, 118, '2026-01-03T00:00:00.000Z'),
  ('51CnDMbXZzL', 'Arjun N.', 5, 'My new commute essential', 'I wear these on my morning commute every day and they block out most of the train noise. I arrive at work without a headache for once.', true, true, 199, '2025-08-04T00:00:00.000Z'),
  ('51CnDMbXZzL', 'James L.', 4, 'Perfect for the gym', 'They stay put during workouts and have survived plenty of sweaty sessions so far. Sound stays strong even with the gym music blasting in the background.', true, true, 72, '2025-12-10T00:00:00.000Z'),
