  ('818ezjaaQlL', 'Maria G.', 3, 'Battery could be better', 'Everything about it works nicely except the battery, which gets me through roughly half a workday. Fine if you''re near an outlet, less so for travel.', false, true, 44, '2025-09-11T00:00:00.000Z'),
  ('81A4WdEAKgL', 'Emily C.', 5, 'Perfect for students', 'Bought this for my daughter heading off to college. It handles her assignments, research and streaming easily, and she loves how easy it is to take to the library. Three months in, she hasn''t called me once with a tech problem, which might be a family record.', false, true, 66, '2026-04-28T00:00:00.000Z'),
  ('81A4WdEAKgL', 'Ashley W.', 5, 'Setup took minutes', 'Setup was quick and straightforward. I had my accounts, files and apps ready to go within an hour of opening the box, with no calls to tech support.', true, true, 257, '2025-10-10T00:00:00.000Z'),
  ('81A4WdEAKgL', 'Maria G.', 5, 'Fast, reliable daily driver', 'Boots up in seconds and handles my browser full of tabs, spreadsheets and video calls without slowing down. Exactly what I needed for work.', true, true, 298, '2026-08-31T00:00:00.000Z'),
