  ('81A4WdEAKgL', 'Chris A.', 4, 'Gorgeous screen', 'The display is sharp and bright, and photos and shows look vivid. I can comfortably work next to a sunny window without squinting.', true, true, 92, '2025-07-21T00:00:00.000Z'),
  ('81A4WdEAKgL', 'Kevin B.', 3, 'Good laptop, dim screen', 'Speed and keyboard are both solid. The screen is a bit dim for my liking and struggles near bright windows, though it''s perfectly fine indoors.', true, true, 41, '2026-06-26T00:00:00.000Z'),
  ('81A4WdEAKgL', 'Arjun N.', 2, 'Screen issue after two weeks', 'A line of flickering pixels appeared on the display after two weeks of careful use. Customer support was polite, but the replacement process has been slow.', true, true, 10, '2025-09-21T00:00:00.000Z');
insert into public.reviews (product_id, author_name, rating, title, body, verified, seeded, helpful_count, created_at) values
  ('81n1T4CYfmL', 'Lauren F.', 5, 'Handles creative work well', 'I edit photos and do some light video work, and this handles it smoothly. Previews render quickly and the screen makes editing a pleasure.', true, true, 192, '2026-05-15T00:00:00.000Z'),
