  ('81dQjX74L', 'Robert H.', 5, 'Built to last', 'After four months of workouts five days a week, there is no wear, no loosening and no chipping. Built tough.', true, true, 179, '2026-05-31T00:00:00.000Z'),
  ('81dQjX74L', 'Michael T.', 5, 'Worth every rep', 'Six weeks in, my arms and shoulders are noticeably stronger. These have made consistent home workouts so much easier to stick with.', true, true, 130, '2025-12-23T00:00:00.000Z'),
