  ('71sTw6pAXeL', 'Nicole D.', 5, 'Shared by the whole household', 'My wife and I share them and both use them almost daily. Comfortable, reliable and exactly what we needed for home workouts.', true, true, 285, '2025-12-09T00:00:00.000Z'),
