  ('in-61vRXtZcy7L', 'Amit H.', 2, 'Much smaller than expected', 'Ordered my usual size and it was far too tight to wear comfortably. The exchange process was easy, but the sizing guidance should be much clearer.', true, true, 33, '2026-02-08T00:00:00.000Z'),
  ('in-61vRXtZcy7L', 'Sneha P.', 3, 'Great fit, average durability', 'The fit and comfort are excellent. After about six weeks though, the material is showing more wear than I expected for how often I use it.', true, true, 53, '2025-10-05T00:00:00.000Z'),
