  ('in-51A42gljwLL', 'Priya S.', 5, 'Clean software experience', 'Fewer unnecessary apps than my previous phone, and the ones that were there were easy to remove. Updates have arrived on time so far.', true, true, 84, '2026-02-28T00:00:00.000Z'),
