  ('in-61D9CLCf5KL', 'Siddharth J.', 3, 'Solid for the basics', 'Handles calls, chats and payments without any trouble. Heavier games stutter at times, so it''s better suited to everyday use than gaming.', true, true, 10, '2026-04-13T00:00:00.000Z'),
  ('in-61D9CLCf5KL', 'Aditya G.', 4, 'Good for students', 'My daughter uses it for online classes, notes and chatting with friends. It handles everything smoothly and she loves the camera.', false, true, 246, '2025-12-13T00:00:00.000Z'),
  ('in-61D9CLCf5KL', 'Meera T.', 2, 'Full of bloatware and ads', 'Too many preinstalled apps and constant promotional notifications. It feels like the phone is working against me rather than for me.', false, true, 54, '2025-12-23T00:00:00.000Z'),
  ('in-61D9CLCf5KL', 'Karthik V.', 5, 'Bright, vivid display', 'The display is bright enough to read easily in harsh afternoon sunlight. Videos look vivid and scrolling feels really smooth.', true, true, 19, '2025-11-26T00:00:00.000Z'),
