  ('in-61D9CLCf5KL', 'Arjun N.', 1, 'Camera is disappointing', 'Photos look washed out and blurry unless the lighting is perfect. The camera was the main reason I bought it, so this is a big letdown.', true, true, 27, '2026-06-14T00:00:00.000Z'),
  ('in-819ZWX2Nm9L', 'Neha C.', 5, 'Battery lasts all week', 'I charge it roughly once a week with notifications and daily workout tracking turned on. Much better than I expected.', true, true, 150, '2025-08-27T00:00:00.000Z'),
  ('in-819ZWX2Nm9L', 'Karthik V.', 5, 'Stylish enough for the office', 'Looks elegant enough to wear to the office, and nobody guesses it''s a fitness watch. I switch watch faces depending on my outfit.', true, true, 46, '2026-08-14T00:00:00.000Z'),
  ('in-819ZWX2Nm9L', 'Priya S.', 4, 'Great gift for my mother', 'Bought this for my mother to track her walks and heart rate. She finds it easy to use and now checks her step count every evening.', true, true, 238, '2026-06-01T00:00:00.000Z'),
  ('in-819ZWX2Nm9L', 'Meera T.', 5, 'Comfortable to wear all day', 'It''s light enough that I forget I''m wearing it, even while sleeping. The strap is soft and hasn''t irritated my skin at all.', true, true, 91, '2025-12-31T00:00:00.000Z'),
  ('in-819ZWX2Nm9L', 'Kavya I.', 4, 'Bright display outdoors', 'The display is bright and easy to read even in direct afternoon sun during my walks. Watch faces look sharp and colourful.', true, true, 125, '2026-02-22T00:00:00.000Z'),
  ('in-819ZWX2Nm9L', 'Vikram M.', 3, 'Decent for the price', 'It does the basics well: time, steps, notifications and calls. Heart rate readings sometimes jump around during workouts, so I wouldn''t rely on them fully.', true, true, 8, '2025-08-30T00:00:00.000Z'),
  ('in-819ZWX2Nm9L', 'Divya L.', 4, 'Useful sleep tracking', 'The sleep tracking has helped me notice how late nights affect my rest. The insights are simple and easy to understand.', true, true, 253, '2026-05-30T00:00:00.000Z'),
  ('in-819ZWX2Nm9L', 'Rohan D.', 2, 'Stopped syncing', 'After two weeks it stopped syncing with the app, so my steps and sleep data just vanished. Reinstalling and re-pairing helped briefly, but the problem keeps coming back every few days, and support has only suggested the same steps again.', true, true, 7, '2026-03-17T00:00:00.000Z');
insert into public.reviews (product_id, author_name, rating, title, body, verified, seeded, helpful_count, created_at) values
  ('in-61Cx3vx0mLL', 'Ananya R.', 5, 'Accurate step tracking', 'I compared the step count with my phone for a week and the numbers were very close. Heart rate readings also match the machines at my gym.', false, true, 311, '2026-02-27T00:00:00.000Z'),
  ('in-61Cx3vx0mLL', 'Rohan D.', 4, 'Battery lasts all week', 'I charge it roughly once a week with notifications and daily workout tracking turned on. Much better than I expected.', true, true, 153, '2026-02-22T00:00:00.000Z'),
  ('in-61Cx3vx0mLL', 'Pooja B.', 3, 'Display dim at times', 'Readable most of the time, but in harsh midday sun I have to shade it with my hand. Indoors it looks great.', true, true, 12, '2025-11-20T00:00:00.000Z'),
  ('in-61Cx3vx0mLL', 'Kavya I.', 4, 'Plenty of workout modes', 'I use it for walking, cycling and yoga, and the workout modes cover everything I do. Switching between them is quick and easy.', true, true, 32, '2026-02-11T00:00:00.000Z'),
  ('in-61Cx3vx0mLL', 'Rahul K.', 2, 'Poor call quality', 'Callers say I sound distant and echoey, and the speaker is too quiet to hear outdoors. The calling feature was my main reason for buying it.', false, true, 50, '2026-05-09T00:00:00.000Z'),
  ('in-61Cx3vx0mLL', 'Arjun N.', 5, 'Good value smartwatch', 'Packed with features for what I paid. It does nearly everything my friend''s far more expensive watch does.', true, true, 115, '2025-07-15T00:00:00.000Z'),
  ('in-61Cx3vx0mLL', 'Meera T.', 3, 'Comfortable, basic strap', 'Comfortable and light, but the strap that comes with it feels basic and attracts dust. I plan to swap it for a better one soon.', true, true, 66, '2025-07-22T00:00:00.000Z'),
