  ('in-61aIxLJVJCL', 'Priya S.', 4, 'Notifications at a glance', 'I no longer pull out my phone every time it buzzes. Glancing at messages on the watch saves me time and distraction in meetings.', false, true, 31, '2025-10-07T00:00:00.000Z'),
