  ('in-61aIxLJVJCL', 'Rohan D.', 3, 'Nice design, tracking so-so', 'It looks premium and the calling feature works well. Step counts feel slightly inflated though, especially on days I spend typing a lot.', true, true, 47, '2026-05-11T00:00:00.000Z'),
  ('in-61ATaTpvEQL', 'Siddharth J.', 5, 'Easy app setup', 'Pairing with my phone took two minutes and the app is simple to navigate. All my health data syncs without any fuss.', true, true, 303, '2025-07-05T00:00:00.000Z'),
