  ('in-71S8pDT9EiL', 'Divya L.', 5, 'Quieter than expected', 'It is noticeably quieter than my old mixer. I can run it early in the morning without waking up the whole house.', true, true, 270, '2025-12-05T00:00:00.000Z'),
  ('in-71S8pDT9EiL', 'Meera T.', 4, 'Stable on the counter', 'It stays firmly in place on the kitchen counter with barely any vibration, even at top speed. No need to hold it down.', true, true, 111, '2025-11-12T00:00:00.000Z'),
  ('in-71S8pDT9EiL', 'Neha C.', 4, 'Sturdy, leak-free jars', 'The jars feel heavy and well made, and the lids lock securely with no leaks. After two months of daily use they still look new.', true, true, 283, '2026-05-22T00:00:00.000Z'),
  ('in-71S8pDT9EiL', 'Sneha P.', 5, 'Great for smoothies too', 'Beyond grinding, it makes excellent smoothies and milkshakes. The large jar blends fruit smoothly without leaving any chunks.', false, true, 117, '2026-04-20T00:00:00.000Z'),
  ('in-71S8pDT9EiL', 'Amit H.', 3, 'Powerful but loud', 'Grinds everything well and quickly, but it is quite loud at the highest speed. I''ve gotten used to it, but it''s not ideal early in the morning.', true, true, 15, '2026-01-13T00:00:00.000Z'),
  ('in-71S8pDT9EiL', 'Vikram M.', 4, 'Good gift for parents', 'Gifted this to my parents and my mother loves it. She says it handles wet and dry grinding better than anything she has used before.', true, true, 256, '2026-03-18T00:00:00.000Z'),
  ('in-71S8pDT9EiL', 'Ananya R.', 2, 'Cannot grind finely', 'Dry masala always comes out coarse no matter how long I grind. For chutneys it is fine, but spice powders are a disappointment.', true, true, 64, '2025-08-15T00:00:00.000Z'),
  ('in-71S8pDT9EiL', 'Priya S.', 3, 'Good performance, runs warm', 'Handles daily grinding well, but the motor gets warm if I run it for more than a few minutes continuously. I let it rest between batches.', true, true, 1, '2026-04-06T00:00:00.000Z'),
  ('in-71Swqb9mXvL', 'Ananya R.', 5, 'Stable on the counter', 'It stays firmly in place on the kitchen counter with barely any vibration, even at top speed. No need to hold it down.', true, true, 300, '2025-07-17T00:00:00.000Z'),
