  ('in-71q6gvpgW8L', 'Arjun N.', 5, 'Great commute read', 'Read it over two weeks on my train commute and looked forward to every ride. It''s easy to pick up where I left off, even after a long day.', true, true, 178, '2026-02-09T00:00:00.000Z'),
  ('in-71q6gvpgW8L', 'Rahul K.', 5, 'Satisfying final chapters', 'So many books lose their way near the end, but this one brings everything together beautifully. The final chapters were worth all the build-up.', true, true, 234, '2025-12-08T00:00:00.000Z'),
  ('in-71q6gvpgW8L', 'Neha C.', 4, 'Passed around the family', 'Bought a copy for a friend who reads constantly, and she loved it so much she passed it on to her sister. Now the three of us keep discussing it.', true, true, 43, '2026-06-02T00:00:00.000Z'),
