  ('in-81qgtF5lNL', 'Neha C.', 5, 'Great grip even when sweaty', 'I do intense, sweaty morning sessions and my hands and feet don''t slip at all. The grip holds up from the first pose to the last.', true, true, 145, '2025-12-03T00:00:00.000Z'),
  ('in-81qgtF5lNL', 'Meera T.', 4, 'Excellent value', 'Great quality for what I paid. It feels more premium than the mats I used at my old studio.', true, true, 112, '2026-05-31T00:00:00.000Z'),
  ('in-81qgtF5lNL', 'Amit H.', 4, 'Easy to keep clean', 'A quick wipe with a damp cloth after each session keeps it fresh. It dries fast and doesn''t hold onto sweat or smells.', true, true, 207, '2026-01-31T00:00:00.000Z'),
  ('in-81qgtF5lNL', 'Rahul K.', 5, 'Comfortable cushioning', 'The cushioning is perfect for my knees during kneeling poses and floor exercises. Supportive without feeling unstable or wobbly.', true, true, 54, '2026-03-09T00:00:00.000Z'),
  ('in-81qgtF5lNL', 'Sneha P.', 3, 'Comfortable, slips when wet', 'Very comfortable for gentle sessions. During intense workouts when I sweat a lot, though, my hands start slipping a bit.', true, true, 44, '2026-07-24T00:00:00.000Z'),
  ('in-81qgtF5lNL', 'Divya L.', 4, 'Durable after months of use', 'Four months of daily practice and it has no tears, no flaking and no worn patches. It''s holding up really well.', true, true, 66, '2026-07-25T00:00:00.000Z'),
  ('in-81qgtF5lNL', 'Siddharth J.', 2, 'Surface started flaking', 'The top layer started flaking after a month, leaving little bits on my clothes and the floor. Disappointing quality.', true, true, 9, '2026-08-02T00:00:00.000Z'),
  ('in-81qgtF5lNL', 'Aditya G.', 3, 'Nice mat, edges curled', 'Good cushioning and grip, but the edges kept curling up for the first week. Rolling it the opposite way overnight helped.', true, true, 12, '2026-06-27T00:00:00.000Z'),
  ('in-61mx7nZOGnL', 'Priya S.', 5, 'Durable after months of use', 'Four months of daily practice and it has no tears, no flaking and no worn patches. It''s holding up really well.', true, true, 212, '2026-08-30T00:00:00.000Z'),
  ('in-61mx7nZOGnL', 'Amit H.', 4, 'Just the right thickness', 'The thickness is just right for me, soft enough for my joints but firm enough for standing balance poses.', true, true, 155, '2026-07-26T00:00:00.000Z'),
  ('in-61mx7nZOGnL', 'Rahul K.', 4, 'Perfect for home workouts', 'I use it for yoga, stretching and bodyweight workouts at home. It stays in place on my tiled floor without sliding around.', true, true, 269, '2026-08-16T00:00:00.000Z'),
  ('in-61mx7nZOGnL', 'Arjun N.', 5, 'Excellent value', 'Great quality for what I paid. It feels more premium than the mats I used at my old studio.', true, true, 9, '2026-01-02T00:00:00.000Z'),
  ('in-61mx7nZOGnL', 'Kavya I.', 3, 'Better for yoga than cardio', 'Great for yoga and stretching. For jumping or more intense workouts, it feels a bit too soft and less stable than I''d like.', true, true, 22, '2026-08-22T00:00:00.000Z'),
  ('in-61mx7nZOGnL', 'Sneha P.', 4, 'Lies flat right away', 'It lay flat as soon as I unrolled it, with no curling at the edges. Such a small thing, but it makes practice so much more pleasant.', true, true, 285, '2025-12-11T00:00:00.000Z'),
  ('in-61mx7nZOGnL', 'Ananya R.', 2, 'Tore within weeks', 'Small tears appeared near the edges within a few weeks of normal use. I expected it to last much longer than that.', true, true, 19, '2026-02-08T00:00:00.000Z'),
  ('in-61mx7nZOGnL', 'Vikram M.', 3, 'Soft, but shows marks', 'Soft and comfortable, but it picks up marks and indentations from my feet and knees easily. Purely cosmetic, but noticeable.', false, true, 14, '2025-11-15T00:00:00.000Z');
insert into public.reviews (product_id, author_name, rating, title, body, verified, seeded, helpful_count, created_at) values
  ('in-710zYiyB7XL', 'Aditya G.', 5, 'Great for beginners', 'As a beginner, I appreciate how stable and comfortable it feels. It has made learning new poses a lot less intimidating.', true, true, 203, '2026-07-19T00:00:00.000Z'),
  ('in-710zYiyB7XL', 'Ananya R.', 4, 'Just the right thickness', 'The thickness is just right for me, soft enough for my joints but firm enough for standing balance poses.', true, true, 183, '2025-10-25T00:00:00.000Z'),
  ('in-710zYiyB7XL', 'Kavya I.', 4, 'Stays put on the floor', 'The underside grips the floor well, even on smooth surfaces. No bunching or sliding during flowing sequences.', true, true, 213, '2025-12-06T00:00:00.000Z'),
  ('in-710zYiyB7XL', 'Siddharth J.', 5, 'Durable after months of use', 'Four months of daily practice and it has no tears, no flaking and no worn patches. It''s holding up really well.', true, true, 61, '2026-08-14T00:00:00.000Z'),
  ('in-710zYiyB7XL', 'Meera T.', 3, 'Good grip, slightly thin', 'The grip is excellent, but it feels a little thin for kneeling poses on a hard floor. I fold it over for extra padding when needed.', true, true, 7, '2025-09-15T00:00:00.000Z'),
  ('in-710zYiyB7XL', 'Amit H.', 4, 'Easy to keep clean', 'A quick wipe with a damp cloth after each session keeps it fresh. It dries fast and doesn''t hold onto sweat or smells.', true, true, 121, '2026-06-18T00:00:00.000Z'),
  ('in-710zYiyB7XL', 'Sneha P.', 2, 'Strong chemical smell', 'The smell was so strong that I couldn''t practice on it indoors. Airing it out for a week helped only slightly.', true, true, 13, '2026-05-17T00:00:00.000Z'),
  ('in-710zYiyB7XL', 'Neha C.', 3, 'Better for yoga than cardio', 'Great for yoga and stretching. For jumping or more intense workouts, it feels a bit too soft and less stable than I''d like.', true, true, 4, '2026-06-22T00:00:00.000Z'),
