  ('in-51izPGxd0SL', 'Vikram M.', 5, 'Helped me stay consistent', 'Having a comfortable mat ready at home has made me far more consistent than any gym membership ever did. I roll it out in the living room every morning and haven''t missed a session in three weeks. My back and shoulders feel so much better.', true, true, 198, '2025-07-08T00:00:00.000Z'),
  ('in-51izPGxd0SL', 'Arjun N.', 4, 'Excellent value', 'Great quality for what I paid. It feels more premium than the mats I used at my old studio.', true, true, 238, '2026-04-19T00:00:00.000Z'),
  ('in-51izPGxd0SL', 'Divya L.', 3, 'Initial smell faded', 'It had a noticeable smell for the first few days, which has now faded. Otherwise it''s comfortable and grippy.', true, true, 46, '2025-09-05T00:00:00.000Z'),
  ('in-51izPGxd0SL', 'Rohan D.', 4, 'A hit with my wife', 'Bought this for my wife, who just started yoga. She uses it every morning and says it''s much more comfortable than her old one.', true, true, 123, '2025-11-10T00:00:00.000Z'),
