  ('in-81yuVZ1RhiL', 'Ananya R.', 5, 'Good value for money', 'Excellent quality for what I paid. It feels like something that should cost more, and it has already outlasted some pricier toys.', true, true, 103, '2026-01-26T00:00:00.000Z'),
  ('in-81yuVZ1RhiL', 'Karthik V.', 4, 'Holds her attention', 'My daughter usually loses interest in new toys within days, but three weeks later she still keeps going back to this one.', true, true, 201, '2026-06-16T00:00:00.000Z'),
  ('in-81yuVZ1RhiL', 'Neha C.', 4, 'Not overly noisy', 'It isn''t loud or overly flashy, which I appreciate. My daughter can play happily in the living room while I work nearby.', true, true, 56, '2026-07-05T00:00:00.000Z'),
  ('in-81yuVZ1RhiL', 'Vikram M.', 5, 'Great learning value', 'My four-year-old is learning while she plays and doesn''t even realize it. I''ve noticed her picking up new words and ideas much faster lately.', true, true, 229, '2025-10-02T00:00:00.000Z'),
  ('in-81yuVZ1RhiL', 'Pooja B.', 3, 'Engaging but a bit loud', 'The kids adore it, though playtime can get noisy. Great for the playroom, not ideal for quiet evenings at home.', false, true, 6, '2026-04-21T00:00:00.000Z'),
  ('in-81yuVZ1RhiL', 'Amit H.', 4, 'Fun for the whole family', 'Even my husband and I end up joining in. It has become a regular part of our weekend evenings together, which I did not expect.', true, true, 163, '2026-01-13T00:00:00.000Z'),
  ('in-81yuVZ1RhiL', 'Priya S.', 2, 'Lost interest immediately', 'My daughter played with it for about ten minutes and never touched it again. It simply did not hold her attention.', true, true, 42, '2026-02-03T00:00:00.000Z'),
  ('in-81yuVZ1RhiL', 'Sneha P.', 3, 'Fun, but interest faded', 'My son loved it for the first week and played with it constantly. Now he picks it up only occasionally, but it was still worth buying.', true, true, 11, '2026-03-23T00:00:00.000Z'),
  ('in-918VkKHJgvL', 'Vikram M.', 5, 'Safe and well finished', 'The edges are smooth, everything feels solid and there was no strange smell out of the box. As a parent, that peace of mind matters a lot.', true, true, 53, '2026-03-13T00:00:00.000Z'),
  ('in-918VkKHJgvL', 'Amit H.', 5, 'Kept my kids busy for hours', 'My two kids played with this for an entire rainy afternoon without asking for a tablet once, and they were back at it before breakfast the next day. That alone makes it worth it for me, and it has been holding up well to their enthusiasm.', true, true, 17, '2026-03-09T00:00:00.000Z'),
  ('in-918VkKHJgvL', 'Pooja B.', 4, 'Holds her attention', 'My daughter usually loses interest in new toys within days, but three weeks later she still keeps going back to this one.', true, true, 226, '2026-02-27T00:00:00.000Z'),
  ('in-918VkKHJgvL', 'Sneha P.', 5, 'Fun for the whole family', 'Even my husband and I end up joining in. It has become a regular part of our weekend evenings together, which I did not expect.', true, true, 238, '2025-07-12T00:00:00.000Z'),
  ('in-918VkKHJgvL', 'Siddharth J.', 4, 'Easy to get started', 'It took a couple of minutes to get ready and my daughter was playing right away. No complicated instructions or fiddly setup.', true, true, 273, '2026-08-26T00:00:00.000Z'),
  ('in-918VkKHJgvL', 'Meera T.', 3, 'Mostly sturdy, some weak spots', 'Most of it feels sturdy, but a couple of spots seem fragile. Good for gentle play, less so for rough toddlers like mine.', true, true, 9, '2025-10-11T00:00:00.000Z'),
  ('in-918VkKHJgvL', 'Arjun N.', 4, 'Tough enough for toddlers', 'It has been dropped, thrown and chewed on by my toddler and still looks almost new. Built much tougher than I expected.', true, true, 236, '2026-04-24T00:00:00.000Z'),
  ('in-918VkKHJgvL', 'Kavya I.', 2, 'Not right for the listed age', 'Far too difficult for the age range on the box. My child got frustrated quickly and needed constant help to play with it.', false, true, 11, '2025-11-30T00:00:00.000Z'),
  ('in-71WasaFL9UL', 'Rahul K.', 5, 'Right for the age range', 'The age recommendation is spot on. My six-year-old finds it challenging enough to stay interested, but not so hard that she gets frustrated.', false, true, 260, '2026-08-06T00:00:00.000Z'),
